        private static void requirePsychoPayload(ItemStack stack,ServerPlayer player,boolean combined,String label) {
                String name=combined?"psychoblind_wand":"psycho_wand";
                var id=net.minecraft.resources.Identifier.parse(combined?"lbc:psychoblind":"lbc:psychowand");
                var tier=net.minecraft.resources.Identifier.parse(combined?"lbc:tier_s":"lbc:tier_c");
                require(stack.is(combined?LbcWands.PSYCHOBLIND:LbcWands.PSYCHOWAND) && stack.getCount()==1
                                && id.equals(stack.get(DataComponents.ITEM_MODEL)) && tier.equals(stack.get(DataComponents.TOOLTIP_STYLE))
                                && translation(stack.get(DataComponents.CUSTOM_NAME),name)!=null
                                && !stack.getHoverName().getStyle().isItalic(),label+" preserves source item, name, model and tier");
                var lore=stack.getOrDefault(DataComponents.LORE,net.minecraft.world.item.component.ItemLore.EMPTY).lines();
                require(lore.size()==(combined?4:10),label+" preserves source lore line count");
                int first=combined?2:4;
                String[] keys=combined?new String[]{"psychoblind_wand.lore.1","psychoblind_wand.lore.2"}
                                :new String[]{"psycho_wand.lore.1","psycho_wand.lore.2","psycho_wand.lore.3","psycho_wand.lore.4","psycho_wand.lore.5"};
                for(int i=1;i<=keys.length;i++) {
                        var line=lore.get(first+i-1);
                        translation(line,keys[i-1]);
                        require(!line.getStyle().isItalic()
                                        && net.minecraft.network.chat.TextColor.fromRgb(0xffffff).equals(line.getStyle().getColor()),
                                        label+" preserves white nonitalic source lore "+i);
                }
                if(!combined) require(translation(lore.get(9),"craft_with_blind")!=null,
                                label+" preserves Blind crafting instruction");
                var data=stack.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();
                require(data.getIntOr(combined?"psychoblind_wand":"psychowand",0)==1
                                && data.getIntOr("staff",0)==1 && data.getIntOr("magicwand",0)==1
                                && data.getIntOr("transformable",0)==1,label+" preserves source custom data");
                requirePolymerStack(player,stack,Items.CARROT_ON_A_STICK,label+" Polymer proxy");
        }

