                        game.maps().restoreSnapshot(beacon,oldBeacon); game.items().magic().blockChanged(beacon,level.getBlockState(beacon));
                        double x=(owner.blockPosition().getX()>>4)*16+8.5,z=(owner.blockPosition().getZ()>>4)*16+8.5;
