                        require(chaosTrident!=null && chaosTrident.getOwner()==owner
                                        && Math.abs(chaosTrident.getDeltaMovement().length()-7)<.0001
                                        && service.owner(chaosTrident)==owner,"Chaos launches native trident at speed seven with inherited owner");
                        chaosTrident.discard();
                        int expectedFangs=0;
                        for(var entity:level.getEntitiesOfClass(net.minecraft.world.entity.LivingEntity.class,chaos.getBoundingBox().inflate(50)))
                                if(entity.distanceToSqr(chaos)<=2500 && entity.distanceToSqr(chaos)>=2.25
                                                && game.items().wands().target(owner,entity)
                                                && !game.items().magic().suppressedAt(level,entity.position())
                                                && !entity.entityTags().contains("nomagic_active")) expectedFangs++;
                        service.chaosCast(owner,chaos,6);
                        int actualFangs=0;
                        for(var entity:level.getAllEntities()) if(!existingConsequences.contains(entity)
                                        && entity instanceof net.minecraft.world.entity.projectile.EvokerFangs fangs) {
                                require(fangs.getOwner()==owner && service.owner(fangs)==owner,"Chaos fangs retain real caster ownership");
                                actualFangs++;
                        }
                        require(actualFangs==9*Math.min(10,expectedFangs) && actualFangs>0,"Chaos creates nine native fangs per eligible enemy, up to ten enemies");
                        // Place the cow closer than the other player for a deterministic two-block trap.
                        chaosVictim.setPos(x,260,z+5);
                        var trapPos=chaosVictim.blockPosition();
                        changedBlocks.putIfAbsent(trapPos,game.maps().snapshot(trapPos));
