                        academy.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(endData)); mana.set(owner,2000);
                        target.setInvulnerableTime(0); target.damageCooldownTime=0; float hp=target.getHealth();
