        private static void checkPsycho(GameController game) {
                require(game.playing(),"Psycho runtime checks require a live match");
                var owner=game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(owner!=null && game.allowDamage(owner),"Psycho owner is active");
                var mana=game.items().mana(); var service=game.items().psycho(); var level=game.maps().level();
                var state=new WandThirdPlayerState(owner,mana);
                var cows=new java.util.ArrayList<net.minecraft.world.entity.animal.cow.Cow>();
                var mouseBlocks=new java.util.LinkedHashMap<net.minecraft.core.BlockPos,MapManager.BlockSnapshot>();
                var mouseShots=new java.util.ArrayList<net.minecraft.world.entity.projectile.throwableitemprojectile.Snowball>();
                boolean oldOffhand=game.config().offhandWands,oldShift=owner.isShiftKeyDown();
                var beaconPos=owner.blockPosition().offset(0,-2,0);
                var oldBeacon=game.maps().snapshot(beaconPos);
                try {
                        service.stop(); owner.closeContainer(); owner.getInventory().clearContent();
                        owner.setShiftKeyDown(false); game.config().offhandWands=false;
                        for(var slot:new net.minecraft.world.entity.EquipmentSlot[]{net.minecraft.world.entity.EquipmentSlot.HEAD,
                                        net.minecraft.world.entity.EquipmentSlot.CHEST,net.minecraft.world.entity.EquipmentSlot.LEGS,
                                        net.minecraft.world.entity.EquipmentSlot.FEET}) owner.setItemSlot(slot,ItemStack.EMPTY);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(LbcWands.PSYCHOWAND));
                        mana.set(owner,599);
                        require(!game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==599 && service.count()==0,
                                        "Psychowand rejects insufficient mana without creating effects");
                        // A real beacon exercises the common native suppression path before any effects exist.
                        level.setBlockAndUpdate(beaconPos,LbcMagic.MAGIC_BEACON_BLOCK.defaultBlockState());
                        game.items().magic().blockChanged(beaconPos,level.getBlockState(beaconPos));
                        mana.set(owner,2000);
                        require(!game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==2000 && service.count()==0,
                                        "Native antimagic beacon rejects Psychowand without mana loss");
                        game.maps().restoreSnapshot(beaconPos,oldBeacon);
                        game.items().magic().blockChanged(beaconPos,level.getBlockState(beaconPos));
                        int x=(owner.blockPosition().getX()>>4)*16+8,z=(owner.blockPosition().getZ()>>4)*16+8;
                        owner.setNoGravity(true);
                        owner.teleportTo(level,x+.5,260,z+.5,java.util.Set.of(),0,0,true);
                        var victim=frostProbeCow(level,cows,x+.5,260,z+8.5);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(LbcWands.PSYCHOBLIND));
                        mana.set(owner,499);
                        require(!game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==499 && service.count()==0,
                                        "Psychoblind rejects below its separate 500 mana threshold");
                        mana.set(owner,1000);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==500 && !service.snapshot().isEmpty(),
                                        "Psychoblind launches an active native charge and spends exactly 500");
                        var shot=service.snapshot().getFirst();
                        require(service.snapshot().stream().allMatch(charge->charge.getOwner()==owner
                                        && game.items().currentEpoch(charge)),
                                        "Every Psychoblind charge retains its caster and current match epoch");
                        for(var other:service.snapshot()) if(other!=shot) other.discard();
                        float health=victim.getHealth();
                        var protectedNpc=frostProbeCow(level,cows,victim.getX(),victim.getY(),victim.getZ());
                        protectedNpc.entityTags().add("magic_academy");
                        float npcHealth=protectedNpc.getHealth();
                        shot.setPos(victim.position().add(0,.5,0));
                        shot.setDeltaMovement(new net.minecraft.world.phys.Vec3(0,0,.1));
                        service.tick();
                        require(victim.getHealth()<health && victim.getLastDamageSource()!=null
                                        && victim.getLastDamageSource().getEntity()==owner
                                        && victim.hasEffect(net.minecraft.world.effect.MobEffects.DARKNESS)
                                        && service.effectValue(victim,"scared")>0 && service.effectValue(victim,"lookback")>0
                                        && service.effectValue(victim,"twitching")>0 && shot.isRemoved(),
                                        "Real charge contact damages and applies Darkness plus the three mental effects");
                        require(protectedNpc.getHealth()==npcHealth && service.effectValue(protectedNpc,"scared")==0
                                        && !protectedNpc.hasEffect(net.minecraft.world.effect.MobEffects.DARKNESS),
                                        "The same real charge sweep excludes a protected Academy NPC");
                        protectedNpc.discard();
                        for(int tick=0;tick<80;tick++) service.tick();
                        require(service.effectCount()==0,"Mob mental counters expire fully without immortal Twitch entries");
                        service.stop();
                        require(service.count()==0 && service.effectCount()==0,
                                        "Psycho stop clears charges and deferred effects");
                        game.config().offhandWands=true;
                        for(var academy:new net.minecraft.world.item.Item[]{LbcWands.ACADEMY_PSYCHOWAND,LbcWands.ACADEMY_PSYCHOBLIND}) {
                                var offhand=new ItemStack(academy); var data=new net.minecraft.nbt.CompoundTag();
                                data.putInt("mode",1); data.putInt("upgraded",1);
                                offhand.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));
                                owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,offhand);
                                var main=owner.getMainHandItem().copy();
                                owner.setShiftKeyDown(true); mana.set(owner,2000);
                                for(int expected:new int[]{2,3,4,1}) {
                                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.OFF_HAND)
                                                        && mana.get(owner)==2000
                                                        && offhand.get(DataComponents.CUSTOM_DATA).copyTag().getIntOr("mode",0)==expected,
                                                        "Academy used-hand mode cycles and wraps freely: "+expected);
                                }
                                require(ItemStack.isSameItemSameComponents(main,owner.getMainHandItem()),
                                                "Academy offhand mode cycling preserves the main hand");
                        }
                        owner.setShiftKeyDown(false);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);
                        for(int mode:new int[]{4,3}) {
                                var wand=new ItemStack(LbcWands.ACADEMY_PSYCHOBLIND); var data=new net.minecraft.nbt.CompoundTag();
                                data.putInt("mode",mode); data.putInt("upgraded",1);
                                wand.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));
                                owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,wand);
                                mana.set(owner,1000);
                                require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                                && mana.get(owner)==500 && !service.snapshot().isEmpty(),
                                                "Academy Psychoblind mode launches at its source cost: "+mode);
                                require(service.snapshot().stream().allMatch(charge->charge.getOwner()==owner
                                                && (mode==4?charge.invisible:charge.spray)),
                                                "Academy mode carries its invisible/spray behavior on real owned charges");
                                service.stop();
                        }
                        var rayWand=new ItemStack(LbcWands.ACADEMY_PSYCHOBLIND); var rayData=new net.minecraft.nbt.CompoundTag();
                        rayData.putInt("mode",2); rayData.putInt("upgraded",1);
                        rayWand.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(rayData));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,rayWand);
                        victim.setPos(x+.5,260,z+8.5); victim.setHealth(10); victim.setInvulnerableTime(0);
                        var followRange=victim.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.FOLLOW_RANGE);
                        require(followRange!=null,"Mindray mob fixture exposes the native follow-range attribute");
                        followRange.setBaseValue(19);
                        var rayNpc=frostProbeCow(level,cows,x+1.5,260,z+8.5); rayNpc.entityTags().add("magic_academy");
                        var suppressed=frostProbeCow(level,cows,x-1.5,260,z+8.5); suppressed.entityTags().add("nomagic_active");
                        var ally=frostProbeCow(level,cows,x+.5,260,z+10.5);
                        var board=game.server().getScoreboard(); var oldTeam=owner.getTeam();
                        var team=board.addPlayerTeam("codex_psycho");
                        board.addPlayerToTeam(owner.getScoreboardName(),team); board.addPlayerToTeam(ally.getScoreboardName(),team);
                        try {
                                mana.set(owner,1000);
                                require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                                && service.rayCount(owner)==40 && service.snapshot().isEmpty(),
                                                "Mindray queues exactly forty ticks without a projectile");
                                service.tick();
                                require(service.rayCount(owner)==39 && service.effectValue(victim,"scared")==1
                                                && service.effectValue(victim,"lookback")==1 && service.effectValue(victim,"piss")==1,
                                                "Wide Mindray applies mental effects once per target in its first tick");
                                for(var excluded:java.util.List.of(rayNpc,suppressed))
                                        require(service.effectValue(excluded,"scared")==0
                                                        && service.effectValue(excluded,"lookback")==0
                                                        && excluded.getHealth()==10,
                                                        "Mindray excludes service NPC and antimagic targets");
                                require(service.effectValue(ally,"scared")==1 && service.effectValue(ally,"lookback")==1
                                                && ally.getHealth()<10,"Mindray can affect allied mobs under the author projectile rule");
                                for(int tick=1;tick<40;tick++) service.tick();
                                require(service.rayCount(owner)==0,"Mindray ends after exactly forty service ticks");
                        } finally {
                                board.removePlayerFromTeam(owner.getScoreboardName());
                                board.removePlayerFromTeam(ally.getScoreboardName()); board.removePlayerTeam(team);
                                if(oldTeam!=null) board.addPlayerToTeam(owner.getScoreboardName(),oldTeam);
                                service.stop();
                        }
                        require(followRange.getBaseValue()==19,"Mindray expiry and stop restore the mob's original follow range");
                        rayNpc.discard(); suppressed.discard(); ally.discard();
                        victim.setPos(x+.5,260,z+8.5); victim.setHealth(1); victim.setInvulnerableTime(0);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(LbcWands.PSYCHOWAND));
                        mana.set(owner,600);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==0 && !victim.isAlive() && victim.getKillCredit()==owner,
                                        "Psychowand executes a below-two-HP enemy with native caster kill credit");
                        var ghosts=level.getEntitiesOfClass(net.minecraft.world.entity.monster.Vex.class,
                                        owner.getBoundingBox().inflate(32),vex->game.items().currentEpoch(vex) && vex.hasCustomName());
                        require(ghosts.size()==1 && ghosts.getFirst().getHealth()==2_000_000_000f
                                        && ghosts.getFirst().getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).getBaseValue()==2_000_000_000,
                                        "Execution creates the original hostile ghost with two-billion health and max-health");
                        var ghostVictim=frostProbeCow(level,cows,x+2.5,260,z+8.5); ghostVictim.setHealth(.25f);
                        require(ghosts.getFirst().canAttack(owner) && ghosts.getFirst().doHurtTarget(level,ghostVictim)
                                        && !ghostVictim.isAlive() && ghostVictim.getKillCredit()==owner,
                                        "Hostile execution ghost can target its caster and native lethal melee credits its summoner");
                        service.stop();
                        require(ghosts.getFirst().isRemoved(),"Psycho stop removes execution ghosts too");
                        // Twitch calls this same native input bridge; verify real use and combat behavior without random rolls.
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SNOWBALL,3));
                        owner.setYRot(0); owner.setXRot(-60);
                        var beforeSnowballs=new java.util.HashSet<java.util.UUID>();
                        for(var entity:level.getAllEntities()) if(entity.getType()==net.minecraft.world.entity.EntityTypes.SNOWBALL)
                                beforeSnowballs.add(entity.getUUID());
                        game.items().mouseAction(owner,false);
                        for(var entity:level.getAllEntities()) if(entity instanceof net.minecraft.world.entity.projectile.throwableitemprojectile.Snowball snowball
                                        && !beforeSnowballs.contains(entity.getUUID())) mouseShots.add(snowball);
                        require(owner.getMainHandItem().getCount()==2 && mouseShots.size()==1 && mouseShots.getFirst().getOwner()==owner,
                                        "Twitch native right click consumes one vanilla snowball and launches it with the player owner");
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));
                        owner.setXRot(15);
                        var meleeVictim=frostProbeCow(level,cows,x+.5,260,z+2.5); float meleeHealth=meleeVictim.getHealth();
                        game.items().mouseAction(owner,true);
                        require(meleeVictim.getHealth()<meleeHealth && meleeVictim.getLastDamageSource()!=null
                                        && meleeVictim.getLastDamageSource().getEntity()==owner,
                                        "Twitch native left click performs player melee with normal damage attribution");
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BUCKET));
                        game.items().mouseAction(owner,false);
                        require(owner.getMainHandItem().is(Items.MILK_BUCKET) && owner.getMainHandItem().getCount()==1,
                                        "Twitch native entity interaction milks an adult cow and replaces the bucket");
                        meleeVictim.discard();
                        owner.setXRot(0);
                        var support=new net.minecraft.core.BlockPos(x,261,z+3); var placed=support.north();
                        mouseBlocks.put(support,game.maps().snapshot(support)); mouseBlocks.put(placed,game.maps().snapshot(placed));
                        level.setBlockAndUpdate(support,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
                        level.setBlockAndUpdate(placed,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.DIRT,3));
                        game.items().mouseAction(owner,false);
                        require(level.getBlockState(placed).is(net.minecraft.world.level.block.Blocks.DIRT)
                                        && owner.getMainHandItem().getCount()==2,
                                        "Twitch native block interaction places one dirt block and consumes exactly one item");
                        for(var entry:mouseBlocks.entrySet()) game.maps().restoreSnapshot(entry.getKey(),entry.getValue());
                        owner.setXRot(-60);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.EMPTY);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.SNOWBALL,3));
                        beforeSnowballs.clear();
                        for(var entity:level.getAllEntities()) if(entity.getType()==net.minecraft.world.entity.EntityTypes.SNOWBALL)
                                beforeSnowballs.add(entity.getUUID());
                        game.items().mouseAction(owner,false);
                        int offhandShots=0;
                        for(var entity:level.getAllEntities()) if(entity instanceof net.minecraft.world.entity.projectile.throwableitemprojectile.Snowball snowball
                                        && !beforeSnowballs.contains(entity.getUUID())) { mouseShots.add(snowball); offhandShots++; }
                        require(owner.getMainHandItem().isEmpty() && owner.getOffhandItem().getCount()==2 && offhandShots==1,
                                        "Empty main hand falls through to one normal offhand snowball use");
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SNOWBALL,3));
                        var frost=game.items().frost();
                        try {
                                for(int i=0;i<10;i++) frost.add(owner,null);
                                require(frost.isFrozen(owner),"Twitch frozen fixture reaches the action lock");
                                game.items().mouseAction(owner,false);
                                require(owner.getMainHandItem().getCount()==3,"Frozen players cannot consume a forced-use item");
                        } finally { frost.clear(owner); }
                        // Academy's real base trial supplies Twitching; a bow without ammunition after start prevents random re-use.
                        var trialWand=new ItemStack(LbcWands.PSYCHOBLIND); var trialData=new net.minecraft.nbt.CompoundTag();
                        trialData.putInt("upgradable",1);
                        trialWand.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(trialData));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,trialWand);
                        owner.setShiftKeyDown(true); mana.set(owner,500);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && service.effectValue(owner,"twitching")>0,
                                        "Native Psychoblind trial supplies the forced-hold Twitching fixture");
                        owner.setShiftKeyDown(false);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));
                        owner.getInventory().setItem(20,new ItemStack(Items.ARROW));
                        service.twitchClick(owner,false);
                        int heldTicks=service.forcedUseTicks(owner);
                        require(owner.isUsingItem() && heldTicks>=2 && heldTicks<=20,
                                        "Twitch starts a native bow use and owns a random hold from two to twenty ticks");
                        owner.getInventory().setItem(20,ItemStack.EMPTY);
                        // Keep the use stack intact while making a later random bow click unable to start another hold.
                        for(int tick=0;tick<heldTicks;tick++) service.tick();
                        require(!owner.isUsingItem() && service.forcedUseTicks(owner)==0,
                                        "The synthetic bow hold releases through native item use at its bounded deadline");
                        service.stop();
                        owner.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);
                        service.stop();
                        require(owner.isUsingItem(),"Psycho cleanup leaves a manually started use active");
                        owner.stopUsingItem();
                        // Reapply through the same native trial, then replace its use with an unrelated offhand use.
                        trialWand=new ItemStack(LbcWands.PSYCHOBLIND); trialData=new net.minecraft.nbt.CompoundTag();
                        trialData.putInt("upgradable",1);
                        trialWand.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(trialData));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,trialWand);
                        owner.setShiftKeyDown(true); mana.set(owner,500);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND),
                                        "A fresh native trial supports the synthetic-use ownership fixture");
                        owner.setShiftKeyDown(false);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));
                        owner.getInventory().setItem(20,new ItemStack(Items.ARROW));
                        service.twitchClick(owner,false);
                        require(service.forcedUseTicks(owner)>=2,"The second synthetic bow use is tracked");
                        owner.stopUsingItem();
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.BOW));
                        owner.startUsingItem(net.minecraft.world.InteractionHand.OFF_HAND);
                        service.stop();
                        require(owner.isUsingItem() && owner.getUsedItemHand()==net.minecraft.world.InteractionHand.OFF_HAND,
                                        "Cleanup never releases an unrelated replacement stack or hand");
                        owner.stopUsingItem();
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SNOWBALL,3));
                        var previousMode=owner.gameMode.getGameModeForPlayer();
                        try {
                                game.spectators().enter(owner);
                                owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SNOWBALL,3));
                                require(game.isObserver(owner) && owner.gameMode.getGameModeForPlayer()==GameType.ADVENTURE,
                                                "Twitch observer fixture uses the native role while in Adventure");
                                game.items().mouseAction(owner,false);
                                require(owner.getMainHandItem().getCount()==3,"Observers cannot consume a forced-use item");
                        } finally { game.spectators().remove(owner); owner.setGameMode(previousMode); }
                        SkyWars2.LOGGER.info("[check] PASS psycho");
                } finally {
                        service.stop();
                        for(var entry:mouseBlocks.entrySet()) game.maps().restoreSnapshot(entry.getKey(),entry.getValue());
                        for(var snowball:mouseShots) snowball.discard();
                        for(var cow:cows) cow.discard();
                        game.maps().restoreSnapshot(beaconPos,oldBeacon);
                        game.items().magic().blockChanged(beaconPos,level.getBlockState(beaconPos));
                        game.config().offhandWands=oldOffhand; owner.setShiftKeyDown(oldShift); state.restore(game);
                }
        }

        private static void checkPsychoCleanup(GameController game) {
                require(game.inLobby() && game.items().psycho().count()==0 && game.items().psycho().effectCount()==0,
                                "Psycho charges and deferred effects clear after match stop");
                SkyWars2.LOGGER.info("[check] PASS psycho-cleanup");
        }

        private static void checkFireblazeCrafting(GameController game) {
                require(game.playing(),"Fireblaze recipe checks require a live match");
                var player=game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player!=null && game.allowDamage(player),"Fireblaze crafting participant is active");
                var state=new WandThirdPlayerState(player,game.items().mana());
                var tablePos=player.blockPosition().offset(1,0,0);
                var oldTable=game.maps().snapshot(tablePos); boolean openedTable=false;
                var fixtures=java.util.List.of(
                                new Object[]{"native Fire + native Blaze Wand",new ItemStack(LbcWands.FIRE_WAND),new ItemStack(LbcWands.BLAZE_WAND)},
                                new Object[]{"native Fire + legacy fallingstars",new ItemStack(LbcWands.FIRE_WAND),legacyFireblazeDonor("fallingstars",Items.CARROT_ON_A_STICK)},
                                new Object[]{"Academy Fire + native Blaze Wand",new ItemStack(LbcWands.ACADEMY_FIRE),new ItemStack(LbcWands.BLAZE_WAND)},
                                new Object[]{"Academy Fire + legacy fallingstars",new ItemStack(LbcWands.ACADEMY_FIRE),legacyFireblazeDonor("fallingstars",Items.CARROT_ON_A_STICK)},
                                new Object[]{"legacy stfire + native Blaze Wand",legacyFireblazeDonor("stfire",Items.CARROT_ON_A_STICK),new ItemStack(LbcWands.BLAZE_WAND)},
                                new Object[]{"legacy stfire + legacy fallingstars",legacyFireblazeDonor("stfire",Items.CARROT_ON_A_STICK),legacyFireblazeDonor("fallingstars",Items.CARROT_ON_A_STICK)});
                try {
                        player.closeContainer(); player.getInventory().clearContent();
                        var menu=player.inventoryMenu; var grid=menu.getCraftSlots();
                        for(var fixture:fixtures) {
                                var first=(ItemStack)fixture[1]; var second=(ItemStack)fixture[2];
                                grid.clearContent(); menu.setCarried(ItemStack.EMPTY);
                                grid.setItem(0,first.copyWithCount(2)); grid.setItem(3,second.copyWithCount(2));
                                int activeBefore=game.items().blaze().count();
                                requireFireblazeCraftResult(menu.getResultSlot().getItem(),player,(String)fixture[0]+" 2x2 preview");
                                require(LbcCraftingRecipe.craftingKind(grid.asCraftInput())==LbcCraftingRecipe.Kind.FIREBLAZE,
                                                fixture[0]+" matches the Fireblaze recipe");
                                require(grid.getItem(0).getCount()==2 && grid.getItem(3).getCount()==2
                                                && game.items().blaze().count()==activeBefore,
                                                fixture[0]+" preview does not consume inputs or create active effects");
                                grid.setItem(1,new ItemStack(Items.STONE));
                                require(menu.getResultSlot().getItem().isEmpty(),fixture[0]+" rejects extra 2x2 ingredients");
                                grid.setItem(1,ItemStack.EMPTY);
                                inventoryClick(player,0,0,ContainerInput.PICKUP);
                                requireFireblazeCraftResult(menu.getCarried(),player,(String)fixture[0]+" 2x2 take");
                                require(grid.getItem(0).getCount()==1 && grid.getItem(3).getCount()==1,
                                                fixture[0]+" take consumes exactly one of each ingredient");
                        }
                        game.maps().level().setBlockAndUpdate(tablePos,net.minecraft.world.level.block.Blocks.CRAFTING_TABLE.defaultBlockState());
                        player.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,owner)->
                                        new net.minecraft.world.inventory.CraftingMenu(id,inventory,
                                                        net.minecraft.world.inventory.ContainerLevelAccess.create(game.maps().level(),tablePos)),
                                        Component.translatable("container.crafting")));
                        openedTable=true;
                        var table=(net.minecraft.world.inventory.CraftingMenu)player.containerMenu;
                        var inputs=table.getInputGridSlots();
                        inputs.get(0).setByPlayer(new ItemStack(LbcWands.BLAZE_WAND,2));
                        inputs.get(8).setByPlayer(new ItemStack(LbcWands.FIRE_WAND,2));
                        int activeBefore=game.items().blaze().count();
                        requireFireblazeCraftResult(table.getResultSlot().getItem(),player,"3x3 preview");
                        require(inputs.get(0).getItem().getCount()==2 && inputs.get(8).getItem().getCount()==2
                                        && game.items().blaze().count()==activeBefore,"3x3 preview has no consumption or active effects");
                        inputs.get(4).setByPlayer(new ItemStack(Items.STONE));
                        require(table.getResultSlot().getItem().isEmpty(),"3x3 Fireblaze recipe rejects extra ingredients");
                        inputs.get(4).setByPlayer(ItemStack.EMPTY);
                        inventoryClick(player,0,0,ContainerInput.PICKUP);
                        requireFireblazeCraftResult(table.getCarried(),player,"3x3 take");
                        require(inputs.get(0).getItem().getCount()==1 && inputs.get(8).getItem().getCount()==1,
                                        "3x3 take consumes exactly one of each ingredient");
                        SkyWars2.LOGGER.info("[check] PASS fireblaze-crafting");
                } finally {
                        if(openedTable) player.closeContainer();
                        game.maps().restoreSnapshot(tablePos,oldTable); state.restore(game);
                }
        }

        private static void checkFireblazeWand(GameController game) {
                require(game.playing(),"Blaze runtime checks require a live match");
                var owner=game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(owner!=null && game.allowDamage(owner),"Blaze owner is an active participant");
                var mana=game.items().mana(); var service=game.items().blaze(); var level=game.maps().level();
                var originalLoot=fixtureLootBefore(level);
                var state=new WandThirdPlayerState(owner,mana);
                var cows=new java.util.ArrayList<net.minecraft.world.entity.animal.cow.Cow>();
                var testBlazes=new java.util.ArrayList<net.minecraft.world.entity.monster.Blaze>();
                var board=game.server().getScoreboard(); var oldTeam=owner.getTeam();
                var team=board.getPlayerTeam("codex_blaze"); boolean createdTeam=team==null;
                if(createdTeam) team=board.addPlayerTeam("codex_blaze");
                int x=(owner.blockPosition().getX()>>4)*16+8,z=(owner.blockPosition().getZ()>>4)*16+8;
                var obstacle=new net.minecraft.core.BlockPos(x,261,z+10);
                var oldBlock=game.maps().snapshot(obstacle);
                boolean oldOffhand=game.config().offhandWands;
                var spawned=new java.util.ArrayList<net.minecraft.world.entity.projectile.Projectile>();
                var protectedTags=new java.util.IdentityHashMap<net.minecraft.world.entity.Entity,java.util.Set<String>>();
                for(var entity:level.getAllEntities()) if(entity!=owner) {
                        var tags=entity.entityTags();
                        protectedTags.put(entity,new java.util.HashSet<>(tags));
                        // LbcWands recognizes magic_academy; retain the explicit fixture marker too.
                        tags.add("protectedmagic_academy"); tags.add("magic_academy");
                }
                var changedBlocks=new java.util.LinkedHashMap<net.minecraft.core.BlockPos,MapManager.BlockSnapshot>();
                var before=new java.util.HashSet<java.util.UUID>();
                for(var entity:level.getAllEntities()) before.add(entity.getUUID());
                java.util.function.Supplier<java.util.List<net.minecraft.world.entity.projectile.Projectile>> fresh=()-> {
                        var list=new java.util.ArrayList<net.minecraft.world.entity.projectile.Projectile>();
                        for(var entity:level.getAllEntities()) if(entity instanceof net.minecraft.world.entity.projectile.Projectile p
                                        && !before.contains(p.getUUID()) && game.items().wands().isFireProjectile(p)) list.add(p);
                        return list;
                };
                net.minecraft.world.entity.Interaction academyNpc=null;
                try {
                        service.stop(); owner.closeContainer(); owner.getInventory().clearContent(); owner.setNoGravity(true);
                        owner.teleportTo(level,x+.5,260,z+.5,java.util.Set.of(),0,0,true);
                        game.config().offhandWands=false;
                        board.addPlayerToTeam(owner.getScoreboardName(),team);
                        var victim=frostProbeCow(level,cows,x+4.5,260,z+.5);
                        var ally=frostProbeCow(level,cows,x-4.5,260,z+.5);
                        var npc=frostProbeCow(level,cows,x+.5,260,z-4.5); npc.entityTags().add("magic_academy");
                        board.addPlayerToTeam(ally.getScoreboardName(),team);
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(LbcWands.FIREBLAZE));
                        mana.set(owner,49);
                        require(!game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND) && fresh.get().isEmpty(),
                                        "Fireblaze rejects a cast below 50 mana without spawning");
                        mana.set(owner,100);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND) && mana.get(owner)==50,
                                        "Fireblaze spends 50 once for its whole volley");
                        var volley=fresh.get();
                        require(volley.size()==1,"One nearby enemy creates one Fireblaze shot; ally and academy NPC are excluded");
                        var shot=volley.getFirst(); spawned.addAll(volley);
                        require(shot.getOwner()==owner && game.items().wands().canHit(shot,victim)
                                        && game.items().wands().canHit(shot,ally) && !game.items().wands().canHit(shot,npc),
                                        "Fireblaze aims at enemies, can physically hit friendly mobs and protects service NPC");
                        var velocity=shot.getDeltaMovement();
                        require(velocity.dot(victim.position().add(0,1,0).subtract(shot.position()))>0,
                                        "Random Fireblaze projectile is already directed toward its target on spawn");
                        for(var entity:volley) entity.discard();
                        victim.discard(); ally.discard(); npc.discard();
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(LbcWands.BLAZE_WAND));
                        level.setBlockAndUpdate(obstacle,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
                        mana.set(owner,2799);
                        require(!game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND) && service.turretCount()==0,
                                        "Blaze Wand rejects activation below 2800");
                        mana.set(owner,2800);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND) && mana.get(owner)==0
                                        && service.turretCount()==1,"Blaze Wand creates exactly one turret at the first wall");
                        for(int i=0;i<100;i++) service.tick();
                        require(service.turretCount()==0,"Blaze turret completes five one-second pulses without marker accumulation");
                        var head=new ItemStack(LbcWands.ACADEMY_BLAZE);
                        var data=new net.minecraft.nbt.CompoundTag(); data.putInt("mode",2); data.putInt("upgraded",1);
                        head.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,head); mana.set(owner,5600);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==2800 && service.headCharges(owner)==7,
                                        "Academy Blaze head spends 2800 and adds seven automatic charges");
                        require(game.items().hud(owner).getString().contains("\uE110"),"Blaze head uses its original actionbar icon");
                        owner.entityTags().add("time_stopped");
                        for(int i=0;i<10;i++) service.tick();
                        require(service.headCharges(owner)==7,"Paused Blaze head preserves pending shots");
                        owner.entityTags().remove("time_stopped");
                        for(int i=0;i<10;i++) service.tick();
                        require(service.headCharges(owner)==6 && mana.get(owner)==2800,"Blaze head fires every ten ticks without another mana payment");
                        game.items().clearEffects(owner);
                        require(service.headCharges(owner)==0,"Full effect cleanser also removes the custom Blaze head status");

                        // Run the source Fireblaze trial and its Academy promotion through actual callbacks.
                        academyNpc=new net.minecraft.world.entity.Interaction(net.minecraft.world.entity.EntityTypes.INTERACTION,level);
                        academyNpc.setPos(owner.position()); academyNpc.entityTags().add("magic_academy");
                        require(level.addFreshEntity(academyNpc),"Fireblaze mock Academy NPC enters the fixture");
                        var fireTrial=new ItemStack(LbcWands.FIREBLAZE);
                        var fireTrialData=new net.minecraft.nbt.CompoundTag(); fireTrialData.putInt("fireblaze_wand",1);
                        fireTrialData.putInt("upgradable",1);
                        fireTrial.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(fireTrialData));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,fireTrial);
                        var trialVictim=frostProbeCow(level,cows,x+4.5,260,z+.5);
                        for(int distance:new int[]{30,40,60,70,90,100,120,130,150}) {
                                level.getChunk((x+distance)>>4,z>>4); level.getChunk((x-distance)>>4,z>>4);
                                level.getChunk(x>>4,(z+distance)>>4); level.getChunk(x>>4,(z-distance)>>4);
                        }
                        owner.setShiftKeyDown(true); mana.set(owner,50);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND) && mana.get(owner)==0,
                                        "Fireblaze Academy trial is a paid native cast");
                        var trialShots=fresh.get(); spawned.addAll(trialShots);
                        var trialFireballs=trialShots.stream().filter(p->p instanceof net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball
                                        && p.entityTags().contains(LbcBlaze.TRIAL_PROJECTILE))
                                        .map(p->(net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball)p).toList();
                        var powers=trialFireballs.stream().map(GameChecks::fireballPower).sorted().toList();
                        require(trialFireballs.size()==14 && powers.equals(java.util.stream.IntStream.rangeClosed(1,14).boxed().toList())
                                        && trialFireballs.stream().allMatch(p->p.getOwner()==owner
                                                && game.items().wands().canHit(p,owner) && game.items().currentEpoch(p)),
                                        "Fireblaze trial launches fourteen source-power LargeFireballs with owner attribution and trial self-hit; powers="+powers);
                        readyForItemDamage(owner);
                        float trialHealth=owner.getHealth();
                        require(owner.hurtServer(level,level.damageSources().fireball(trialFireballs.getFirst(),owner),1)
                                        && owner.getHealth()<trialHealth,
                                        "Owned trial fireball actually damages its caster through the native same-team PvP gate");
                        var fireReady=fireTrial.get(DataComponents.CUSTOM_DATA).copyTag();
                        require(fireReady.getIntOr("upgrade_available",0)==1 && fireReady.getIntOr("upgradable",1)==0,
                                        "Fourteen-hit Fireblaze trial immediately marks the held wand upgrade-ready");
                        require(game.items().academy().interact(owner,net.minecraft.world.InteractionHand.MAIN_HAND,academyNpc),
                                        "Fireblaze Academy NPC consumes the ready upgrade interaction");
                        var academyFire=owner.getMainHandItem(); var academyFireData=academyFire.get(DataComponents.CUSTOM_DATA).copyTag();
                        var academyLore=academyFire.getOrDefault(DataComponents.LORE,net.minecraft.world.item.component.ItemLore.EMPTY).lines();
                        require(academyFire.is(LbcWands.ACADEMY_FIREBLAZE) && academyFireData.getIntOr("fireblaze_wand",0)==1
                                        && academyFireData.getIntOr("upgraded",0)==1 && academyFireData.getIntOr("mode",0)==1
                                        && academyFireData.getIntOr("upgrade_available",0)==1
                                        && net.minecraft.resources.Identifier.parse("lbc:tier_s").equals(academyFire.get(DataComponents.TOOLTIP_STYLE))
                                        && translation(academyLore.getLast(),"upgraded_item")!=null
                                        && academyLore.getLast().getStyle().getColor().equals(
                                                net.minecraft.network.chat.TextColor.fromLegacyFormat(net.minecraft.ChatFormatting.GREEN)),
                                        "NPC promotion preserves Fireblaze flags, tier S, mode 1 and green upgraded lore");
                        for(var entity:trialShots) entity.discard(); spawned.removeAll(trialShots);
                        trialVictim.discard();

                        // Cycle every mode using the offhand stack and leave the main hand unchanged.
                        owner.setShiftKeyDown(true); game.config().offhandWands=true; mana.set(owner,1000);
                        var offhandAcademy=academyFire.copy(); owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,offhandAcademy);
                        var unchangedMain=academyFire.get(DataComponents.CUSTOM_DATA).copyTag();
                        for(int expected:new int[]{2,3,4,1})
                                require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.OFF_HAND)
                                                && offhandAcademy.get(DataComponents.CUSTOM_DATA).copyTag().getIntOr("mode",0)==expected
                                                && mana.get(owner)==1000,
                                                "Academy Fireblaze cycles used-hand mode "+expected+" without mana");
                        require(academyFire.get(DataComponents.CUSTOM_DATA).copyTag().equals(unchangedMain),
                                        "Offhand mode cycling leaves main-hand Academy Fireblaze unchanged");
                        owner.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,ItemStack.EMPTY);
                        owner.setShiftKeyDown(false); game.config().offhandWands=false;

                        // World mode searches valid targets beyond the ordinary 30-block radius.
                        var distant=frostProbeCow(level,cows,x+.5,300,z+.5);
                        academyFireData=academyFire.get(DataComponents.CUSTOM_DATA).copyTag(); academyFireData.putInt("mode",1);
                        academyFire.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(academyFireData));
                        mana.set(owner,50);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND) && mana.get(owner)==0,
                                        "Academy world mode charges once for its global target pass");
                        var worldShots=fresh.get(); spawned.addAll(worldShots);
                        require(worldShots.size()==1 && worldShots.getFirst().getOwner()==owner
                                        && game.items().wands().canHit(worldShots.getFirst(),distant)
                                        && !game.items().wands().canHit(worldShots.getFirst(),owner),
                                        "Academy world mode targets one enemy more than 30 blocks away and protects its caster");
                        for(var entity:worldShots) entity.discard(); spawned.removeAll(worldShots); distant.discard();

                        // Mega is one native owned LargeFireball with source ExplosionPower 5.
                        var megaVictim=frostProbeCow(level,cows,x+4.5,260,z+.5);
                        academyFireData=academyFire.get(DataComponents.CUSTOM_DATA).copyTag(); academyFireData.putInt("mode",2);
                        academyFire.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(academyFireData));
                        mana.set(owner,50);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND),"Academy Fireblaze Mega mode dispatches");
                        var megaShots=fresh.get(); spawned.addAll(megaShots);
                        var megaFireballs=megaShots.stream().filter(p->p instanceof net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball)
                                        .map(p->(net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball)p).toList();
                        require(megaFireballs.size()==1 && fireballPower(megaFireballs.getFirst())==5
                                        && megaFireballs.getFirst().getOwner()==owner
                                        && game.items().wands().canHit(megaFireballs.getFirst(),megaVictim)
                                        && !game.items().wands().canHit(megaFireballs.getFirst(),owner),
                                        "Academy Mega mode creates one owned native power-five LargeFireball");
                        for(var entity:megaShots) entity.discard(); spawned.removeAll(megaShots); megaVictim.discard();

                        // Predict the single native Pillars column, snapshot its full 0..319 range, then drain it.
                        var pillarVictim=frostProbeCow(level,cows,x+4.5,260,z+.5);
                        academyFireData=academyFire.get(DataComponents.CUSTOM_DATA).copyTag(); academyFireData.putInt("mode",3);
                        academyFire.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(academyFireData));
                        long pillarSeed=0xB1A2E5L; owner.getRandom().setSeed(pillarSeed);
                        var expectedPillarRandom=net.minecraft.util.RandomSource.create(pillarSeed);
                        int pillarX=expectedPillarRandom.nextInt(61)-30,pillarZ=expectedPillarRandom.nextInt(61)-30;
                        var pillarBase=net.minecraft.core.BlockPos.containing(pillarVictim.position().add(0,1,0)).offset(pillarX,0,pillarZ);
                        int minPillarChunkX=(pillarVictim.blockPosition().getX()-31)>>4;
                        int maxPillarChunkX=(pillarVictim.blockPosition().getX()+31)>>4;
                        int minPillarChunkZ=(pillarVictim.blockPosition().getZ()-31)>>4;
                        int maxPillarChunkZ=(pillarVictim.blockPosition().getZ()+31)>>4;
                        for(int cx=minPillarChunkX;cx<=maxPillarChunkX;cx++)
                                for(int cz=minPillarChunkZ;cz<=maxPillarChunkZ;cz++)
                                        level.getChunkAt(new net.minecraft.core.BlockPos(cx*16+8,160,cz*16+8));
                        for(int y=0;y<320;y++) {
                                var pos=pillarBase.atY(y).immutable();
                                changedBlocks.putIfAbsent(pos,game.maps().snapshot(pos));
                        }
                        mana.set(owner,50);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && service.terrainCount()==1,"Academy Pillars queues one native terrain column");
                        int pillarTicks=0;
                        while(service.terrainCount()>0 && pillarTicks++<600) service.tick();
                        require(service.terrainCount()==0 && level.getBlockState(pillarBase.atY(0)).is(net.minecraft.world.level.block.Blocks.LAVA)
                                        && level.getBlockState(pillarBase.atY(159)).is(net.minecraft.world.level.block.Blocks.LAVA)
                                        && level.getBlockState(pillarBase.atY(319)).is(net.minecraft.world.level.block.Blocks.LAVA),
                                        "Pillars writes native lava from Y=0 through Y=319 and drains within the bounded tick budget");
                        pillarVictim.discard();

                        // Kiuas mode follows LbcKiuas.kiuResult and drains all three queued regions.
                        var kiuasVictim=frostProbeCow(level,cows,x+4.5,260,z+.5);
                        int minKiuasChunkX=(kiuasVictim.blockPosition().getX()-15)>>4;
                        int maxKiuasChunkX=(kiuasVictim.blockPosition().getX()+15)>>4;
                        int minKiuasChunkZ=(kiuasVictim.blockPosition().getZ()-15)>>4;
                        int maxKiuasChunkZ=(kiuasVictim.blockPosition().getZ()+15)>>4;
                        for(int cx=minKiuasChunkX;cx<=maxKiuasChunkX;cx++)
                                for(int cz=minKiuasChunkZ;cz<=maxKiuasChunkZ;cz++)
                                        level.getChunkAt(new net.minecraft.core.BlockPos(cx*16+8,260,cz*16+8));
                        for(int dx=-15;dx<=15;dx++) for(int dy=-15;dy<=15;dy++) for(int dz=-15;dz<=15;dz++) {
                                var pos=kiuasVictim.blockPosition().offset(dx,dy,dz).immutable();
                                changedBlocks.putIfAbsent(pos,game.maps().snapshot(pos));
                        }
                        var water=kiuasVictim.blockPosition().offset(3,0,0).immutable();
                        var campfire=kiuasVictim.blockPosition().offset(3,1,1).immutable();
                        changedBlocks.putIfAbsent(water,game.maps().snapshot(water));
                        changedBlocks.putIfAbsent(campfire,game.maps().snapshot(campfire));
                        level.setBlockAndUpdate(water.below(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
                        level.setBlockAndUpdate(campfire.below(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
                        level.setBlockAndUpdate(water,net.minecraft.world.level.block.Blocks.WATER.defaultBlockState());
                        level.setBlockAndUpdate(campfire,net.minecraft.world.level.block.Blocks.CAMPFIRE.defaultBlockState());
                        academyFireData=academyFire.get(DataComponents.CUSTOM_DATA).copyTag(); academyFireData.putInt("mode",4);
                        academyFire.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(academyFireData));
                        mana.set(owner,50);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && service.terrainCount()==1,"Academy Kiuas queues its grouped native terrain batch");
                        int kiuasTicks=0;
                        while(service.terrainCount()>0 && kiuasTicks++<600) service.tick();
                        require(service.terrainCount()==0 && level.getBlockState(water).is(net.minecraft.world.level.block.Blocks.FIRE)
                                        && level.getBlockState(campfire).is(net.minecraft.world.level.block.Blocks.FIRE)
                                        && level.getBlockState(kiuasVictim.blockPosition()).is(net.minecraft.world.level.block.Blocks.LAVA)
                                        && LbcKiuas.kiuResult(net.minecraft.world.level.block.Blocks.WATER.defaultBlockState())
                                                .is(net.minecraft.world.level.block.Blocks.FIRE)
                                        && LbcKiuas.kiuResult(net.minecraft.world.level.block.Blocks.CAMPFIRE.defaultBlockState())
                                                .is(net.minecraft.world.level.block.Blocks.FIRE),
                                        "Academy Kiuas applies native water/campfire conversions plus the center lava write and drains within budget");
                        kiuasVictim.discard();

                        // A real hostile Blaze at the ray endpoint is adopted and immediately unlocks its trial.
                        owner.setYRot(0); owner.setXRot(0);
                        var hostileBlaze=new net.minecraft.world.entity.monster.Blaze(net.minecraft.world.entity.EntityTypes.BLAZE,level);
                        hostileBlaze.setNoAi(true); hostileBlaze.setNoGravity(true); hostileBlaze.setPos(x+.5,260,z+9);
                        require(level.addFreshEntity(hostileBlaze),"Actual hostile Blaze enters the taming fixture"); testBlazes.add(hostileBlaze);
                        var blazeEnemy=frostProbeCow(level,cows,x+4.5,260,z+.5);
                        var blazeTrial=new ItemStack(LbcWands.BLAZE_WAND);
                        var blazeTrialData=new net.minecraft.nbt.CompoundTag(); blazeTrialData.putInt("fallingstars",1);
                        blazeTrialData.putInt("upgradable",1);
                        blazeTrial.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(blazeTrialData));
                        owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,blazeTrial);
                        owner.setShiftKeyDown(true); mana.set(owner,2800);
                        require(game.items().wands().use(owner,net.minecraft.world.InteractionHand.MAIN_HAND)
                                        && mana.get(owner)==2800 && service.owner(hostileBlaze)==owner,
                                        "Blaze contact transfers ownership and refunds the paid turret activation");
                        board.removePlayerFromTeam(owner.getScoreboardName()); board.removePlayerFromTeam(hostileBlaze.getScoreboardName());
                        require(!game.items().wands().target(owner,hostileBlaze) && !service.canTarget(hostileBlaze,owner),
                                        "A converted Blaze and its owner remain friendly even with no scoreboard team");
                        board.addPlayerToTeam(owner.getScoreboardName(),team); board.addPlayerToTeam(hostileBlaze.getScoreboardName(),team);
                        var hostileTrialMobs=level.getEntitiesOfClass(net.minecraft.world.entity.monster.Blaze.class,
                                        new net.minecraft.world.phys.AABB(x-16,244,z-16,x+16,276,z+16),
                                        mob->mob.entityTags().contains(LbcBlaze.TRIAL_PROJECTILE));
                        for(var mob:hostileTrialMobs) mob.setNoAi(true);
                        require(hostileTrialMobs.size()==20 && hostileTrialMobs.stream().allMatch(mob->service.owner(mob)==owner
                                        && service.canTarget(mob,owner) && service.canTarget(mob,blazeEnemy)),
                                        "Blaze trial spawns twenty owner-attributed hostile Blazes with the source self-hit target rule");
                        require(game.items().wands().target(owner,hostileTrialMobs.getFirst()),
                                        "Hostile trial Blazes remain valid combat targets for their summoner");
                        var creditVictim=frostProbeCow(level,cows,x+2.5,260,z+4.5);
                        creditVictim.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1);
                        creditVictim.setHealth(1); creditVictim.setInvulnerableTime(0); creditVictim.setNoAi(true);
                        require(creditVictim.hurtServer(level,level.damageSources().mobAttack(hostileBlaze),999)
                                        && !creditVictim.isAlive() && creditVictim.getKillCredit()==owner,
                                        "A native hostile Blaze mobAttack hit credits its player owner on lethal damage");
                        var blazeReady=blazeTrial.get(DataComponents.CUSTOM_DATA).copyTag();
                        require(blazeReady.getIntOr("upgrade_available",0)==1 && blazeReady.getIntOr("upgradable",1)==0,
                                        "Blaze trial is immediately upgrade-ready after the actual hostile encounter");
                        var nativeShot=new net.minecraft.world.entity.projectile.hurtingprojectile.SmallFireball(
                                        net.minecraft.world.entity.EntityTypes.SMALL_FIREBALL,level);
                        nativeShot.setOwner(hostileBlaze); nativeShot.setPos(hostileBlaze.position());
                        require(level.addFreshEntity(nativeShot),"Native Blaze SmallFireball enters the entity-load adoption fixture");
                        service.loaded(nativeShot); spawned.add(nativeShot);
                        require(nativeShot.getOwner()==owner && game.items().wands().isFireProjectile(nativeShot)
                                        && game.items().currentEpoch(nativeShot) && !game.items().wands().canHit(nativeShot,owner)
                                        && game.items().wands().canHit(nativeShot,hostileBlaze)
                                        && service.canTarget(hostileBlaze,blazeEnemy) && !service.canTarget(hostileBlaze,owner),
                                        "Loaded Blaze projectile adopts player credit and epoch, protects its player and can hit friendly mobs");
                        for(var mob:hostileTrialMobs) { mob.discard(); testBlazes.remove(mob); }
                        hostileBlaze.discard(); testBlazes.remove(hostileBlaze); service.stop();
                        require(service.count()==0,"Blaze trial mobs and services are fully removed between fixtures");
                        academyNpc.discard();

                        // Exercise the native retain-unloaded queue without forcing a distant chunk.
                        int workChunkX=0,workChunkZ=0; boolean foundUnloaded=false;
                        outer: for(int radius=3;radius<=20;radius++) for(int dx=-radius;dx<=radius;dx++) {
                                for(int dz=-radius;dz<=radius;dz++) {
                                        if(Math.max(Math.abs(dx),Math.abs(dz))!=radius) continue;
                                        int cx=(x>>4)+dx,cz=(z>>4)+dz;
                                        if(level.getChunkSource().getChunkNow(cx,cz)==null) {
                                                workChunkX=cx; workChunkZ=cz; foundUnloaded=true; break outer;
                                        }
                                }
                        }
                        require(foundUnloaded,"Find a distant unloaded chunk for the retained work fixture");
                        var retainedPos=new net.minecraft.core.BlockPos((workChunkX<<4)+8,260,(workChunkZ<<4)+8);
                        var retainedWork=new BlockAreaWork(level,s->s.is(net.minecraft.world.level.block.Blocks.STONE),
                                        (pos,s)->net.minecraft.world.level.block.Blocks.GOLD_BLOCK.defaultBlockState(),
                                        net.minecraft.world.level.block.Block.UPDATE_ALL,true);
                        retainedWork.move(new BlockAreaWork.Bounds(retainedPos.getX(),retainedPos.getY(),retainedPos.getZ(),
                                        retainedPos.getX(),retainedPos.getY(),retainedPos.getZ()),true);
                        require(retainedWork.step(game,owner,1,System.nanoTime()+1_000_000L)==0
                                        && retainedWork.queuedBlockCount()==1
                                        && level.getChunkSource().getChunkNow(workChunkX,workChunkZ)==null,
                                        "Retained terrain work waits without loading its unloaded chunk");
                        var loadedFixtureChunk=level.getChunk(workChunkX,workChunkZ);
                        var retainedSnapshot=game.maps().snapshot(retainedPos);
                        try {
                                level.setBlock(retainedPos,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),
                                                net.minecraft.world.level.block.Block.UPDATE_ALL);
                                require(retainedWork.step(game,owner,1,System.nanoTime()+1_000_000L)==1
                                                && retainedWork.queuedBlockCount()==0
                                                && level.getBlockState(retainedPos).is(net.minecraft.world.level.block.Blocks.GOLD_BLOCK),
                                                "Retained terrain work applies once after explicit chunk loading");
                        } finally {
                                retainedWork.clear(); game.maps().restoreSnapshot(retainedPos,retainedSnapshot);
                        }
                        SkyWars2.LOGGER.info("[check] PASS fireblaze-wand");
                } finally {
                        service.stop(); game.config().offhandWands=oldOffhand;
                        spawned.addAll(fresh.get()); for(var entity:spawned) entity.discard();
                        clearFixtureLoot(level,originalLoot,cows);
                        for(var cow:cows) { board.removePlayerFromTeam(cow.getScoreboardName()); cow.discard(); }
                        for(var mob:testBlazes) mob.discard();
                        if(academyNpc!=null) academyNpc.discard();
                        for(var entry:protectedTags.entrySet()) {
                                var tags=entry.getKey().entityTags(); var original=entry.getValue();
                                if(!original.contains("magic_academy")) tags.remove("magic_academy");
                                if(!original.contains("protectedmagic_academy")) tags.remove("protectedmagic_academy");
                        }
                        for(var entry:changedBlocks.entrySet()) game.maps().restoreSnapshot(entry.getKey(),entry.getValue());
                        game.maps().restoreSnapshot(obstacle,oldBlock);
                        board.removePlayerFromTeam(owner.getScoreboardName());
                        if(oldTeam!=null) board.addPlayerToTeam(owner.getScoreboardName(),oldTeam);
                        if(createdTeam) board.removePlayerTeam(team);
                        state.restore(game);
                }
        }

        private static int fireballPower(net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball projectile) {
                var saved=net.minecraft.world.level.storage.TagValueOutput.createWithContext(
                                net.minecraft.util.ProblemReporter.DISCARDING,projectile.registryAccess());
                projectile.saveWithoutId(saved);
                return saved.buildResult().getIntOr("ExplosionPower",-1);
        }

        private static void checkFireblazeCleanup(GameController game) {
                require(game.inLobby() && game.items().blaze().count()==0,
                                "Fireblaze markers and terrain work clear after match stop");
                SkyWars2.LOGGER.info("[check] PASS fireblaze-cleanup");
        }

        private static void checkKiuasMenu(GameController game) {
                require(game.playing(),"Kiuaskivi/Sun menu checks require a live match");
                var player=game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player!=null && game.allowDamage(player),"Kiuaskivi/Sun menu participant is active");
                var state=new WandThirdPlayerState(player,game.items().mana());
                try {
                        player.closeContainer(); player.getInventory().clearContent();
                        var kiuas=game.lbc().rollTable(player.level(),player.position(),player,"lbc:ported/kiuaskivi");
                        require(kiuas.size()==1,"Kiuaskivi source table returns one payload");
                        requireKiuasPayload(kiuas.getFirst(),player,false,"Kiuaskivi loot table");
                        var sun=game.lbc().rollTable(player.level(),player.position(),player,"lbc:ported/sun_arcanum");
                        require(sun.size()==1,"Fire/Kiuas source table returns one payload");
                        requireKiuasPayload(sun.getFirst(),player,true,"Sun Arcanum loot table");
                        SkyWars2.LOGGER.info("[check] PASS kiuas-menu");
                } finally { state.restore(game); }
        }

        private static void requireSunCraftResult(ItemStack result,ServerPlayer player,String label) {
                require(result.is(LbcKiuas.SUN) && result.getCount()==1
                                && net.minecraft.resources.Identifier.parse("lbc:the_sun").equals(result.get(DataComponents.ITEM_MODEL))
                                && net.minecraft.resources.Identifier.parse("lbc:tier_a").equals(result.get(DataComponents.TOOLTIP_STYLE))
                                && translation(result.get(DataComponents.CUSTOM_NAME),"sun_arcanum")!=null,
                                label+" crafts exactly one native Sun Arcanum");
                requirePolymerStack(player,result,Items.REPEATING_COMMAND_BLOCK,label+" result proxy");
        }

        private static void checkKiuasCrafting(GameController game) {
                require(game.playing(),"Sun recipe checks require a live match");
                var player=game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player!=null && game.allowDamage(player),"Sun crafting participant is active");
                var state=new WandThirdPlayerState(player,game.items().mana());
                var level=game.maps().level(); var tablePos=player.blockPosition().offset(1,0,0);
                var oldTable=game.maps().snapshot(tablePos); boolean openedTable=false;
                var fixtures=java.util.List.of(
                                new Object[]{"native Fire + native Kiuaskivi",new ItemStack(LbcWands.FIRE_WAND),new ItemStack(LbcKiuas.KIUASKIVI)},
                                new Object[]{"Academy Fire + native Kiuaskivi",new ItemStack(LbcWands.ACADEMY_FIRE),new ItemStack(LbcKiuas.KIUASKIVI)},
                                new Object[]{"legacy stfire + legacy kiuaskivi",legacyKiuasDonor("stfire",Items.CARROT_ON_A_STICK),legacyKiuasDonor("kiuaskivi",Items.REPEATING_COMMAND_BLOCK)});
                try {
                        player.closeContainer(); player.getInventory().clearContent();
                        var menu=player.inventoryMenu; var grid=menu.getCraftSlots();
                        for(var fixture:fixtures) {
                                var first=(ItemStack)fixture[1]; var second=(ItemStack)fixture[2];
                                grid.clearContent(); menu.setCarried(ItemStack.EMPTY);
                                grid.setItem(0,first.copyWithCount(2)); grid.setItem(3,second.copyWithCount(2));
                                requireSunCraftResult(menu.getResultSlot().getItem(),player,(String)fixture[0]+" 2x2 preview");
                                require(LbcCraftingRecipe.craftingKind(grid.asCraftInput())==LbcCraftingRecipe.Kind.SUN,
                                                fixture[0]+" matches the Sun recipe");
                                grid.setItem(1,new ItemStack(Items.STONE));
                                require(menu.getResultSlot().getItem().isEmpty(),fixture[0]+" rejects extra 2x2 ingredients");
                                grid.setItem(1,ItemStack.EMPTY);
                                inventoryClick(player,0,0,ContainerInput.PICKUP);
                                requireSunCraftResult(menu.getCarried(),player,(String)fixture[0]+" 2x2 take");
                                require(grid.getItem(0).getCount()==1 && grid.getItem(3).getCount()==1,
                                                fixture[0]+" take consumes exactly one of each ingredient");
                        }
                        level.setBlockAndUpdate(tablePos,net.minecraft.world.level.block.Blocks.CRAFTING_TABLE.defaultBlockState());
                        player.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,owner)->
                                        new net.minecraft.world.inventory.CraftingMenu(id,inventory,
                                                        net.minecraft.world.inventory.ContainerLevelAccess.create(level,tablePos)),
                                        Component.translatable("container.crafting")));
                        openedTable=true;
                        var table=(net.minecraft.world.inventory.CraftingMenu)player.containerMenu;
                        var inputs=table.getInputGridSlots();
                        inputs.get(0).setByPlayer(new ItemStack(LbcWands.FIRE_WAND,2));
                        inputs.get(8).setByPlayer(new ItemStack(LbcKiuas.KIUASKIVI,2));
                        requireSunCraftResult(table.getResultSlot().getItem(),player,"3x3 preview");
                        require(inputs.get(0).getItem().getCount()==2 && inputs.get(8).getItem().getCount()==2,
                                        "3x3 Sun preview does not consume ingredients");
                        inputs.get(4).setByPlayer(new ItemStack(Items.STONE));
                        require(table.getResultSlot().getItem().isEmpty(),"3x3 Sun recipe rejects extra ingredients");
                        inputs.get(4).setByPlayer(ItemStack.EMPTY);
                        inventoryClick(player,0,0,ContainerInput.PICKUP);
                        requireSunCraftResult(table.getCarried(),player,"3x3 take");
                        require(inputs.get(0).getItem().getCount()==1 && inputs.get(8).getItem().getCount()==1,
                                        "3x3 Sun take consumes exactly one of each ingredient");
                        SkyWars2.LOGGER.info("[check] PASS kiuas-crafting");
                } finally {
                        if(openedTable) player.closeContainer();
                        game.maps().restoreSnapshot(tablePos,oldTable); state.restore(game);
                }
        }

        private static void checkKiuasCleanup(GameController game) {
                require(game.inLobby() && game.items().kiuas().count()==0
                                && game.items().kiuas().queuedBlockCount()==0,
                                "Kiuaskivi aura and queued block work clear after match stop");
                SkyWars2.LOGGER.info("[check] PASS kiuas-cleanup");
        }

