                        player.entityTags().addAll(oldTags);
                        player.teleportTo(level, oldPosition.x, oldPosition.y, oldPosition.z, java.util.Set.of(),
                                        oldYaw, oldPitch, true);
                        player.setGameMode(oldMode);
                        player.setShiftKeyDown(oldShift);
                        player.setHealth(Math.min(player.getMaxHealth(), oldHealth));
                        game.config().lbcTrinketLimit = oldTrinketLimit;
                        player.setAbsorptionAmount(oldAbsorption);
                        mana.maximum(player, oldMax);
                        mana.baseRegen(player, oldRegen);
                        mana.set(player, oldMana);
                        mana.noMagic(player, oldNoMagic);
                        mana.inventoryChanged(player);
                        for (int i = 0; i < manaTimers.size(); i++)
                                mana.score(player, manaTimers.get(i)).set(oldManaTimers[i]);
