                        ally.getAbilities().mayfly = oldAllyMayFly;
                        ally.getAbilities().flying = oldAllyFlying;
                        ally.getAbilities().invulnerable = oldAllyInvulnerable;
                        ally.setInvisible(oldAllyInvisible);
                        ally.noPhysics = oldAllyNoPhysics;
                        ally.onUpdateAbilities();
                        mana.noMagic(ally, oldAllyNoMagic);
