        private static void checkElectroNativeBlockLaunch(net.minecraft.server.level.ServerLevel level,
                        net.minecraft.server.level.ServerPlayer player, LbcWands wands, ItemStack wand,
                        LbcMana mana, java.util.Map<net.minecraft.core.BlockPos,
                                        net.minecraft.world.level.block.state.BlockState> originalBlocks,
                        java.util.List<net.minecraft.world.entity.animal.cow.Cow> testMobs,
                        double baseX, double testY, double baseZ) {
                Vec3 savedPosition = player.position();
                float savedYaw = player.getYRot(), savedPitch = player.getXRot();
                var directions = new net.minecraft.core.Direction[] {
                                net.minecraft.core.Direction.DOWN, net.minecraft.core.Direction.UP,
                                net.minecraft.core.Direction.NORTH, net.minecraft.core.Direction.SOUTH,
                                net.minecraft.core.Direction.WEST, net.minecraft.core.Direction.EAST };
                for (var face : directions) {
                        for (var entry : originalBlocks.entrySet()) level.setBlock(entry.getKey(), entry.getValue(), 3);
                        originalBlocks.clear(); wands.stop();
                        player.teleportTo(level, baseX + .5, testY, baseZ + .5, java.util.Set.of(), 0, 0, true);
                        var incomingFace = face.getOpposite();
                        float yaw = switch (incomingFace) {
                                case NORTH -> 180; case WEST -> 90; case EAST -> -90; default -> 0;
                        };
                        float pitch = incomingFace == net.minecraft.core.Direction.UP ? -90
                                        : incomingFace == net.minecraft.core.Direction.DOWN ? 90 : 0;
                        player.setYRot(yaw); player.setXRot(pitch);
                        var from = player.getEyePosition();
                        var incoming = net.minecraft.world.phys.Vec3.directionFromRotation(pitch, yaw);
                        for (int i = 0; i <= 24; i++) {
                                var pos = net.minecraft.core.BlockPos.containing(from.add(incoming.scale(i * .25)));
                                require(level.hasChunkAt(pos), "Electro face fixture chunk is loaded: " + pos);
                                originalBlocks.putIfAbsent(pos, level.getBlockState(pos));
                                level.setBlock(pos, net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(), 3);
                        }
                        var wall = net.minecraft.core.BlockPos.containing(from.add(incoming.scale(4)));
                        originalBlocks.putIfAbsent(wall, level.getBlockState(wall));
                        level.setBlock(wall, net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(), 3);
                        var hit = net.minecraft.world.phys.shapes.Shapes.block().clip(from, from.add(incoming.scale(12)), wall);
                        require(hit != null && hit.getDirection() == face,
                                        "Native Electro fixture reaches the intended " + face + " block face");
                        player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND, wand.copy());
                        mana.set(player, 1000);
                        require(wand.getItem().use(level, player, net.minecraft.world.InteractionHand.MAIN_HAND).consumesAction()
                                        && wands.electroCount() == 1, "Native " + face + " impact creates one trace");
                        var trace = wands.electroSnapshot().getFirst();
                        var normal = face.getUnitVec3();
                        require(trace.position.distanceTo(hit.getLocation().add(normal)) < 1.0e-5
                                        && net.minecraft.world.phys.Vec3.directionFromRotation(trace.pitch, trace.yaw).dot(normal) > .999,
                                        "Electro " + face + " launch starts and points along the hit face normal");
                        wands.tick();
                        var advanced = wands.electroSnapshot();
                        require(advanced.size() == 1
                                        && advanced.getFirst().position.subtract(hit.getLocation()).dot(normal) > 2.9,
                                        "Electro " + face + " first movement stays outside its launch wall");
                }

                // Oblique incoming direction distinguishes the native clipped face from merely reversing the ray.
                for (var entry : originalBlocks.entrySet()) level.setBlock(entry.getKey(), entry.getValue(), 3);
                originalBlocks.clear(); wands.stop();
                player.teleportTo(level, baseX + .5, testY, baseZ + .5, java.util.Set.of(), 0, 0, true);
                player.setYRot(-65); player.setXRot(0);
                var from = player.getEyePosition();
                var incoming = player.getLookAngle();
                for (int i = 0; i <= 32; i++) {
                        var pos = net.minecraft.core.BlockPos.containing(from.add(incoming.scale(i * .25)));
                        require(level.hasChunkAt(pos), "Oblique Electro fixture chunk is loaded: " + pos);
                        originalBlocks.putIfAbsent(pos, level.getBlockState(pos));
                        level.setBlock(pos, net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(), 3);
                }
                var obliqueWall = new net.minecraft.core.BlockPos((int)baseX + 3, (int)testY + 1, (int)baseZ + 1);
                originalBlocks.putIfAbsent(obliqueWall, level.getBlockState(obliqueWall));
                level.setBlock(obliqueWall, net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(), 3);
                var obliqueHit = net.minecraft.world.phys.shapes.Shapes.block().clip(from, from.add(incoming.scale(12)), obliqueWall);
                require(obliqueHit != null && obliqueHit.getDirection() == net.minecraft.core.Direction.WEST,
                                "Oblique Electro ray clips the WEST face rather than a reversed-ray approximation");
                player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND, wand.copy()); mana.set(player, 1000);
                require(wand.getItem().use(level, player, net.minecraft.world.InteractionHand.MAIN_HAND).consumesAction()
                                && wands.electroCount() == 1, "Oblique native block contact creates a trace");
                var obliqueTrace = wands.electroSnapshot().getFirst();
                var west = net.minecraft.core.Direction.WEST.getUnitVec3();
                require(obliqueTrace.position.distanceTo(obliqueHit.getLocation().add(west)) < 1.0e-5
                                && net.minecraft.world.phys.Vec3.directionFromRotation(obliqueTrace.pitch, obliqueTrace.yaw).dot(west) > .999,
                                "Oblique Electro launch uses the clipped WEST normal, not reverse incoming direction");
                wands.stop();

                // Entity endpoints retain the owner's original heading and the historical backward setback.
                for (var entry : originalBlocks.entrySet()) level.setBlock(entry.getKey(), entry.getValue(), 3);
                originalBlocks.clear();
                player.teleportTo(level, baseX + 8.5, testY, baseZ + .5, java.util.Set.of(), 90, 0, true);
                player.setYRot(90); player.setXRot(0);
                var target = new net.minecraft.world.entity.animal.cow.Cow(net.minecraft.world.entity.EntityTypes.COW, level);
                target.setPos(baseX + 5.5, testY + .92, baseZ + .5); target.setNoGravity(true);
                level.addFreshEntity(target); testMobs.add(target);
                var entityContact = target.getBoundingBox().clip(player.getEyePosition(),
                                player.getEyePosition().add(player.getLookAngle().scale(35))).orElseThrow();
                player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND, wand.copy()); mana.set(player, 1000);
                require(wand.getItem().use(level, player, net.minecraft.world.InteractionHand.MAIN_HAND).consumesAction()
                                && wands.electroCount() == 1, "Electro entity endpoint creates a native trace");
                var entityTrace = wands.electroSnapshot().getFirst();
                require(entityTrace.yaw == player.getYRot() && entityTrace.pitch == player.getXRot()
                                && entityTrace.position.distanceTo(entityContact.subtract(player.getLookAngle())) < 1.0e-5,
                                "Entity-hit Electro launch preserves exact owner yaw and pitch");
                wands.stop();
                for (var entry : originalBlocks.entrySet()) level.setBlock(entry.getKey(), entry.getValue(), 3);
                originalBlocks.clear();
                player.teleportTo(level, savedPosition.x, savedPosition.y, savedPosition.z,
                                java.util.Set.of(), savedYaw, savedPitch, true);
        }

        private static void checkWandsElectroCleanup(GameController game) {
                require(game.inLobby(), "Tiny Electro cleanup check runs after match stop");
                require(game.items().wands().electroCount() == 0,
                                "Tracked Tiny Electro traces are removed on stop");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player != null, "Tiny Electro cleanup fixture exists");
                if (wandsElectroCleanupOwner != null) {
                        require(player.getUUID().equals(wandsElectroCleanupOwner), "Electro cleanup owner fixture is stable");
                        wandsElectroCleanupOwner = null;
                }
                SkyWars2.LOGGER.info("[check] PASS wands-electro-cleanup");
        }

        private static void checkManaCore(GameController game) {
                require(game.playing(), "Mana core requires an actual match");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var mana = game.items().mana();
                require(player != null && game.allowDamage(player), "Mana fixture is a live participant");
                int oldMana = mana.get(player), oldMax = mana.maximum(player), oldBase = mana.baseRegen(player);
                int oldBoost = mana.boost(player), oldReverse = mana.reverse(player);
                GameType oldMode = player.gameMode();
                int oldFood = player.getFoodData().getFoodLevel();
                float oldSaturation = player.getFoodData().getSaturationLevel();
                int oldFoodCount = mana.score(player, "food_count").get();
                var boostAdvancement = game.server().getAdvancements().get(net.minecraft.resources.Identifier
                                .parse("lbc:true_advancements/potions/effect_magic_buff"));
                var tempAdvancement = game.server().getAdvancements().get(
                                net.minecraft.resources.Identifier.parse("lbc:true_advancements/potions/mana_temp"));
                boolean hadBoostAdvancement = boostAdvancement != null
                                && player.getAdvancements().getOrStartProgress(boostAdvancement).isDone();
                boolean hadTempAdvancement = tempAdvancement != null
                                && player.getAdvancements().getOrStartProgress(tempAdvancement).isDone();
                var oldInventory = new ItemStack[player.getInventory().getContainerSize()];
                for (int slot = 0; slot < oldInventory.length; slot++)
                        oldInventory[slot] = player.getInventory().getItem(slot).copy();
                var oldCursor = player.containerMenu.getCarried().copy();
                var oldEffects = player.getActiveEffects().stream()
                                .map(net.minecraft.world.effect.MobEffectInstance::new).toList();
                var level = player.level();
                var observer = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                require(observer != null, "Observer mana fixture exists");
                int observerMana = mana.get(observer), observerMax = mana.maximum(observer),
                                observerBase = mana.baseRegen(observer);
                int observerBoost = mana.boost(observer), observerReverse = mana.reverse(observer);
                var stopper = new net.minecraft.world.entity.Marker(net.minecraft.world.entity.EntityTypes.MARKER,
                                level);
                boolean observerWasObserver = false;
                try {
                        mana.resetResources(player);
                        require(mana.get(player) == 5000 && mana.maximum(player) == 5000 && mana.baseRegen(player) == 10
                                        && mana.regeneration(player) == 10 && mana.boost(player) == 0
                                        && mana.reverse(player) == 0
                                        && mana.score(player, "food_count").get() == 0,
                                        "New mana resources start at 5000/5000 with base and visual regen 10, no statuses, and reset food counter");

                        mana.set(player, 8123);
                        mana.maximum(player, 9000);
                        mana.baseRegen(player, 10);
                        require(mana.get(player) == 8123 && mana.maximum(player) == 9000
                                        && mana.baseRegen(player) == 10,
                                        "Mana resource accessors preserve explicit values");
                        mana.add(player, -23);
                        require(mana.get(player) == 8100, "Mana add accepts signed adjustments");
                        require(mana.trySpend(player, 100) && mana.get(player) == 8000,
                                        "Mana spend deducts exactly the requested amount");
                        require(!mana.trySpend(player, 8001) && mana.get(player) == 8000,
                                        "Insufficient mana does not spend");
                        boolean negativeSpendRejected = false;
                        try {
                                mana.trySpend(player, -1);
                        } catch (IllegalArgumentException expected) {
                                negativeSpendRejected = true;
                        }
                        require(negativeSpendRejected && mana.get(player) == 8000,
                                        "Negative spend cost is rejected without changing mana");

                        // Marked vanilla armor and a generic marked stack exercise datapack gear
                        // without registering test items.
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,
                                        manaFixture(Items.LEATHER_HELMET, "mage"));
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST,
                                        manaFixture(Items.LEATHER_CHESTPLATE, "mage"));
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.LEGS,
                                        manaFixture(Items.LEATHER_LEGGINGS, "mage"));
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET,
                                        manaFixture(Items.LEATHER_BOOTS, "mage"));
                        var belts = manaFixture(Items.STICK, "manabelt").copyWithCount(2);
                        player.getInventory().setItem(9, belts);
                        triggerNativeInventoryChange(player, belts);
                        mana.set(player, 100);
                        mana.maximum(player, 1000);
                        mana.baseRegen(player, 10);
                        mana.tickPlayer(player);
                        require(mana.get(player) == 135 && mana.regeneration(player) == 35,
                                        "One eligible mana tick performs one combined gear-boosted addition; mage armor adds 4/6/7/4 and each belt adds 2 visual regen");

                        mana.boost(player, 2);
                        mana.tickPlayer(player);
                        require(mana.get(player) == 187 && mana.boost(player) == 1 && mana.regeneration(player) == 52,
                                        "Boosted tick uses source 3/2 scaling once and decrements its timer once");
                        mana.tickPlayer(player);
                        require(mana.get(player) == 239 && mana.boost(player) == 0,
                                        "Boost expires after its second eligible tick");
                        mana.set(player, 990);
                        mana.tickPlayer(player);
                        require(mana.get(player) == 1000, "Ordinary regeneration clamps to maximum mana");

                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD, ItemStack.EMPTY);
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST, ItemStack.EMPTY);
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.LEGS, ItemStack.EMPTY);
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET, ItemStack.EMPTY);
                        player.getInventory().setItem(9, ItemStack.EMPTY);
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        mana.set(player, 1000);
                        mana.maximum(player, 5000);
                        mana.baseRegen(player, 10);
                        mana.reverse(player, 2);
                        mana.set(player, 1000);
                        mana.tickPlayer(player);
                        require(mana.get(player) == 990 && mana.reverse(player) == 2,
                                        "Reverse mana drains visual regen and suppresses the ordinary gain");
                        mana.secondPlayer(player);
                        require(mana.reverse(player) == 1, "Reverse timer advances once per second");
                        mana.tickPlayer(player);
                        mana.secondPlayer(player);
                        mana.tickPlayer(player);
                        require(mana.get(player) == 990 && mana.reverse(player) == 0,
                                        "Reverse drains on both seconds, then normal regeneration resumes");

                        mana.set(player, 123);
                        mana.maximum(player, 1000);
                        mana.baseRegen(player, 10);
                        mana.tickPlayer(player);
                        mana.set(player, 123);
                        var hud = mana.hud(player);
                        var hudParts = hud.getSiblings();
                        require(hud.getString().equals("\uE100 123\u00a7a/1000 \u00a7a[\u00a7a+10\u00a7a]") && hudParts.size() == 7
                                        && hudParts.get(1).getString().equals("123")
                                        && java.util.Objects.equals(hudParts.get(1).getStyle().getColor(),
                                                        net.minecraft.network.chat.TextColor.fromLegacyFormat(
                                                                        net.minecraft.ChatFormatting.AQUA))
                                        && hudParts.get(2).getString().equals("\u00a7a/")
                                        && hudParts.get(3).getString().equals("1000")
                                        && java.util.Objects.equals(hudParts.get(3).getStyle().getColor(),
                                                        net.minecraft.network.chat.TextColor.fromLegacyFormat(
                                                                        net.minecraft.ChatFormatting.AQUA))
                                        && hudParts.get(4).getString().equals(" \u00a7a[\u00a7a+")
                                        && hudParts.get(5).getString().equals("10")
                                        && java.util.Objects.equals(hudParts.get(5).getStyle().getColor(),
                                                        net.minecraft.network.chat.TextColor.fromLegacyFormat(
                                                                        net.minecraft.ChatFormatting.AQUA))
                                        && hudParts.get(6).getString().equals("\u00a7a]"),
                                        "Mana HUD keeps the source glyph, values, spacing and literal green separators");
                        require(java.util.Objects.equals(mana.hud(player).getStyle().getColor(),
                                        net.minecraft.network.chat.TextColor.fromRgb(0x4E5C24)),
                                        "Mana HUD glyph keeps the source olive color");

                        mana.set(player, 400);
                        player.setGameMode(GameType.CREATIVE);
                        mana.tickPlayer(player);
                        require(mana.get(player) == 410, "Creative players retain mana regeneration");
                        mana.set(player, 400);
                        player.entityTags().add("time_stopped");
                        require(!mana.trySpend(player, 1), "Time-stopped players cannot spend mana");
                        mana.tickPlayer(player);
                        require(mana.get(player) == 400, "Time-stopped players receive no mana tick");
                        player.entityTags().remove("time_stopped");

                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.RAID_OMEN, 2, 16,
                                        false, false, false));
                        player.entityTags().add("time_stopped");
                        mana.tickPlayer(player);
                        require(player.hasEffect(MobEffects.RAID_OMEN) && mana.boost(player) == 0
                                        && mana.get(player) == 400,
                                        "Native Raid Omen XVI waits for an eligible tick while time is stopped");
                        player.entityTags().remove("time_stopped");
                        stopper.setPos(player.position());
                        stopper.entityTags().add("stopper_magic");
                        level.addFreshEntity(stopper);
                        require(game.items().magic().suppressed(player) && !mana.trySpend(player, 1),
                                        "A live magic stopper vetoes mana spending");
                        mana.tickPlayer(player);
                        require(mana.get(player) == 400 && !player.hasEffect(MobEffects.RAID_OMEN)
                                        && mana.boost(player) == 1,
                                        "Native Raid Omen XVI converts despite magic suppression and normalizes duration two to one");
                        stopper.discard();
                        mana.tickPlayer(player);
                        require(mana.get(player) == 415 && mana.regeneration(player) == 15 && mana.boost(player) == 0,
                                        "Converted Raid Omen boosts the first unsuppressed mana tick once");

                        observerWasObserver = game.isObserver(observer);
                        game.spectators().enter(observer);
                        mana.set(observer, 300);
                        mana.baseRegen(observer, 10);
                        require(!mana.trySpend(observer, 1), "Detached Adventure observer cannot spend mana");
                        mana.tickPlayer(observer);
                        require(mana.get(observer) == 300, "Detached Adventure observer receives no mana tick");
                        if (!observerWasObserver)
                                game.spectators().remove(observer);

                        mana.set(player, -7);
                        mana.maximum(player, 900);
                        mana.baseRegen(player, 10);
                        mana.clearEffects(player);
                        require(mana.get(player) == -7 && mana.maximum(player) == 900 && mana.baseRegen(player) == 10
                                        && mana.boost(player) == 0 && mana.reverse(player) == 0,
                                        "Clearing mana effects preserves resources and base regeneration");
                } finally {
                        stopper.discard();
                        if (observer != null && !observerWasObserver && game.isObserver(observer))
                                game.spectators().remove(observer);
                        if (observer != null) {
                                mana.clearEffects(observer);
                                mana.maximum(observer, observerMax);
                                mana.baseRegen(observer, observerBase);
                                mana.set(observer, observerMana);
                                mana.boost(observer, observerBoost);
                                mana.reverse(observer, observerReverse);
                        }
                        player.entityTags().remove("time_stopped");
                        mana.clearEffects(player);
                        mana.maximum(player, oldMax);
                        mana.baseRegen(player, oldBase);
                        mana.set(player, oldMana);
                        mana.boost(player, oldBoost);
                        mana.reverse(player, oldReverse);
                        for (int slot = 0; slot < oldInventory.length; slot++)
                                player.getInventory().setItem(slot, oldInventory[slot]);
                        mana.inventoryChanged(player);
                        player.containerMenu.setCarried(oldCursor);
                        player.setGameMode(oldMode);
                        player.getFoodData().setFoodLevel(oldFood);
                        player.getFoodData().setSaturation(oldSaturation);
                        mana.score(player, "food_count").set(oldFoodCount);
                        player.removeAllEffects();
                        for (var effect : oldEffects)
                                player.addEffect(effect);
                        if (!hadBoostAdvancement && boostAdvancement != null)
                                revokeAdvancement(player, boostAdvancement);
                        if (!hadTempAdvancement && tempAdvancement != null)
                                revokeAdvancement(player, tempAdvancement);
                }
                // Match death recreates ServerPlayer; assert the UUID-backed resources survive
                // while temporary statuses do not.
                mana.set(player, 321);
                mana.maximum(player, 987);
                mana.baseRegen(player, 0);
                player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.RAID_OMEN, 4, 17, false,
                                false, false));
                mana.tickPlayer(player);
                require(mana.maximum(player) == 3487 && mana.score(player, "effect_add_manamax").get() == 3,
                                "Native max-mana potion creates a persistent stat change and a timed pulse before death");
                mana.boost(player, 8);
                mana.reverse(player, 9);
                player.hurtServer(level, player.damageSources().genericKill(), 10000);
                require(game.awaitingRespawn(player.getUUID()),
                                "Mana lifecycle fixture enters normal death/respawn flow");
                sendRespawnPacket(player);
                deferredTicks = 2;
                deferredCheck = () -> {
                        var respawned = game.server().getPlayerList().getPlayer(player.getUUID());
                        require(respawned != null && respawned != player && game.allowDamage(respawned),
                                        "Mana owner respawns as a fresh live player");
                        require(mana.get(respawned) == 321 && mana.maximum(respawned) == 3487
                                        && mana.baseRegen(respawned) == 0,
                                        "Mana, maximum and base regeneration survive death");
                        require(mana.boost(respawned) == 0 && mana.reverse(respawned) == 0,
                                        "Temporary mana statuses clear on death");
                        require(mana.score(respawned, "effect_add_manamax").get() == 0,
                                        "Mana potion timer clears on death while its permanent maximum increase survives");
                        mana.maximum(respawned, oldMax);
                        mana.baseRegen(respawned, oldBase);
                        mana.set(respawned, oldMana);
                        mana.boost(respawned, oldBoost);
                        mana.reverse(respawned, oldReverse);
                        SkyWars2.LOGGER.info("[check] PASS mana-core");
                };
        }

        private static ItemStack manaFixture(net.minecraft.world.item.Item item, String marker) {
                var stack = new ItemStack(item);
                var data = new net.minecraft.nbt.CompoundTag();
                data.putInt(marker, 1);
                stack.set(DataComponents.CUSTOM_DATA, net.minecraft.world.item.component.CustomData.of(data));
                return stack;
        }

        /**
         * Exercises native fall/consumption/damage entry points, including the injected
         * hooks.
         */
        private static void checkSkills(GameController game) {
                require(game.playing(), "Skills require a live match");
                var owner = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var enemy = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                require(owner != null && enemy != null && game.allowDamage(owner) && game.allowDamage(enemy),
                                "Two live skill probes");
                owner.removeAllEffects();
                enemy.removeAllEffects();
                owner.getInventory().clearContent();
                enemy.getInventory().clearContent();
                owner.setNoGravity(true);
                enemy.setNoGravity(true);
                owner.teleportTo(owner.level(), 0, 200, 0, java.util.Set.of(), 0, 0, true);
                enemy.teleportTo(owner.level(), 2, 200, 0, java.util.Set.of(), 0, 0, true);
                owner.level().getGameRules().set(net.minecraft.world.level.gamerules.GameRules.FALL_DAMAGE, true,
                                game.server());
                game.config().vanillaSkills = true;
                game.players().get(owner.getUUID()).skill = 2;
                game.players().get(enemy.getUUID()).skill = 0;
                owner.setHealth(60);
                enemy.setHealth(60);
                enemy.setInvulnerableTime(0);
                enemy.damageCooldownTime = 0;
                owner.causeFallDamage(3.34, 0, owner.damageSources().fall());
                require(enemy.getHealth() == 60, "Heavyweight ignores falls below 335 cm");
                owner.causeFallDamage(3.35, 0, owner.damageSources().fall());
                require(Math.abs(enemy.getHealth() - (60 - 335 * 0.00915)) < 0.001,
                                "Native landing applies source radial damage");
                require(owner.getHealth() == 60, "Heavyweight does not damage its owner");
                enemy.setHealth(60);
                enemy.setInvulnerableTime(0);
                enemy.damageCooldownTime = 0;
                owner.causeFallDamage(40, 0, owner.damageSources().fall());
                require(Math.abs(enemy.getHealth() - (60 - 3999 * 0.00915)) < 0.001, "Heavyweight clamps at 3999 cm");
                enemy.teleportTo(enemy.level(), 7, 200, 0, java.util.Set.of(), 0, 0, true);
                enemy.setHealth(60);
                enemy.setInvulnerableTime(0);
                enemy.damageCooldownTime = 0;
                owner.causeFallDamage(10, 0, owner.damageSources().fall());
                require(enemy.getHealth() == 60, "Heavyweight respects six-block radius");

                game.players().get(owner.getUUID()).skill = 4;
                new ItemStack(Items.BREAD).finishUsingItem(owner.level(), owner);
                requireFoodEffects(owner);
                owner.removeAllEffects();
                var remainder = new ItemStack(Items.HONEY_BOTTLE).finishUsingItem(owner.level(), owner);
                requireFoodEffects(owner);
                require(remainder.is(Items.GLASS_BOTTLE), "Consumption preserves native bottle remainder");
                owner.removeAllEffects();
                new ItemStack(Items.POTION).finishUsingItem(owner.level(), owner);
                require(!owner.hasEffect(MobEffects.ABSORPTION), "Non-food consumable gives no skill bonus");
                owner.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND, new ItemStack(Items.BREAD));
                owner.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);
                owner.releaseUsingItem();
                require(!owner.hasEffect(MobEffects.ABSORPTION), "Cancelled consumption gives no bonus");
                game.config().vanillaSkills = false;
                new ItemStack(Items.BREAD).finishUsingItem(owner.level(), owner);
                require(!owner.hasEffect(MobEffects.ABSORPTION), "Disabled skills do not trigger");
                game.config().vanillaSkills = true;
                int cleared = 0;
                for (int attempt = 0; attempt < 64; attempt++) {
                        owner.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.HUNGER, 1000));
                        new ItemStack(Items.BREAD).finishUsingItem(owner.level(), owner);
                        if (!owner.hasEffect(MobEffects.HUNGER))
                                cleared++;
                }
                require(cleared > 0 && cleared < 64, "Hunger removal is probabilistic, not always/never");
                owner.removeAllEffects();
                enemy.removeAllEffects();
                owner.getInventory().clearContent();
                game.players().get(owner.getUUID()).skill = 13;
                enemy.teleportTo(enemy.level(), 2, 200, 0, java.util.Set.of(), 0, 0, true);
                nativeTickProbes.add(owner.getUUID());
                nativeTickProbes.add(enemy.getUUID());
                SkyWars2.LOGGER.info("[check] skills fall/food PASS; hunger clears={}/64", cleared);
                probeVex(game, owner, enemy, 0);
        }

        private static void requireFoodEffects(ServerPlayer owner) {
                var absorption = owner.getEffect(MobEffects.ABSORPTION);
                var regeneration = owner.getEffect(MobEffects.REGENERATION);
                var saturation = owner.getEffect(MobEffects.SATURATION);
                require(absorption != null && absorption.getDuration() == 200 && absorption.getAmplifier() == 0
                                && !absorption.isVisible(), "Absorption I, ten seconds, hidden particles");
                require(regeneration != null && regeneration.getDuration() == 100 && regeneration.getAmplifier() == 0,
                                "Regeneration I, five seconds");
                require(saturation != null && saturation.getDuration() == 40 && saturation.getAmplifier() == 0,
                                "Saturation I, two seconds");
        }

        private static java.util.List<Vex> ownedVexes(GameController game) {
                return java.util.stream.StreamSupport.stream(game.maps().level().getAllEntities().spliterator(), false)
                                .filter(entity -> entity instanceof Vex && !entity.shouldBeSaved()
                                                && !entity.isRemoved())
                                .map(entity -> (Vex) entity).toList();
        }

        private static void probeVex(GameController game, ServerPlayer owner, ServerPlayer enemy, int attempt) {
                require(attempt < 32, "Vex appears within 32 successful hit trials");
                owner.setInvulnerableTime(0);
                owner.damageCooldownTime = 0;
                owner.setHealth(60);
                require(owner.hurtServer(owner.level(), owner.damageSources().generic(), 1), "Native damage accepted");
                require(ownedVexes(game).isEmpty(), "Vex does not spawn immediately on damage");
                deferredTicks = 6;
                deferredCheck = () -> {
                        var summoned = ownedVexes(game);
                        if (summoned.isEmpty()) {
                                probeVex(game, owner, enemy, attempt + 1);
                                return;
                        }
                        require(summoned.size() == 1, "One summon trial per hurt window");
                        var vex = summoned.getFirst();
                        vex.setNoAi(true);
                        require(Math.abs(vex.getHealth() - 0.1F) < 0.001, "Vex retains source 0.1 HP");
                        require(vex.getAttributeValue(
                                        net.minecraft.world.entity.ai.attributes.Attributes.FOLLOW_RANGE) == 50,
                                        "Vex follow range 50");
                        require(vex.getMainHandItem().isEmpty(), "Vex receives no implicit vanilla sword");
                        require(!vex.canAttack(owner) && vex.canAttack(enemy), "Vex targets enemies, never its owner");
                        owner.setInvulnerableTime(0);
                        owner.damageCooldownTime = 0;
                        float health = owner.getHealth();
                        require(!vex.doHurtTarget(owner.level(), owner) && owner.getHealth() == health,
                                        "Forced owner attack is rejected");
                        var scoreboard = game.server().getScoreboard();
                        var team = scoreboard.addPlayerTeam("skill_probe");
                        try {
                                scoreboard.addPlayerToTeam(owner.getScoreboardName(), team);
                                scoreboard.addPlayerToTeam(enemy.getScoreboardName(), team);
                                require(!vex.canAttack(enemy) && !vex.doHurtTarget(owner.level(), enemy),
                                                "Vex respects owner's allies");
                        } finally {
                                scoreboard.removePlayerTeam(team);
                        }
                        enemy.setInvulnerableTime(0);
                        enemy.damageCooldownTime = 0;
                        enemy.setHealth(60);
                        require(vex.doHurtTarget(owner.level(), enemy) && enemy.getHealth() < 60,
                                        "Native Vex damages opponent");
                        owner.setInvulnerableTime(0);
                        owner.damageCooldownTime = 0;
                        owner.hurtServer(owner.level(), owner.damageSources().generic(), 1);
                        // A real death must remove existing summons and invalidate the pending hurt
                        // window.
                        owner.setInvulnerableTime(0);
                        owner.damageCooldownTime = 0;
                        owner.hurtServer(owner.level(), owner.damageSources().genericKill(), 10000);
                        require(ownedVexes(game).isEmpty(), "Owner death removes all owned Vex immediately");
                        require(game.awaitingRespawn(owner.getUUID()), "Death entered native respawn lifecycle");
                        sendRespawnPacket(owner);
                        deferredTicks = 8;
                        deferredCheck = () -> {
                                require(ownedVexes(game).isEmpty(), "Death/respawn cancels delayed summons");
                                var replacement = game.server().getPlayerList().getPlayer(owner.getUUID());
                                require(replacement != null && replacement != owner && game.allowDamage(replacement),
                                                "Respawn uses a new live player incarnation");
                                replacement.setNoGravity(true);
                                replacement.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                                                MobEffects.ABSORPTION, 200));
                                probeAbsorbedVex(game, replacement, enemy, 0);
                        };
                };
        }

        private static void probeAbsorbedVex(GameController game, ServerPlayer owner, ServerPlayer enemy, int attempt) {
                require(attempt < 32, "Respawned owner summons after fully absorbed hits");
                owner.setInvulnerableTime(0);
                owner.damageCooldownTime = 0;
                owner.setAbsorptionAmount(2);
                float health = owner.getHealth();
                require(owner.hurtServer(owner.level(), owner.damageSources().generic(), 1)
                                && owner.getHealth() == health,
                                "Native damage is fully absorbed and still sets HurtTime");
                deferredTicks = 6;
                deferredCheck = () -> {
                        var summons = ownedVexes(game);
                        if (summons.isEmpty()) {
                                probeAbsorbedVex(game, owner, enemy, attempt + 1);
                                return;
                        }
                        require(summons.size() == 1, "Fresh player incarnation has its own summon state");
                        summons.getFirst().setNoAi(true);
                        owner.setNoGravity(false);
                        enemy.setNoGravity(false);
                        nativeTickProbes.clear();
                        SkyWars2.LOGGER.info("[check] PASS skills");
                };
        }

        private static void checkLobbyRules(GameController game) {
                require(game.inLobby(), "Lobby rules require ready lobby");
                var player = game.server().getPlayerList().getPlayers().getFirst();
                player.setRemainingFireTicks(100);
                var arena = game.maps().level();
                var kept = new net.minecraft.world.entity.decoration.ArmorStand(arena, 2, 128, 2);
                kept.entityTags().add("map_object");
                arena.addFreshEntity(kept);
                var taggedAfterLoad = new net.minecraft.world.entity.decoration.ArmorStand(arena, 4, 128, 2);
                require(arena.addFreshEntity(taggedAfterLoad), "Post-load tag probe added");
                taggedAfterLoad.entityTags().add("strict_map_object");
                var retagged = new net.minecraft.world.entity.decoration.ArmorStand(arena, 5, 128, 2);
                retagged.entityTags().add("map_object");
                require(arena.addFreshEntity(retagged), "Retained tag-change probe added");
                game.maps().cleanupLobbyEntities();
                require(!retagged.isRemoved(), "Tag-change probe initially retained");
                retagged.entityTags().clear();
                // Force a complete audit window after direct tag mutation; no load event fires.
                for (int tick = 0; tick < 20; tick++)
                        game.maps().cleanupLobbyEntities();
                require(retagged.isRemoved(), "Direct tag mutation is caught within twenty lobby ticks");
                require(!taggedAfterLoad.isRemoved(), "Source tag assigned after load callback is respected");
                var removed = new net.minecraft.world.entity.decoration.ArmorStand(arena, 3, 128, 2);
                arena.addFreshEntity(removed);
                game.maps().cleanupLobbyEntities();
                require(removed.isRemoved(), "New untagged entity is removed before the next periodic audit");
                var overworld = game.server().overworld();
                boolean alreadyForced = overworld.getForceLoadedChunks()
                                .contains(net.minecraft.world.level.ChunkPos.pack(0, 0));
                overworld.setChunkForced(0, 0, true);
                overworld.getChunkAt(new net.minecraft.core.BlockPos(0, 128, 0));
                var other = new net.minecraft.world.entity.decoration.ArmorStand(overworld, 0, 128, 0);
                other.entityTags().add("strict_map_object");
                require(overworld.addFreshEntity(other), "Other-dimension probe added");
                // Forced chunks become visible asynchronously, especially on a fresh world.
                deferredTicks = 100;
                deferredCheck = () -> {
                        int visibleOther = 0;
                        for (var entity : overworld.getAllEntities())
                                visibleOther++;
                        SkyWars2.LOGGER.info(
                                        "[check] lobby-rules otherWorld={} forced={} visible={} probeLookup={} removed={}",
                                        other.level().dimension().identifier(),
                                        overworld.getForceLoadedChunks()
                                                        .contains(net.minecraft.world.level.ChunkPos.pack(0, 0)),
                                        visibleOther, overworld.getEntity(other.getUUID()) != null, other.isRemoved());
                        require(!kept.isRemoved(), "Arena map_object preserved");
                        require(!taggedAfterLoad.isRemoved(), "Arena tag assigned after addFreshEntity preserved");
                        require(removed.isRemoved(), "Untagged arena entity removed");
                        require(other.isRemoved(), "Tags do not protect entities in other dimensions");
                        require(player.getRemainingFireTicks() <= 0, "Lobby fire extinguished without powder snow");
                        kept.discard();
                        taggedAfterLoad.discard();
                        if (!alreadyForced)
                                overworld.setChunkForced(0, 0, false);
                        SkyWars2.LOGGER.info("[check] PASS lobby-rules");
                };
        }

        /**
         * Controlled operator benchmark, not a measurement of total server CPU/MSPT.
         */
        private static void measureLobbyCpu(GameController game) {
                require(game.inLobby(), "Lobby CPU benchmark requires ready lobby");
                require(game.server().getPlayerList().getPlayers().size() == 2,
                                "Benchmark requires exactly two test players");
                var probes = new java.util.ArrayList<net.minecraft.world.entity.decoration.ArmorStand>();
                var output = new com.google.gson.JsonObject();
                try {
                        for (int index = 0; index < 512; index++) {
                                var probe = new net.minecraft.world.entity.decoration.ArmorStand(game.maps().level(), 2,
                                                128, 2);
                                probe.entityTags().add("map_object");
                                require(game.maps().level().addFreshEntity(probe), "CPU benchmark probe added");
                                probes.add(probe);
                        }
                        output.addProperty("retainedProbeEntities", probes.size());
                        output.addProperty("players", 2);
                        output.addProperty("callsPerSample", CPU_SAMPLE_CALLS);
                        output.add("cleanupCpuNanosPerCall", measureCpu(game.maps()::cleanupLobbyEntities));
                        output.add("inventoryCpuNanosPerTwoPlayers", measureCpu(() -> {
                                for (var player : game.server().getPlayerList().getPlayers())
                                        game.enforceLobbyInventory(player);
                        }));
                        require(probes.stream().noneMatch(net.minecraft.world.entity.Entity::isRemoved),
                                        "CPU probes remain whitelisted");
                        java.nio.file.Files.writeString(java.nio.file.Path.of("lobby-cpu.json"),
                                        new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(output),
                                        StandardCharsets.UTF_8);
                        SkyWars2.LOGGER.info("[check] lobby-cpu {}", output);
                } catch (java.io.IOException error) {
                        throw new IllegalStateException("Cannot write CPU benchmark", error);
                } finally {
                        probes.forEach(net.minecraft.world.entity.Entity::discard);
                }
                SkyWars2.LOGGER.info("[check] PASS lobby-cpu");
        }

        private static com.google.gson.JsonArray measureCpu(Runnable work) {
                var bean = java.lang.management.ManagementFactory.getThreadMXBean();
                require(bean.isCurrentThreadCpuTimeSupported(), "JVM supports current-thread CPU timing");
                if (!bean.isThreadCpuTimeEnabled())
                        bean.setThreadCpuTimeEnabled(true);
                for (int iteration = 0; iteration < 8000; iteration++)
                        work.run();
                var samples = new com.google.gson.JsonArray();
                for (int sample = 0; sample < 7; sample++) {
                        long started = bean.getCurrentThreadCpuTime();
                        for (int iteration = 0; iteration < CPU_SAMPLE_CALLS; iteration++)
                                work.run();
                        samples.add((bean.getCurrentThreadCpuTime() - started) / (double) CPU_SAMPLE_CALLS);
                }
                return samples;
        }

        private static void snapshot(GameController game) {
                baseline.clear();
                for (var player : game.server().getPlayerList().getPlayers()) {
                        var p = game.players().get(player.getUUID());
                        baseline.put(player.getUUID(), new int[] { p.coins, p.games, p.wins, p.deaths,
                                        java.util.Arrays.stream(p.keys).sum() });
                }
        }

        private static int cageBarriers(GameController game) {
                int barriers = 0;
                for (var spawn : game.maps().spawns()) {
                        var feet = net.minecraft.core.BlockPos.containing(spawn.position());
                        for (int x = -1; x <= 1; x++)
                                for (int z = -1; z <= 1; z++)
                                        for (int y = -1; y <= 4; y++)
                                                if (game.maps().level().getBlockState(feet.offset(x, y, z))
                                                                .is(net.minecraft.world.level.block.Blocks.GLASS))
                                                        barriers++;
                }
                return barriers;
        }

        private static void createTestBots(GameController game) {
                require(game.inLobby(), "Create vanilla test players in the ready lobby");
                for (String name : BOT_NAMES) {
                        ServerPlayer existing = createBot(game, name);
                        require(existing != null && existing.getClass() == ServerPlayer.class,
                                        name + " must be a vanilla ServerPlayer, not Carpet EntityPlayerMPFake");
                }
                SkyWars2.LOGGER.info("[check] Created TestAlpha/TestBeta as vanilla ServerPlayer instances");
        }

        private static ServerPlayer createBot(GameController game, String name) {
                UUID uuid = offlineUuid(name);
                ServerPlayer existing = game.server().getPlayerList().getPlayer(uuid);
                if (existing != null)
                        return existing;
                GameProfile profile = new GameProfile(uuid, name);
                ServerPlayer player = new ServerPlayer(game.server(), game.maps().level(), profile,
                                ClientInformation.createDefault());
                game.server().getPlayerList().placeNewPlayer(carpetConnection(), player,
                                new CommonListenerCookie(profile, 0, player.clientInformation(), false));
                player.connection.handleAcceptPlayerLoad(new ServerboundPlayerLoadedPacket());
                return game.server().getPlayerList().getPlayer(uuid);
        }

        private static void checkChests(GameController game) {
                require(game.playing(), "Match chests generated");
                int chestCount = 0, stackCount = 0, nonempty = 0;
                for (var entity : game.maps().level().getAllEntities()) {
                        if (!(entity instanceof net.minecraft.world.entity.Marker)) continue;
                        if (entity.entityTags().stream().noneMatch(t -> t.equals("swrg.default")
                                        || t.equals("swrg.midle") || t.equals("swrg.center")))
                                continue;
                        var block = game.maps().level()
                                        .getBlockEntity(net.minecraft.core.BlockPos.containing(entity.position()));
                        require(block instanceof net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity,
                                        "Chest marker has native container");
                        var container = (net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity) block;
                        chestCount++;
                        for (int i = 0; i < container.getContainerSize(); i++) {
                                var stack = container.getItem(i);
                                if (stack.isEmpty())
                                        continue;
                                nonempty++;
                                if (stack.getCount() > 1)
                                        stackCount++;
                                var mods = stack.get(DataComponents.ATTRIBUTE_MODIFIERS);
                                if (mods != null)
                                        require(mods.modifiers().stream().noneMatch(
                                                        m -> m.modifier().id().toString().equals("minecraft:count")),
                                                        "Synthetic count modifier removed");
                        }
                }
                SkyWars2.LOGGER.info("[check] Generated {} chests, {} occupied slots, {} multi-item stacks", chestCount,
                                nonempty, stackCount);
                require(chestCount > 0 && nonempty > 0 && stackCount > 0,
                                "Real loot generated with multiple-item stacks");
        }

        private static void checkMapEditorCleanup(GameController game) {
                require(game.inLobby() && game.selectedMapReady() && "35".equals(game.config().mapId),
                                "Map 35 is fully prepared in the lobby");
                var level = game.maps().level();
                int spawns = 0, looks = 0, defaults = 0, midles = 0, centers = 0;
                level.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.BLOCK_DROPS, true, game.server());
                level.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.ENTITY_DROPS, true, game.server());
                for (var entity : level.getAllEntities()) {
                        if (entity.entityTags().contains("marker")
                                        && (entity instanceof net.minecraft.world.entity.item.FallingBlockEntity
                                                        || entity instanceof net.minecraft.world.entity.Display.BlockDisplay)) {
                                require(false, "Technical marker visualization survived map cleanup: "
                                                + entity.getType());
                        }
                        if (!(entity instanceof net.minecraft.world.entity.Marker)) continue;
                        if (entity.entityTags().contains("swrg.spawn")) spawns++;
                        if (entity.entityTags().contains("swrg.look")) looks++;
                        if (entity.entityTags().contains("swrg.default")) defaults++;
                        if (entity.entityTags().contains("swrg.midle")) midles++;
                        if (entity.entityTags().contains("swrg.center")) centers++;
                }
                require(spawns == 8 && looks == 1 && defaults == 8 && midles == 8 && centers == 4,
                                "Map 35 retains all 29 native spawn, look, and chest marker anchors");
                require(itemEntityIds(level).isEmpty(),
                                "Map 35 load clears old chest contents without dropping items into the arena");

                var beforeFirstRefill = itemEntityIds(level);
                game.maps().fillChests(false);
                int chests = checkMap35ChestContainers(level);
                requireNewItemEntitiesAbsent(level, beforeFirstRefill,
                                "First map 35 chest refill does not eject loot onto the ground");

                var beforeSecondRefill = itemEntityIds(level);
                game.maps().fillChests(false);
                int refilledChests = checkMap35ChestContainers(level);
                require(refilledChests == chests,
                                "Repeated refill preserves all map 35 chest marker anchors");
                requireNewItemEntitiesAbsent(level, beforeSecondRefill,
                                "Repeated map 35 chest refill does not eject old contents onto the ground");
                SkyWars2.LOGGER.info("[check] PASS map-editor-cleanup chests={} spawnAnchors={} lookAnchors={} technicalMarkers=0",
                                chests, spawns, looks);
        }

        private static int checkMap35ChestContainers(net.minecraft.server.level.ServerLevel level) {
                int chestMarkers = 0, nonemptyContainers = 0;
                for (var entity : level.getAllEntities()) {
                        if (!(entity instanceof net.minecraft.world.entity.Marker)) continue;
                        if (entity.entityTags().stream().noneMatch(tag -> tag.equals("swrg.default")
                                        || tag.equals("swrg.midle") || tag.equals("swrg.center"))) continue;
                        var blockEntity = level.getBlockEntity(
                                        net.minecraft.core.BlockPos.containing(entity.position()));
                        require(blockEntity instanceof net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity,
                                        "Map 35 chest anchor points to a native container");
                        var container = (net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity) blockEntity;
                        chestMarkers++;
                        for (int slot = 0; slot < container.getContainerSize(); slot++) {
                                if (!container.getItem(slot).isEmpty()) {
                                        nonemptyContainers++;
                                        break;
                                }
                        }
                }
                require(chestMarkers == 20 && nonemptyContainers == 20,
                                "All 20 map 35 chest marker containers remain filled");
                return chestMarkers;
        }

        private static java.util.Set<UUID> itemEntityIds(net.minecraft.server.level.ServerLevel level) {
                var ids = new java.util.HashSet<UUID>();
                for (var entity : level.getAllEntities())
                        if (entity instanceof net.minecraft.world.entity.item.ItemEntity) ids.add(entity.getUUID());
                return ids;
        }

        private static void requireNewItemEntitiesAbsent(net.minecraft.server.level.ServerLevel level,
                        java.util.Set<UUID> before, String message) {
                for (var entity : level.getAllEntities())
                        if (entity instanceof net.minecraft.world.entity.item.ItemEntity
                                        && !before.contains(entity.getUUID()))
                                require(false, message + ": " + ((net.minecraft.world.entity.item.ItemEntity)entity).getItem());
        }

        private static void setAirdropConfig(GameController game) {
                require(game.inLobby(), "Airdrop timing fixture can only be set in lobby");
                if (fastConfigSnapshot == null)
                        fastConfigSnapshot = GameConfigSnapshot.from(game.config());
                GameConfig config = game.config();
                config.lives = 2;
                config.countdownSeconds = 5;
                config.stageOneSeconds = 1;
                config.stageTwoSeconds = 2;
                config.endingSeconds = 15;
                config.stageOneEvent = 2;
                config.stageTwoEvent = 8; // selection 8 resolves to stage-two event 7: center airdrop.
                config.save();
                SkyWars2.LOGGER.info("[check] Airdrop fixture saved: phase1=1 phase2=2 event2=8");
        }

        private static void checkAirdrop(GameController game) {
                require(game.stage() == GameController.Stage.PHASE_TWO,
                                "Airdrop check runs after the real phase-two transition");
                require(game.config().stageOneSeconds == 1 && game.config().stageTwoSeconds == 2
                                && game.config().stageTwoEvent == 8,
                                "Configured stage-two event selects source airdrop event 7");
                var level = game.maps().level();
                var chickens = java.util.stream.StreamSupport.stream(level.getAllEntities().spliterator(), false)
                                .filter(entity -> entity instanceof net.minecraft.world.entity.animal.chicken.Chicken
                                                && entity.entityTags().contains("skywars2.airdrop"))
                                .map(entity -> (net.minecraft.world.entity.animal.chicken.Chicken) entity)
                                .toList();
                require(chickens.size() == 10, "Stage-two event spawns ten tagged chicken carriers: " + chickens.size());
                int multiItemStacks = 0;
                var cartPositions = new java.util.HashMap<net.minecraft.core.BlockPos, net.minecraft.world.level.block.state.BlockState>();
                for (var chicken : chickens) {
                        require(!chicken.isNoGravity() && chicken.getY() <= 110.001,
                                        "Airdrop carrier uses normal falling physics from source Y=110");
                        var carts = chicken.getPassengers().stream()
                                        .filter(net.minecraft.world.entity.vehicle.minecart.MinecartChest.class::isInstance)
                                        .map(net.minecraft.world.entity.vehicle.minecart.MinecartChest.class::cast)
                                        .toList();
                        require(carts.size() == 1, "Each chicken carries exactly one chest minecart");
                        var cart = carts.getFirst();
                        cartPositions.put(cart.blockPosition(), level.getBlockState(cart.blockPosition()));
                        require(cart.getVehicle() == chicken && cart.isCurrentlyGlowing()
                                        && game.items().currentEpoch(chicken) && game.items().currentEpoch(cart)
                                        && cart.entityTags().contains("skywars2.airdrop")
                                        && cart.entityTags().contains("swrg.center")
                                        && cart.entityTags().contains("swrg.chest"),
                                        "Cart rides the chicken and keeps glowing source chest tags");
                        cart.getItem(0); // Force the native minecart loot table before inspecting its slots.
                        boolean cartHasLoot = false;
                        for (int slot = 0; slot < cart.getContainerSize(); slot++) {
                                var stack = cart.getItem(slot);
                                if (stack.isEmpty())
                                        continue;
                                cartHasLoot = true;
                                if (stack.getCount() > 1)
                                        multiItemStacks++;
                                var modifiers = stack.get(DataComponents.ATTRIBUTE_MODIFIERS);
                                if (modifiers != null)
                                        require(modifiers.modifiers().stream().noneMatch(modifier ->
                                                        modifier.modifier().id().toString().equals("minecraft:count")),
                                                        "Airdrop loot has no synthetic minecraft:count modifier");
                        }
                        require(cartHasLoot, "Each center cart generates its native loot table");
                }
                require(multiItemStacks > 0, "Airdrop center loot retains native stack counts greater than one");
                checkAirdropNormalizerFixture();
                game.maps().fillChests(false);
                checkChests(game);
                for (var entry : cartPositions.entrySet())
                        require(level.getBlockState(entry.getKey()).equals(entry.getValue()),
                                        "Map chest refill does not create block chests at tagged cart positions");
        }

        private static void checkAirdropNormalizerFixture() {
                var stack = new ItemStack(Items.IRON_SWORD);
                var genuine = stack.get(DataComponents.ATTRIBUTE_MODIFIERS);
                require(genuine != null && !genuine.modifiers().isEmpty(),
                                "Normalizer fixture begins with genuine native sword attributes");
                var synthetic = new net.minecraft.world.entity.ai.attributes.AttributeModifier(
                                net.minecraft.resources.Identifier.parse("minecraft:count"), 4.0,
                                net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADD_VALUE);
                var modifiers = net.minecraft.world.item.component.ItemAttributeModifiers.builder();
                for (var entry : genuine.modifiers())
                        modifiers.add(entry.attribute(), entry.modifier(), entry.slot(), entry.display());
                modifiers.add(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE, synthetic,
                                net.minecraft.world.entity.EquipmentSlotGroup.MAINHAND);
                stack.set(DataComponents.ATTRIBUTE_MODIFIERS, modifiers.build());
                var fixture = new net.minecraft.world.SimpleContainer(1);
                fixture.setItem(0, stack);
                MapManager.normalizeLootCounts(fixture);
                require(fixture.getItem(0).getCount() == 4,
                                "Synthetic modifier amount becomes the actual stack count");
                var normalized = fixture.getItem(0).get(DataComponents.ATTRIBUTE_MODIFIERS);
                require(normalized != null
                                && normalized.modifiers().stream().noneMatch(entry ->
                                                entry.modifier().id().equals(synthetic.id())),
                                "Container normalizer removes only synthetic count attributes");
                require(normalized.modifiers().equals(genuine.modifiers()),
                                "Container normalizer preserves every genuine attribute modifier");
        }

        private static void stopAirdropMatch(GameController game) {
                require(game.stage() == GameController.Stage.PHASE_TWO,
                                "Airdrop stop fixture requires the active phase-two match");
                game.stopMatch();
        }

        private static void checkAirdropCleanup(GameController game) {
                require(game.inLobby(), "Airdrop cleanup is checked after match stop");
                require(java.util.stream.StreamSupport.stream(game.maps().level().getAllEntities().spliterator(), false)
                                .noneMatch(entity -> entity.entityTags().contains("skywars2.airdrop")),
                                "Match stop removes every chicken carrier and chest cart from the airdrop");
                var level = game.maps().level();
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var stale = new net.minecraft.world.entity.animal.chicken.Chicken(
                                net.minecraft.world.entity.EntityTypes.CHICKEN, level);
                var cart = new net.minecraft.world.entity.vehicle.minecart.MinecartChest(
                                net.minecraft.world.entity.EntityTypes.CHEST_MINECART, level);
                stale.setPos(player.position()); cart.setPos(player.position());
                stale.entityTags().add("skywars2.airdrop");
                cart.entityTags().addAll(java.util.List.of("skywars2.airdrop", "swrg.center", "swrg.chest"));
                try {
                        cart.startRiding(stale, true, false);
                        level.addFreshEntityWithPassengers(stale);
                        game.maps().queueLobbyEntity(stale); game.maps().queueLobbyEntity(cart);
                        game.maps().cleanupLobbyEntities();
                        require(stale.isRemoved() && cart.isRemoved(),
                                        "Lobby rejects reloaded stale airdrops despite their source map tags");
                } finally { cart.discard(); stale.discard(); }
        }

        static UUID offlineUuid(String name) {
                return UUID.nameUUIDFromBytes(("OfflinePlayer:" + name).getBytes(StandardCharsets.UTF_8));
        }

        private static Connection carpetConnection() {
                try {
                        Class<?> fakeConnection = Class.forName("carpet.patches.FakeClientConnection");
                        Constructor<?> constructor = fakeConnection.getDeclaredConstructor(PacketFlow.class);
                        constructor.setAccessible(true);
                        return (Connection) constructor.newInstance(PacketFlow.SERVERBOUND);
                } catch (ClassNotFoundException missingCarpet) {
                        throw new IllegalStateException(
                                        "Install Carpet to run /sw check bots; it supplies FakeClientConnection.",
                                        missingCarpet);
                } catch (ReflectiveOperationException | ClassCastException failure) {
                        throw new IllegalStateException(
                                        "Could not create Carpet FakeClientConnection (PacketFlow.SERVERBOUND).",
                                        failure);
                }
        }

        private static void setFastConfig(GameController game) {
                require(game.inLobby(), "Fast test timings can only be set in lobby");
                if (fastConfigSnapshot == null)
                        fastConfigSnapshot = GameConfigSnapshot.from(game.config());
                GameConfig config = game.config();
                config.lives = 2;
                config.countdownSeconds = 5;
                config.stageOneSeconds = 3;
                config.stageTwoSeconds = 6;
                config.endingSeconds = 15;
                config.stageOneEvent = 2; // selection 2 = first phase-one event (speed)
                config.stageTwoEvent = 6; // selection 6 = phase-two shrinking border
                config.save();
                SkyWars2.LOGGER.info(
                                "[check] Fast fixture saved: lives=2 countdown=5 phase1=3 phase2=6 ending=15 events=2,6");
        }

        private static void restoreFastConfig(GameController game) {
                require(game.inLobby(), "Restore test timings after match returns to lobby");
                require(fastConfigSnapshot != null, "Run /sw check fast before restore");
                fastConfigSnapshot.apply(game.config());
                game.config().save();
                fastConfigSnapshot = null;
                SkyWars2.LOGGER.info("[check] PASS restore");
        }

        private static void startWatch(GameController game) {
                require(game.inLobby(), "Start the map-preparation watch from lobby before /sw start");
                require(watcher == null, "A watch is already running");
                snapshot(game);
                watcher = new WatchState(game.stage());
                // Re-selecting the current map exercises asynchronous preparation while the GUI
                // stays in the lobby.
                require(game.selectMap(null, game.config().mapId, game.config().broken),
                                "Current map preparation accepted");
                SkyWars2.LOGGER.info("[check] watch armed; waiting for selected map preparation, then start a match");
        }

        private static void startLivesTest(GameController game) {
                require(game.inLobby(), "Run /sw check lives from lobby to start the extra-lives scenario");
                require(game.config().lives >= 2, "Set /sw check fast first (lives=2)");
                for (String name : BOT_NAMES) {
                        ServerPlayer bot = game.server().getPlayerList().getPlayer(offlineUuid(name));
                        require(bot != null && bot.getClass() == ServerPlayer.class, "Run /sw check bots first");
                }
                require(game.canStart(null), "Current map must have enough spawn points for all online players");
                watcher = null;
                snapshot(game);
                livesState = new LivesState(offlineUuid(BOT_NAMES[0]));
                game.requestStart(null, false);
                SkyWars2.LOGGER.info("[check] lives scenario armed; waiting for the real match start");
        }

        private static void tickLives(GameController game) {
                LivesState state = livesState;
                if (state == null)
                        return;
                if (++state.waitTicks > 20 * 60) {
                        failLives("Timed out in step " + state.step);
                        return;
                }
                ServerPlayer player = game.server().getPlayerList().getPlayer(state.victim);
                if (state.step == LivesStep.WAIT_PLAYING) {
                        if (!game.playing())
                                return;
                        require(game.lives(state.victim) == 2, "TestAlpha starts with two lives");
                        damageByCommand(game, player);
                        require(game.lives(state.victim) == 1 && game.awaitingRespawn(state.victim),
                                        "First real damage-command death decrements life and awaits respawn");
                        state.step = LivesStep.WAIT_FIRST_RESPAWN;
                        state.waitTicks = 0;
                        return;
                }
                if (player == null) {
                        failLives("TestAlpha disconnected during " + state.step);
                        return;
                }
                if (state.step == LivesStep.WAIT_FIRST_RESPAWN) {
                        if (!game.awaitingRespawn(state.victim) || !player.isDeadOrDying())
                                return;
                        sendRespawnPacket(player);
                        ServerPlayer respawned = game.server().getPlayerList().getPlayer(state.victim);
                        require(respawned != null && !respawned.isDeadOrDying(),
                                        "Serverbound PERFORM_RESPAWN creates the replacement player");
                        require(game.lives(state.victim) == 1 && !game.awaitingRespawn(state.victim),
                                        "One life remains after real respawn callback");
                        require(respawned.gameMode.getGameModeForPlayer() == GameType.SURVIVAL,
                                        "Respawned player returns to survival");
                        state.step = LivesStep.WAIT_SECOND_DEATH;
                        state.waitTicks = 0;
                        return;
                }
                if (state.step == LivesStep.WAIT_SECOND_DEATH) {
                        if (game.awaitingRespawn(state.victim) || player.isDeadOrDying())
                                return;
                        damageByCommand(game, player);
                        require(game.lives(state.victim) == 0 && game.awaitingRespawn(state.victim),
                                        "Second real damage-command death eliminates the participant");
                        state.step = LivesStep.WAIT_ELIMINATION;
                        state.waitTicks = 0;
                        return;
                }
                if (state.step == LivesStep.WAIT_ELIMINATION && player.isDeadOrDying()) {
                        sendRespawnPacket(player);
                        ServerPlayer eliminated = game.server().getPlayerList().getPlayer(state.victim);
                        require(eliminated != null && game.isObserver(eliminated)
                                        && eliminated.gameMode() == GameType.ADVENTURE,
                                        "Zero-life respawn packet is converted to spectator");
                        require(game.lives(state.victim) == 0, "Elimination preserves zero lives");
                        livesState = null;
                        SkyWars2.LOGGER.info(
                                        "[check] PASS lives: vanilla packet respawn with one remaining life, then elimination");
                }
        }

        private static void damageByCommand(GameController game, ServerPlayer player) {
                require(player != null, "Damage-test player is online");
                require(game.command("damage " + player.getScoreboardName() + " 100 minecraft:generic_kill"),
                                "Vanilla damage command parsed and executed");
        }

        private static void sendRespawnPacket(ServerPlayer deadPlayer) {
                deadPlayer.connection.handleClientCommand(new ServerboundClientCommandPacket(
                                ServerboundClientCommandPacket.Action.PERFORM_RESPAWN));
                // Vanilla 26.3 waits for this acknowledgement before accepting damage again.
                deadPlayer.connection.handleAcceptPlayerLoad(new ServerboundPlayerLoadedPacket());
                require(deadPlayer.connection.hasClientLoaded(), "Client load acknowledgement accepted after respawn");
        }

        private static void tickWatch(GameController game) {
                WatchState state = watcher;
                if (state == null)
                        return;
                GameController.Stage current = game.stage();
                if (current == GameController.Stage.LOBBY && !state.countdown && !state.ending && game.maps().busy()) {
                        if (state.preparationMenuChecks == 0)
                                runWatchCheck("preparation-actions", () -> checkLoadingActions(game));
                        long started = System.nanoTime();
                        if (state.preparationMenuChecks % 10 == 0) {
                                runWatchCheck("preparation-navigation", () -> {
                                        ServerPlayer player = game.server().getPlayerList().getPlayers().getFirst();
                                        game.menus().open(player, GameMenus.Page.HUB);
                                        click(currentGui(player), 6);
                                        require(currentGui(player).getGuiElement(0).getItemStack().is(Items.TRIAL_KEY),
                                                        "Shop navigation works while map is busy");
                                        click(currentGui(player), 18);
                                        require(currentGui(player).getGuiElement(0).getItemStack().is(Items.COMPARATOR),
                                                        "Back navigation works while map is busy");
                                });
                                state.maxPreparationMenuNanos = Math.max(state.maxPreparationMenuNanos,
                                                System.nanoTime() - started);
                        }
                        state.preparationMenuChecks++;
                }
                if (current != state.lastStage) {
                        switch (current) {
                                case COUNTDOWN -> {
                                        require(!state.countdown && state.lastStage == GameController.Stage.LOBBY,
                                                        "Start moves directly from lobby to countdown");
                                        runWatchCheck("countdown", () -> {
                                                require(state.preparationMenuChecks > 0,
                                                                "GUI was checked while the selected map was preparing in lobby");
                                                require(game.selectedMapReady(),
                                                                "Selected map was ready before countdown");
                                                require(game.maps().loadingChunkCount() == 0,
                                                                "Temporary chunk tickets released before countdown");
                                                for (ServerPlayer player : game.alivePlayers()) {
                                                        require(!player.getAbilities().mayfly
                                                                        && !player.getAbilities().flying
                                                                        && !player.getAbilities().invulnerable,
                                                                        "Temporary loading abilities removed before countdown");
                                                }
                                                SkyWars2.LOGGER.info(
                                                                "[check] Lobby preparation GUI ticks={} maxNavigationMs={}",
                                                                state.preparationMenuChecks,
                                                                state.maxPreparationMenuNanos / 1_000_000.0);
                                                require(game.alivePlayers().size() >= 2,
                                                                "Countdown has enrolled participants");
                                                require(cageBarriers(game) > 0, "Countdown has source glass cages");
                                        });
                                        state.countdown = true;
                                        if (staleMenu != null)
                                                runWatchCheck("stale-menu", () -> checkStaleMenu(game));
                                }
                                case PLAYING -> {
                                        require(state.countdown && !state.playing,
                                                        "Playing follows countdown exactly once");
                                        runWatchCheck("playing", () -> {
                                                require(game.alivePlayers().size() >= 2, "Two live participants");
                                                for (ServerPlayer p : game.alivePlayers()) {
                                                        require(p.gameMode.getGameModeForPlayer() == GameType.SURVIVAL,
                                                                        "Survival after countdown");
                                                        require(p.getHealth() > 0, "Positive health at match start");
                                                }
                                        });
                                        state.playing = true;
                                }
                                case PHASE_ONE -> {
                                        require(state.playing && !state.phaseOne,
                                                        "Phase one follows play exactly once");
                                        state.phaseOne = true;
                                }
                                case PHASE_TWO -> {
                                        require(state.phaseOne && !state.phaseTwo,
                                                        "Phase two follows phase one exactly once");
                                        state.phaseTwo = true;
                                }
                                case ENDING -> {
                                        require(state.playing && !state.ending, "Ending follows the match");
                                        require(state.phaseOne && (game.config().stageTwoEvent == 0 || state.phaseTwo),
                                                        "Timed stages were observed before ending");
                                        runWatchCheck("ending", () -> {
                                                int winners = 0;
                                                for (var p : game.server().getPlayerList().getPlayers()) {
                                                        var prior = baseline.get(p.getUUID());
                                                        var now = game.players().get(p.getUUID());
                                                        if (prior == null || now.wins != prior[2] + 1)
                                                                continue;
                                                        winners++;
                                                        require(now.coins >= prior[0] + 110, "Start and victory coins");
                                                        require(java.util.Arrays.stream(now.keys).sum() == prior[4] + 1,
                                                                        "One victory key");
                                                        require(p.gameMode.getGameModeForPlayer() == GameType.CREATIVE,
                                                                        "Winner creative mode");
                                                }
                                                require(winners == 1, "Exactly one winner credited");
                                        });
                                        state.ending = true;
                                }
                                case LOBBY -> {
                                        if (state.ending) {
                                                runWatchCheck("lobby",
                                                                () -> require(game.inLobby(), "Return to ready lobby"));
                                                if (!state.failed)
                                                        SkyWars2.LOGGER.info(
                                                                        "[check] PASS watch: lobby preparation -> countdown -> playing -> phases -> ending -> lobby");
                                                else
                                                        SkyWars2.LOGGER.error(
                                                                        "[check] FAIL watch: one or more asynchronous assertions failed");
                                                watcher = null;
                                                return;
                                        }
                                        if (state.countdown || state.playing)
                                                watchFailure("Match returned to lobby before ending");
                                }
                                default -> {
                                }
                        }
                        state.lastStage = current;
                }
        }

        private static void runWatchCheck(String name, Runnable check) {
                try {
                        check.run();
                        SkyWars2.LOGGER.info("[check] PASS watch/{}", name);
                } catch (RuntimeException failure) {
                        watchFailure(name + ": " + failure.getMessage());
                }
        }

        private static void watchFailure(String message) {
                if (watcher != null)
                        watcher.failed = true;
                SkyWars2.LOGGER.error("[check] FAIL watch: {}", message);
        }

        private static void failLives(String message) {
                livesState = null;
                SkyWars2.LOGGER.error("[check] FAIL lives: {}", message);
        }

        /**
         * Exercises Polymer packet codecs, native packet handling, and effect/dimension hooks
         * against the real ServerPlayer entities in a live match. The fixtures have no client sockets.
         */
        private static void checkFullInvisibility(GameController game) {
                require(game.playing(), "Full invisibility requires a live match");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var attacker = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                require(player != null && attacker != null && game.allowDamage(player)
                                && game.allowDamage(attacker), "Both native test players are alive participants");
                require(!player.hasEffect(MobEffects.INVISIBILITY), "Fresh fixture starts without invisibility");
                var originalPose = player.getPose();
                var originalScale = player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.SCALE);
                require(originalScale != null, "Player has the native scale attribute");
                double scaleValue = originalScale.getBaseValue();
                var playerState = new WandThirdPlayerState(player, game.items().mana());
                var attackerState = new WandThirdPlayerState(attacker, game.items().mana());
                var overlay = eu.pb4.polymer.core.api.entity.PolymerEntity.get(player);
                require(overlay instanceof FullInvisibility, "Registered PLAYER overlay is installed");
                var viewerConnection = fullInvisibilityPacketConnection(attacker);
                var selfConnection = fullInvisibilityPacketConnection(player);
                var provider = (net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider) viewerConnection;
                var selfProvider = (net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider) selfConnection;
                var attackerContext = provider.getPacketContext();
                var selfContext = selfProvider.getPacketContext();
                require(eu.pb4.polymer.common.api.PolymerCommonUtils.getPlayer(attackerContext) == attacker
                                && eu.pb4.polymer.common.api.PolymerCommonUtils.getPlayer(selfContext) == player,
                                "Synthetic PacketContext resolves the exact real recipient fixtures");
                var originalAttackerCamera = attacker.getCamera();
                int entityId = player.getId();
                var nativeBox = player.getBoundingBox();
                var savedEffectOutput = net.minecraft.world.level.storage.TagValueOutput.createWithContext(
                                net.minecraft.util.ProblemReporter.DISCARDING, player.registryAccess());
                var restoredEffectProbe = new ServerPlayer(game.server(), player.level(),
                                new GameProfile(UUID.randomUUID(), "InvisibilityRestoredProbe"),
                                net.minecraft.server.level.ClientInformation.createDefault());
                var mount = new net.minecraft.world.entity.vehicle.minecart.Minecart(
                                net.minecraft.world.entity.EntityTypes.MINECART, player.level());
                try {
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                                        MobEffects.INVISIBILITY, 200, 2));
                        player.saveWithoutId(savedEffectOutput);
                        restoredEffectProbe.load(net.minecraft.world.level.storage.TagValueInput.create(
                                        net.minecraft.util.ProblemReporter.DISCARDING, player.registryAccess(),
                                        savedEffectOutput.buildResult()));
                        var restoredOverlay = eu.pb4.polymer.core.api.entity.PolymerEntity.get(restoredEffectProbe);
                        require(restoredEffectProbe.hasEffect(MobEffects.INVISIBILITY)
                                        && restoredOverlay instanceof FullInvisibility
                                        && restoredOverlay.getPolymerEntityType(attackerContext)
                                                        == net.minecraft.world.entity.EntityTypes.INTERACTION,
                                        "Saved level III invisibility rebuilds the hidden overlay during native entity load");

                        player.setNoGravity(true);
                        attacker.setNoGravity(true);
                        player.teleportTo(player.level(), .5, 200, .5, java.util.Set.of(), 0, 0, true);
                        attacker.teleportTo(attacker.level(), .5, 200, 1.4, java.util.Set.of(), 0, 0, true);
                        nativeBox = player.getBoundingBox();
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST, ItemStack.EMPTY);
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.LEGS, ItemStack.EMPTY);
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET, ItemStack.EMPTY);
                        player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,
                                        new ItemStack(Items.DIAMOND_HELMET));
                        player.setPose(net.minecraft.world.entity.Pose.STANDING);
                        originalScale.setBaseValue(1.0);
                        player.refreshDimensions();
                        nativeBox = player.getBoundingBox();
                        require(Math.abs(player.getBbWidth() - .6f) < .0001
                                        && Math.abs(player.getBbHeight() - 1.8f) < .0001,
                                        "Production scale 1 starts from the native .6 by 1.8 player bounds");

                        // Amplifier 2 is level III. Normal effect callbacks must switch the other
                        // viewer to Interaction while retaining this exact native player entity/id.
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                                        MobEffects.INVISIBILITY, 200, 2));
                        require(eu.pb4.polymer.core.api.entity.PolymerEntity.get(player) == overlay,
                                        "The proxy overlay remains attached to the same ServerPlayer");
                        require(player.getId() == entityId && player.getBoundingBox().equals(nativeBox),
                                        "Visibility transition retains native entity id and server hitbox");
                        require(overlay.getPolymerEntityType(attackerContext) == net.minecraft.world.entity.EntityTypes.INTERACTION
                                        && overlay.getPolymerEntityType(selfContext) == net.minecraft.world.entity.EntityTypes.PLAYER,
                                        "Level III uses Interaction for another viewer and PLAYER for self");
                        requireFullInvisibilityMetadata(overlay, player, attacker);
                        requireFullInvisibilitySpawnCodec(player, attacker, provider);
                        requireFullInvisibilityMetadataCodec(overlay, player, attacker, provider);
                        requireFullInvisibilityPickupCodec(player, provider, false);
                        requireFullInvisibilityPickupCodec(player, selfProvider, true);
                        var pickup = new net.minecraft.world.entity.item.ItemEntity(player.level(),
                                        player.getX(), player.getY(), player.getZ(), new ItemStack(Items.SLIME_BALL, 3));
                        pickup.setNoPickUpDelay();
                        player.getInventory().setItem(0, ItemStack.EMPTY);
                        int slimeBeforePickup = player.getInventory().countItem(Items.SLIME_BALL);
                        try {
                                require(player.level().addFreshEntity(pickup), "Pickup fixture enters the real server world");
                                pickup.playerTouch(player);
                                require(pickup.isRemoved() && player.getInventory().countItem(Items.SLIME_BALL) == slimeBeforePickup + 3,
                                                "Fully invisible player still receives the actual picked-up items");
                        } finally { pickup.discard(); }
                        // The proxy consumes client RMB; Polymer must recover vanilla item use
                        // after the real server Player interaction returns PASS, without double use.
                        attacker.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,
                                        new ItemStack(Items.SNOWBALL, 2));
                        attacker.connection.handleInteract(new net.minecraft.network.protocol.game.ServerboundInteractPacket(
                                        player.getId(), net.minecraft.world.InteractionHand.MAIN_HAND, Vec3.ZERO, false));
                        attacker.connection.handleClientTickEnd(new net.minecraft.network.protocol.game.ServerboundClientTickEndPacket());
                        require(attacker.getMainHandItem().getCount() == 1,
                                        "Polymer recovers exactly one vanilla item use when aiming at the invisible proxy");
                        for (var thrown : player.level().getEntitiesOfClass(
                                        net.minecraft.world.entity.projectile.throwableitemprojectile.Snowball.class,
                                        attacker.getBoundingBox().inflate(8), entity -> entity.getOwner() == attacker))
                                thrown.discard();
                        mount.setPos(player.position());
                        mount.setNoGravity(true);
                        require(player.level().addFreshEntity(mount) && player.startRiding(mount, true, true),
                                        "Invisible player mounts a native minecart");
                        mount.positionRider(player);
                        requireFullInvisibilityPassengerCodec(mount, player, provider, false);
                        requireFullInvisibilityPassengerCodec(mount, player, selfProvider, true);
                        var head = new com.mojang.datafixers.util.Pair<>(net.minecraft.world.entity.EquipmentSlot.HEAD,
                                        player.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.HEAD));
                        require(overlay.getPolymerVisibleEquipment(java.util.List.of(head), attacker).isEmpty()
                                        && overlay.getPolymerVisibleEquipment(java.util.List.of(head), player)
                                                        .equals(java.util.List.of(head)),
                                        "Hidden equipment is empty for others and unchanged for self");
                        attacker.setCamera(player);
                        requireFullInvisibilityPickupCodec(player, provider, true);
                        requireFullInvisibilityPassengerCodec(mount, player, provider, true);
                        require(overlay.getPolymerEntityType(attackerContext)
                                                == net.minecraft.world.entity.EntityTypes.PLAYER
                                        && overlay.getPolymerVisibleEquipment(java.util.List.of(head), attacker)
                                                        .equals(java.util.List.of(head)),
                                        "Camera owner sees the target as a normal PLAYER with equipment during spectating");
                        attacker.setCamera(originalAttackerCamera);
                        requireFullInvisibilityPickupCodec(player, provider, false);
                        requireFullInvisibilityPassengerCodec(mount, player, provider, false);
                        require(overlay.getPolymerEntityType(attackerContext)
                                        == net.minecraft.world.entity.EntityTypes.INTERACTION,
                                        "Leaving the target camera restores the hidden proxy for the same viewer");

                        // The built-in effect replacement cannot reliably lower amplifier while
                        // retaining duration, so model the native removal/add sequence and test both
                        // transition edges explicitly through their registered callbacks.
                        player.removeEffect(MobEffects.INVISIBILITY);
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                                        MobEffects.INVISIBILITY, 200, 1));
                        require(overlay.getPolymerEntityType(attackerContext) == net.minecraft.world.entity.EntityTypes.PLAYER,
                                        "Transition from level III to level II restores PLAYER view");
                        requireFullInvisibilityPickupCodec(player, provider, true);
                        player.removeEffect(MobEffects.INVISIBILITY);
                        require(overlay.getPolymerEntityType(attackerContext) == net.minecraft.world.entity.EntityTypes.PLAYER,
                                        "Clearing invisibility keeps the native PLAYER view");

                        // Scale and pose alter the native player dimensions. The registered
                        // dimensions hook must refresh Interaction's full metadata template.
                        player.setPose(net.minecraft.world.entity.Pose.CROUCHING);
                        originalScale.setBaseValue(.5);
                        player.refreshDimensions();
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                                        MobEffects.INVISIBILITY, 200, 2));
                        requireFullInvisibilityMetadata(overlay, player, attacker);
                        player.setPose(net.minecraft.world.entity.Pose.STANDING);
                        originalScale.setBaseValue(1.25);
                        player.refreshDimensions();
                        requireFullInvisibilityMetadata(overlay, player, attacker);

                        // Drive the native packet handler against this same authoritative ServerPlayer.
                        // Projectile and generic damage sources exercise their usual server guards.
                        player.setHealth(player.getMaxHealth());
                        player.damageCooldownTime = 0;
                        player.setInvulnerableTime(0);
                        attacker.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,
                                        new ItemStack(Items.DIAMOND_SWORD));
                        attacker.resetAttackStrengthTicker();
                        attacker.damageCooldownTime = 0;
                        attacker.setInvulnerableTime(0);
                        float beforeMelee = player.getHealth();
                        attacker.connection.handleAttack(new net.minecraft.network.protocol.game.ServerboundAttackPacket(
                                        player.getId()));
                        require(player.getHealth() < beforeMelee,
                                        "Native ServerboundAttackPacket damages the invisible real player entity");
                        var arrow = new net.minecraft.world.entity.projectile.arrow.Arrow(player.level(), attacker,
                                        new ItemStack(Items.ARROW), null);
                        player.damageCooldownTime = 0;
                        player.setInvulnerableTime(0);
                        float beforeProjectile = player.getHealth();
                        require(player.hurtServer(player.level(), player.damageSources().arrow(arrow, attacker), 1)
                                        && player.getHealth() < beforeProjectile,
                                        "Projectile damage source still hits the invisible real player entity");
                        player.damageCooldownTime = 0;
                        player.setInvulnerableTime(0);
                        float beforeOther = player.getHealth();
                        require(player.hurtServer(player.level(), player.damageSources().generic(), 1)
                                        && player.getHealth() < beforeOther,
                                        "Other native damage still hits the invisible real player entity");

                        // Expiry is allowed to run through normal native player ticks, then the
                        // deferred callback verifies the final proxy state and restores the fixture.
                        player.removeEffect(MobEffects.INVISIBILITY);
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                                        MobEffects.INVISIBILITY, 40, 2));
                        nativeTickProbes.add(player.getUUID());
                        deferredTicks = 50;
                        deferredCheck = () -> {
                                try {
                                        require(!player.hasEffect(MobEffects.INVISIBILITY),
                                                        "Level III invisibility naturally expires after native ticks");
                                        require(overlay.getPolymerEntityType(attackerContext)
                                                        == net.minecraft.world.entity.EntityTypes.PLAYER,
                                                        "Effect expiry returns the proxy to native PLAYER view");
                                        SkyWars2.LOGGER.info("[check] PASS full-invisibility");
                                } finally {
                                        nativeTickProbes.remove(player.getUUID());
                                        player.stopRiding();
                                        mount.discard();
                                        attacker.setCamera(originalAttackerCamera);
                                        originalScale.setBaseValue(scaleValue);
                                        player.setPose(originalPose);
                                        player.refreshDimensions();
                                        playerState.restore(game);
                                        attackerState.restore(game);
                                }
                        };
                } catch (RuntimeException failure) {
                        nativeTickProbes.remove(player.getUUID());
                        player.stopRiding();
                        mount.discard();
                        attacker.setCamera(originalAttackerCamera);
                        originalScale.setBaseValue(scaleValue);
                        player.setPose(originalPose);
                        player.refreshDimensions();
                        playerState.restore(game);
                        attackerState.restore(game);
                        throw failure;
                } finally {
                        // Untracked native probe has no Connection; discard without sending effect-removal packets.
                        restoredEffectProbe.discard();
                }
        }

        private static net.minecraft.network.Connection fullInvisibilityPacketConnection(ServerPlayer viewer) {
                return new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND) {
                        @Override
                        public net.minecraft.network.PacketListener getPacketListener() {
                                return viewer.connection;
                        }
                };
        }

        private static void requireFullInvisibilityPassengerCodec(net.minecraft.world.entity.Entity mount,
                        ServerPlayer rider, net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider provider,
                        boolean visible) {
                var raw = io.netty.buffer.Unpooled.buffer();
                try {
                        var buffer = new net.minecraft.network.RegistryFriendlyByteBuf(raw, rider.registryAccess());
                        net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider, () -> {
                                var packet = new net.minecraft.network.protocol.game.ClientboundSetPassengersPacket(mount);
                                net.minecraft.network.protocol.game.ClientboundSetPassengersPacket.STREAM_CODEC.encode(buffer, packet);
                                var decoded = net.minecraft.network.protocol.game.ClientboundSetPassengersPacket.STREAM_CODEC.decode(buffer);
                                require(decoded.getVehicle() == mount.getId()
                                                && (java.util.Arrays.stream(decoded.getPassengers()).anyMatch(id -> id == rider.getId()) == visible),
                                                "Passenger codec preserves real camera/self mount and detaches external proxy");
                                require(mount.hasPassenger(rider) && rider.getVehicle() == mount,
                                                "Packet filtering does not dismount the real server player");
                        });
                } finally { raw.release(); }
        }

        private static void requireFullInvisibilityPickupCodec(ServerPlayer collector,
                        net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider provider, boolean visible) {
                var raw = io.netty.buffer.Unpooled.buffer();
                try {
                        var buffer = new net.minecraft.network.RegistryFriendlyByteBuf(raw, collector.registryAccess());
                        // Reuse one packet for different viewers: encoding must never mutate the broadcast packet.
                        var packet = new net.minecraft.network.protocol.game.ClientboundTakeItemEntityPacket(
                                        123456789, collector.getId(), 2);
                        net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider, () -> {
                                net.minecraft.network.protocol.game.ClientboundTakeItemEntityPacket.STREAM_CODEC.encode(buffer, packet);
                                var decoded = net.minecraft.network.protocol.game.ClientboundTakeItemEntityPacket.STREAM_CODEC.decode(buffer);
                                require(decoded.getPlayerId() == (visible ? collector.getId() : -1),
                                                "Pickup codec never gives the client an Interaction as LivingEntity collector");
                                require(decoded.getItemId() == packet.getItemId() && decoded.getAmount() == 2
                                                && packet.getPlayerId() == collector.getId(),
                                                "Pickup count, item ID and original broadcast packet remain intact");
                                require(visible || collector.level().getEntity(decoded.getPlayerId()) == null,
                                                "Hidden pickup resolves to no collector, so vanilla skips only the flight particle");
                        });
                } finally { raw.release(); }
        }

        private static void requireFullInvisibilitySpawnCodec(ServerPlayer player, ServerPlayer viewer,
                        net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider provider) {
                var raw = io.netty.buffer.Unpooled.buffer();
                try {
                        var buffer = new net.minecraft.network.RegistryFriendlyByteBuf(raw, player.registryAccess());
                        net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider, () -> {
                                require(eu.pb4.polymer.common.api.PolymerCommonUtils.getPlayer(
                                                provider.getPacketContext()) == viewer,
                                                "Spawn codec PacketContext resolves the intended viewer");
                                var packet = eu.pb4.polymer.core.api.entity.PolymerEntityUtils.setEntityContext(
                                                new net.minecraft.network.protocol.game.ClientboundAddEntityPacket(
                                                                player, 0, player.blockPosition()), player);
                                net.minecraft.network.protocol.game.ClientboundAddEntityPacket.STREAM_CODEC
                                                .encode(buffer, packet);
                                buffer.readerIndex(0);
                                var decoded = net.minecraft.network.protocol.game.ClientboundAddEntityPacket.STREAM_CODEC
                                                .decode(buffer);
                                require(decoded.getId() == player.getId()
                                                && decoded.getType() == net.minecraft.world.entity.EntityTypes.INTERACTION,
                                                "Polymer spawn codec sends the same entity id with Interaction type to the other viewer");
                        });
                } finally {
                        raw.release();
                }
        }

        private static void requireFullInvisibilityMetadataCodec(eu.pb4.polymer.core.api.entity.PolymerEntity overlay,
                        ServerPlayer player, ServerPlayer viewer,
                        net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider provider) {
                var metadata = new java.util.ArrayList<net.minecraft.network.syncher.SynchedEntityData.DataValue<?>>();
                overlay.modifyRawTrackedData(metadata, viewer, true);
                var raw = io.netty.buffer.Unpooled.buffer();
                try {
                        var buffer = new net.minecraft.network.RegistryFriendlyByteBuf(raw, player.registryAccess());
                        net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider, () -> {
                                require(eu.pb4.polymer.common.api.PolymerCommonUtils.getPlayer(
                                                provider.getPacketContext()) == viewer,
                                                "Metadata codec PacketContext resolves the intended viewer");
                                var packet = eu.pb4.polymer.core.api.entity.PolymerEntityUtils.setEntityContext(
                                                new net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket(
                                                                player.getId(), metadata), player);
                                net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket.STREAM_CODEC
                                                .encode(buffer, packet);
                                buffer.readerIndex(0);
                                var decoded = net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket.STREAM_CODEC
                                                .decode(buffer);
                                require(decoded.id() == player.getId(),
                                                "Polymer metadata codec retains the native player entity id");
                                var proxy = new net.minecraft.world.entity.Interaction(
                                                net.minecraft.world.entity.EntityTypes.INTERACTION, player.level());
                                proxy.getEntityData().assignValues(decoded.packedItems());
                                require(proxy.isInvisible() && proxy.isPickable()
                                                && !proxy.isOnFire() && !proxy.isCurrentlyGlowing()
                                                && Math.abs(proxy.getBbWidth() - player.getBbWidth()) < .0001
                                                && Math.abs(proxy.getBbHeight() - player.getBbHeight()) < .0001,
                                                "Decoded native Interaction metadata is invisible, pickable, unlit, and sized to the live player's BB");
                        });
                } finally {
                        raw.release();
                }
        }

        private static void requireFullInvisibilityMetadata(eu.pb4.polymer.core.api.entity.PolymerEntity overlay,
                        ServerPlayer player, ServerPlayer viewer) {
                var actual = new java.util.ArrayList<net.minecraft.network.syncher.SynchedEntityData.DataValue<?>>();
                overlay.modifyRawTrackedData(actual, viewer, true);
                var template = new net.minecraft.world.entity.Interaction(
                                net.minecraft.world.entity.EntityTypes.INTERACTION, player.level());
                template.setInvisible(true);
                template.setWidth(player.getBbWidth());
                template.setHeight(player.getBbHeight());
                template.setResponse(true);
                var expected = new java.util.ArrayList<net.minecraft.network.syncher.SynchedEntityData.DataValue<?>>();
                for (var field : eu.pb4.polymer.core.api.entity.PolymerEntityUtils
                                .getDefaultSynchedEntityData(net.minecraft.world.entity.EntityTypes.INTERACTION)) {
                        if (field != null) {
                                var accessor = field.getAccessor();
                                expected.add(fullInvisibilityValue(template, accessor));
                        }
                }
                require(actual.equals(expected),
                                "Viewer metadata exactly matches native Interaction schema with player's current BB");
                require(actual.size() == expected.size(), "No PLAYER-only metadata fields leak into Interaction metadata");
        }

        private static <T> net.minecraft.network.syncher.SynchedEntityData.DataValue<T> fullInvisibilityValue(
                        net.minecraft.world.entity.Interaction entity,
                        net.minecraft.network.syncher.EntityDataAccessor<T> accessor) {
                return net.minecraft.network.syncher.SynchedEntityData.DataValue.create(accessor,
                                entity.getEntityData().get(accessor));
        }

        private static void require(boolean condition, String message) {
                if (!condition)
                        throw new IllegalStateException(message);
        }

        private static void checkMenus(GameController game) {
                boolean ranked = game.config().ranked;
                try {
                        game.config().ranked = true;
                        checkUnlockedMenus(game);
                } finally { game.config().ranked = ranked; }
        }

        /** Bounded permission/config integration check; it never starts a match or changes map selection. */
        private static void checkAdminControls(GameController game) {
                require(game.inLobby(), "Admin-control checks run in the lobby");
                var alpha = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var beta = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                require(alpha != null && beta != null && game.server().getPlayerList().getPlayer(alpha.getUUID()) == alpha
                                && game.server().getPlayerList().getPlayer(beta.getUUID()) == beta,
                                "Admin-control fixture uses both online test players");

                boolean alphaAdmin = alpha.entityTags().contains("admin");
                boolean betaAdmin = beta.entityTags().contains("admin");
                String originalMap = game.config().mapId;
                boolean originalBroken = game.config().broken;
                int originalLives = game.config().lives;
                boolean halloween = game.config().eventHalloween;
                boolean november = game.config().eventNovember;
                boolean tournament = game.config().eventTournament;
                eu.pb4.sgui.api.gui.SlotBasedGui settingsGui = null;
                eu.pb4.sgui.api.elements.GuiElement settingButton = null;
                eu.pb4.sgui.api.elements.GuiElement resetButton = null;
                eu.pb4.sgui.api.gui.SlotBasedGui mapsGui = null;
                eu.pb4.sgui.api.elements.GuiElement mapButton = null;
                try {
                        alpha.entityTags().add("admin");
                        beta.entityTags().remove("admin");
                        require(game.mayControlMatch(alpha) && !game.mayControlMatch(beta)
                                        && game.mayControlMatch(null),
                                        "An online tagged admin controls the match; ordinary players and observers do not, console does");

                        game.menus().open(alpha, GameMenus.Page.SETTINGS);
                        settingsGui = currentGui(alpha);
                        settingButton = settingsGui.getGuiElement(9);
                        resetButton = settingsGui.getGuiElement(26);
                        require(settingButton != null && resetButton != null, "Admin can open lobby settings and reset controls");
                        int livesBeforeStaleClick = game.config().lives;
                        beta.entityTags().add("admin");
                        alpha.entityTags().remove("admin");
                        settingButton.getGuiCallback().click(9, ClickType.MOUSE_LEFT, ContainerInput.PICKUP, settingsGui);
                        require(game.config().lives == livesBeforeStaleClick,
                                        "A settings callback captured as admin rechecks the live tag before mutation");
                        int resetProbeLives = GameConfig.resetDefaults().lives == 1 ? 2 : 1;
                        game.config().lives = resetProbeLives;
                        resetButton.getGuiCallback().click(26, ClickType.MOUSE_LEFT, ContainerInput.PICKUP, settingsGui);
                        require(game.config().lives == resetProbeLives && game.config().mapId.equals(originalMap),
                                        "A stale reset callback rechecks live permission before restoring defaults");
                        game.menus().open(alpha, GameMenus.Page.SETTINGS);
                        require(currentGui(alpha) == settingsGui,
                                        "An adminless player cannot open lobby settings");

                        alpha.entityTags().add("admin");
                        beta.entityTags().remove("admin");
                        game.menus().open(alpha, GameMenus.Page.MAPS);
                        mapsGui = currentGui(alpha);
                        var selectedButton = OriginalGuiDesign.sourceMapButton(alpha, game.config().mapId, true);
                        require(selectedButton != null && selectedButton.slot() >= 0,
                                        "Current selected map has a stable native menu slot");
                        mapButton = mapsGui.getGuiElement(selectedButton.slot());
                        require(mapButton != null, "Admin can open the current map selection menu");
                        beta.entityTags().add("admin");
                        alpha.entityTags().remove("admin");
                        require(!game.selectMap(alpha, originalMap, originalBroken)
                                        && game.config().mapId.equals(originalMap) && game.config().broken == originalBroken,
                                        "Denied same-map selection reports no mutation or map preparation");
                        mapButton.getGuiCallback().click(selectedButton.slot(), ClickType.MOUSE_LEFT,
                                        ContainerInput.PICKUP, mapsGui);
                        require(game.config().mapId.equals(originalMap) && game.config().broken == originalBroken,
                                        "A stale map callback rechecks live admin permission");

                        alpha.entityTags().add("admin");
                        beta.entityTags().remove("admin");
                        game.requestStart(beta, false);
                        game.requestStart(beta, true);
                        require(game.inLobby() && !game.canStart(beta),
                                        "Ordinary player's normal and quick starts remain denied while an admin is online");
                        alpha.entityTags().remove("admin");
                        require(game.mayControlMatch(beta) && game.canStart(beta) == game.canStart(alpha),
                                        "With no online admins, either ordinary player can control the match without a host-only restriction");
                        alpha.entityTags().add("admin");
                        game.menus().open(beta, GameMenus.Page.STATS);
                        require(currentGui(beta).isOpen(), "Personal stats menu remains available while match controls are admin-restricted");
                        alpha.entityTags().remove("admin");

                        var dispatcher = game.server().getCommands().getDispatcher();
                        var playerSource = beta.createCommandSourceStack().withPermission(
                                        net.minecraft.server.permissions.PermissionSet.NO_PERMISSIONS);
                        boolean nonOpRejected = false;
                        try { dispatcher.execute("settings", playerSource); }
                        catch (com.mojang.brigadier.exceptions.CommandSyntaxException expected) { nonOpRejected = true; }
                        require(nonOpRejected, "Native /settings root remains protected by operator permission");
                        boolean nonOpNestedRejected = false;
                        try { dispatcher.execute("settings event halloween true", playerSource); }
                        catch (com.mojang.brigadier.exceptions.CommandSyntaxException expected) { nonOpNestedRejected = true; }
                        require(nonOpNestedRejected, "Native /settings event remains protected by operator permission");
                        alpha.entityTags().add("admin");
                        var taggedNonOpSource = alpha.createCommandSourceStack().withPermission(
                                        net.minecraft.server.permissions.PermissionSet.NO_PERMISSIONS);
                        boolean taggedNonOpRejected = false;
                        try { dispatcher.execute("settings", taggedNonOpSource); }
                        catch (com.mojang.brigadier.exceptions.CommandSyntaxException expected) { taggedNonOpRejected = true; }
                        require(taggedNonOpRejected, "Admin tag alone does not grant operator-only /settings");
                        var opSource = beta.createCommandSourceStack().withPermission(
                                        net.minecraft.server.permissions.PermissionSet.ALL_PERMISSIONS);
                        require(dispatcher.execute("settings", opSource) == 1,
                                        "Native operator /settings command succeeds without an admin tag");
                        boolean busyBeforeMapSetting = game.maps().busy();
                        require(dispatcher.execute("settings map " + originalMap, opSource) == 1
                                        && game.config().mapId.equals(originalMap) && game.config().broken == originalBroken
                                        && game.maps().busy() == busyBeforeMapSetting,
                                        "Operator /settings map can reapply the current map despite another tagged admin, without starting a paste");
                        alpha.entityTags().remove("admin");
                        require(dispatcher.execute("settings event halloween true", opSource) == 1
                                        && dispatcher.execute("settings event november true", opSource) == 1
                                        && dispatcher.execute("settings event tournament true", opSource) == 1,
                                        "Native operator event settings accept all three persistent flags");
                        require(game.config().eventHalloween && game.config().eventNovember
                                        && game.config().eventTournament,
                                        "Event settings immediately update live config");
                        require(GameConfig.load().eventHalloween && GameConfig.load().eventNovember
                                        && GameConfig.load().eventTournament,
                                        "All event flags persist to the normal config file");
                        var defaults = GameConfig.resetDefaults();
                        require(!defaults.eventHalloween && !defaults.eventNovember && !defaults.eventTournament,
                                        "All event flags default to false");
                        var live = game.config();
                        boolean resetWouldBeMapSafe = live.lives == defaults.lives && live.health == defaults.health
                                        && live.countdownSeconds == defaults.countdownSeconds
                                        && live.stageOneSeconds == defaults.stageOneSeconds
                                        && live.stageTwoSeconds == defaults.stageTwoSeconds
                                        && live.endingSeconds == defaults.endingSeconds
                                        && live.stageOneEvent == defaults.stageOneEvent
                                        && live.stageTwoEvent == defaults.stageTwoEvent
                                        && live.pvpMode == defaults.pvpMode && live.gameMode == defaults.gameMode
                                        && live.day == defaults.day && live.vanillaKits == defaults.vanillaKits
                                        && live.vanillaSkills == defaults.vanillaSkills && live.lbcKits == defaults.lbcKits
                                        && live.lbcSkills == defaults.lbcSkills && live.lbcLevelups == defaults.lbcLevelups
                                        && live.offhandWands == defaults.offhandWands
                                        && live.lbcLevelupLimit == defaults.lbcLevelupLimit
                                        && live.lbcTrinketLimit == defaults.lbcTrinketLimit
                                        && live.noBorders == defaults.noBorders
                                        && live.mapId.equals(defaults.mapId) && live.broken == defaults.broken;
                        if (resetWouldBeMapSafe) {
                                alpha.entityTags().add("admin");
                                game.menus().open(alpha, GameMenus.Page.SETTINGS);
                                var resetGui = currentGui(alpha);
                                var reset = resetGui.getGuiElement(26);
                                require(reset != null, "Default-options fixture exposes the settings reset button");
                                reset.getGuiCallback().click(26, ClickType.MOUSE_LEFT, ContainerInput.PICKUP, resetGui);
                                require(game.config().eventHalloween && game.config().eventNovember
                                                && game.config().eventTournament,
                                                "Lobby GUI reset preserves all OP-only event service flags");
                                alpha.entityTags().remove("admin");
                        }
                        boolean invalidRejected = false;
                        try { dispatcher.execute("settings event halloween maybe", opSource); }
                        catch (com.mojang.brigadier.exceptions.CommandSyntaxException expected) { invalidRejected = true; }
                        require(invalidRejected && game.config().eventHalloween,
                                        "Invalid event boolean is rejected without changing the saved flag");
                        require(dispatcher.execute("settings event halloween false", opSource) == 1
                                        && !game.config().eventHalloween && !GameConfig.load().eventHalloween,
                                        "False event values persist through the same operator command path");
                        SkyWars2.LOGGER.info("[check] PASS admin-controls");
                } catch (com.mojang.brigadier.exceptions.CommandSyntaxException failure) {
                        throw new IllegalStateException("An authorized settings command failed", failure);
                } finally {
                        if (alphaAdmin) alpha.entityTags().add("admin"); else alpha.entityTags().remove("admin");
                        if (betaAdmin) beta.entityTags().add("admin"); else beta.entityTags().remove("admin");
                        game.config().lives = originalLives;
                        game.config().mapId = originalMap;
                        game.config().broken = originalBroken;
                        game.config().eventHalloween = halloween;
                        game.config().eventNovember = november;
                        game.config().eventTournament = tournament;
                        game.config().save();
                        game.menus().open(alpha, GameMenus.Page.HUB);
                        game.menus().open(beta, GameMenus.Page.HUB);
                }
        }

        private static void checkUnlockedMenus(GameController game) {
                require(game.inLobby(), "Menu checks require the ready lobby");
                require(game.server().getPlayerList().getPlayers().size() >= 2,
                                "Menu checks require two online players");
                ServerPlayer player = game.server().getPlayerList().getPlayers().getFirst();
                PlayerStore.Profile profile = game.players().get(player.getUUID());

                for (GameMenus.Page page : GameMenus.Page.values()) {
                        game.menus().open(player, page);
                        SlotBasedGui gui = currentGui(player);
                        require(gui instanceof SimpleGui simple && simple.getVirtualSize() == 27,
                                        "SGui 9x3 wrapper opened for " + page);
                        require(gui.getLockPlayerInventory(), "Player inventory locked on " + page);
                        require(gui.isOpen(), "SGui reports open for " + page);
                        checkClientTranslation(((SimpleGui) gui).getTitle());
                        for (int slot = 0; slot < 27; slot++) {
                                var element = gui.getGuiElement(slot);
                                if (element == null)
                                        continue;
                                checkClientTranslation(element.getItemStack().getHoverName());
                                var lore = element.getItemStack().get(DataComponents.LORE);
                                if (lore != null)
                                        for (Component line : lore.lines())
                                                checkClientTranslation(line);
                        }
                }
                checkClientTranslation(game.status());
                checkClientTranslation(game.settingsSummary());
                checkClientTranslation(SkyWars2.text("bossbar.countdown", 5));

                game.menus().open(player, GameMenus.Page.HUB);
                SlotBasedGui hub = currentGui(player);
                requireItem(hub, 0, Items.COMPARATOR, "Original settings comparator at slot 0");
                click(hub, 0);
                SlotBasedGui settings = currentGui(player);
                requireItem(settings, 24, Items.COOKED_PORKCHOP, "Original health setting at slot 24");
                int previousHealth = game.config().health;
                int expectedHealth = previousHealth < 2 ? 2
                                : previousHealth < 10 ? 10
                                                : previousHealth < 20 ? 20
                                                                : previousHealth < 40 ? 40
                                                                                : previousHealth < 60 ? 60 : 2;
                try {
                        click(settings, 24);
                        require(game.config().health == expectedHealth,
                                        "Health setting callback updates current config");
                        require(GameConfig.load().health == expectedHealth, "Health setting callback persists config");
                } finally {
                        game.config().health = previousHealth;
                        game.config().save();
                }

                game.menus().open(player, GameMenus.Page.VANILLA_KITS);
                var kitOne = currentGui(player).getGuiElement(0).getItemStack();
                Component kitName = kitOne.getHoverName();
                translation(kitName, "swrg.kit.a1");
                requireLegacyStyle(kitName, net.minecraft.ChatFormatting.AQUA, "Legacy kit name style");
                var kitLore = kitOne.get(DataComponents.LORE);
                require(kitLore != null && kitLore.lines().size() == 3,
                                "Legacy kit lore has exactly three original rows");
                String[] kitLoreKeys = { "swrg.lore.kit.a1.0", "swrg.lore.kit.a1.1", "swrg.lore.kit.a1.2" };
                for (int row = 0; row < kitLoreKeys.length; row++) {
                        Component line = kitLore.lines().get(row);
                        translation(line, kitLoreKeys[row]);
                        requireLegacyStyle(line, net.minecraft.ChatFormatting.GRAY, "Legacy kit lore row " + row);
                }

                game.menus().open(player, GameMenus.Page.VANILLA_SKILLS);
                Component spiderSkill = currentGui(player).getGuiElement(0).getItemStack().getHoverName();
                translation(spiderSkill, "swrg.skill.a1");
                requireLegacyStyle(spiderSkill, net.minecraft.ChatFormatting.AQUA, "Legacy skill name style");
                var spiderLore = currentGui(player).getGuiElement(0).getItemStack().get(DataComponents.LORE);
                require(spiderLore != null && spiderLore.lines().size() == 1,
                                "Legacy skill lore has exactly its original description row");
                translation(spiderLore.lines().getFirst(), "swrg.lore.skill.a1.0");
                requireLegacyStyle(spiderLore.lines().getFirst(), net.minecraft.ChatFormatting.GRAY,
                                "Legacy skill lore style");

                var windSkill = currentGui(player).getGuiElement(11).getItemStack();
                Component windName = windSkill.getHoverName();
                translation(windName, "wind_runner_skill");
                requireLegacyStyle(windName, net.minecraft.ChatFormatting.WHITE, "Legacy Wind Wings name style");
                var windLore = windSkill.get(DataComponents.LORE);
                require(windLore != null && windLore.lines().size() == 1,
                                "Legacy Wind Wings lore has exactly its original description row");
                translation(windLore.lines().getFirst(), "wind_runner_skill.lore.1");
                requireLegacyStyle(windLore.lines().getFirst(), net.minecraft.ChatFormatting.GRAY,
                                "Legacy Wind Wings lore style");

                var dualist = currentGui(player).getGuiElement(12).getItemStack();
                translation(dualist.getHoverName(), "dualist_skill");
                requireLegacyStyle(dualist.getHoverName(), net.minecraft.ChatFormatting.WHITE,
                                "Legacy Vex skill name style");
                var dualistLore = dualist.get(DataComponents.LORE);
                require(dualistLore != null && dualistLore.lines().size() == 1,
                                "Legacy Vex skill lore has exactly its original description row");
                translation(dualistLore.lines().getFirst(), "dualist_skill.lore");
                requireLegacyStyle(dualistLore.lines().getFirst(), net.minecraft.ChatFormatting.GRAY,
                                "Legacy Vex skill lore style");
                checkDynamicDesign(game, player, profile);

                int previousCoins = profile.coins;
                int previousMemcoins = profile.memcoins;
                int[] previousKeys = profile.keys.clone();
                try {
                        profile.coins = 1000;
                        game.players().save();
                        game.menus().open(player, GameMenus.Page.KEY_SHOP);
                        SlotBasedGui shop = currentGui(player);
                        int[][] costs = { { 100, 400, 700 }, { 150, 600, 1050 }, { 150, 600, 1050 }, { 200, 800, 1400 },
                                        { 100, 400, 750 } };
                        for (int key = 0; key < 5; key++) {
                                for (int tier = 0; tier < 3; tier++) {
                                        int slot = key * 3 + tier;
                                        var stack = shop.getGuiElement(slot).getItemStack();
                                        require(stack.is(key == 4 ? Items.GOLD_NUGGET : Items.TRIAL_KEY),
                                                        "Original key shop material at slot " + slot);
                                        var lore = stack.get(DataComponents.LORE);
                                        require(lore != null && lore.lines().size() == 3,
                                                        "Original quantity, price and balance lore at slot " + slot);
                                        checkClientTranslation(stack.getHoverName());
                                        for (var line : lore.lines())
                                                checkClientTranslation(line);
                                        int beforeCoins = profile.coins, beforeMemcoins = profile.memcoins,
                                                        beforeKeys = profile.keys[key];
                                        profile.coins = 10000;
                                        profile.memcoins = 10000;
                                        game.menus().open(player, GameMenus.Page.KEY_SHOP);
                                        click(currentGui(player), slot);
                                        require((key == 4 ? profile.memcoins : profile.coins) == 10000
                                                        - costs[key][tier], "Source key price at slot " + slot);
                                        require(profile.keys[key] == beforeKeys + (tier == 0 ? 1 : tier == 1 ? 5 : 10),
                                                        "Source key quantity at slot " + slot);
                                        profile.coins = beforeCoins;
                                        profile.memcoins = beforeMemcoins;
                                        profile.keys[key] = beforeKeys;
                                }
                        }
                        game.menus().open(player, GameMenus.Page.KEY_SHOP);
                        shop = currentGui(player);

                        click(shop, 0);
                        require(profile.coins == 900, "One key click charges exactly 100 coins");
                        require(profile.keys[0] == previousKeys[0] + 1, "One key click grants exactly one key");
                        PlayerStore.Profile persisted = PlayerStore.load().get(player.getUUID());
                        require(persisted.coins == 900 && persisted.keys[0] == previousKeys[0] + 1,
                                        "Key purchase is persisted");

                        stalePlayer = player;
                        staleMenu = currentGui(player);
                        staleShopButton = staleMenu.getGuiElement(0);
                        require(staleShopButton != null && staleShopButton.getItemStack().is(Items.TRIAL_KEY),
                                        "Keep real keyshop callback for stale-menu suite");
                } finally {
                        profile.coins = previousCoins;
                        profile.memcoins = previousMemcoins;
                        System.arraycopy(previousKeys, 0, profile.keys, 0, profile.keys.length);
                        game.players().save();
                }
        }

        private static void checkStaleMenu(GameController game) {
                require(game.stage() == GameController.Stage.COUNTDOWN, "Stale menu check requires countdown stage");
                require(staleMenu != null && stalePlayer != null && staleShopButton != null,
                                "Run /skywars check menus in the lobby first");
                require(game.server().getPlayerList().getPlayer(stalePlayer.getUUID()) != null,
                                "Stale-menu test player remains online");
                PlayerStore.Profile profile = game.players().get(stalePlayer.getUUID());
                int coins = profile.coins;
                int[] keys = profile.keys.clone();
                // The live menu is reused during navigation; retain the actual old button,
                // rather than looking up whichever new page now occupies slot 0.
                staleShopButton.getGuiCallback().click(0, ClickType.MOUSE_LEFT, ContainerInput.PICKUP, staleMenu);
                require(profile.coins == coins, "Stale keyshop callback cannot charge during countdown");
                require(java.util.Arrays.equals(profile.keys, keys),
                                "Stale keyshop callback cannot grant keys during countdown");
                staleMenu = null;
                staleShopButton = null;
                stalePlayer = null;
        }

        private static void checkLoadingActions(GameController game) {
                require(game.inLobby() && game.canUseMenus() && game.maps().busy(),
                                "Lobby menus remain available during map preparation");
                ServerPlayer player = game.server().getPlayerList().getPlayers().getFirst();
                require(player.gameMode.getGameModeForPlayer() == GameType.ADVENTURE,
                                "Vanilla client can send compass use-item packets during lobby preparation");
                if (staleMenu != null) {
                        require(currentGui(stalePlayer) == staleMenu && staleMenu.isOpen(),
                                        "Map preparation keeps the existing menu open");
                }
                for (GameMenus.Page page : GameMenus.Page.values()) {
                        game.menus().open(player, page);
                        require(currentGui(player).isOpen(), "Menu page opens during lobby map preparation: " + page);
                }
                int health = game.config().health;
                String mapId = game.config().mapId;
                game.menus().open(player, GameMenus.Page.SETTINGS);
                try {
                        click(currentGui(player), 24);
                        require(game.config().health != health,
                                        "Lobby health setting can change during map preparation");
                        require(game.config().mapId.equals(mapId), "Changing a non-map setting keeps the selected map");
                } finally {
                        game.config().health = health;
                        game.config().save();
                        game.menus().open(player, GameMenus.Page.SETTINGS);
                }
                require(game.config().health == health && game.config().mapId.equals(mapId),
                                "Fixture restores health and selected map after testing a lobby setting");
                game.requestStart(player, false);
                require(game.inLobby() && game.maps().busy() && game.config().mapId.equals(mapId),
                                "Start is rejected while selected-map preparation remains busy");
                player.getInventory().setSelectedSlot(GameController.MENU_COMPASS_SLOT);
                require(player.getMainHandItem().is(Items.COMPASS),
                                "Lobby keeps the menu compass during map preparation");
                player.connection.handleUseItem(new net.minecraft.network.protocol.game.ServerboundUseItemPacket(
                                net.minecraft.world.InteractionHand.MAIN_HAND, 0, player.getYRot(), player.getXRot()));
                require(currentGui(player).getGuiElement(0).getItemStack().is(Items.COMPARATOR),
                                "Native compass packet opens the main menu during lobby preparation");
        }

        private static void checkMenuNavigation(GameController game) {
                require(game.inLobby(), "Navigation checks require the ready lobby");
                var player = game.server().getPlayerList().getPlayers().getFirst();
                game.menus().open(player, GameMenus.Page.SETTINGS);
                require(currentGui(player).getGuiElement(25) == null, "Global language button removed");
                int containerId = player.containerMenu.containerId;
                int previousMode = game.config().gameMode;
                try {
                        // Р•РґРёРЅСЃС‚РІРµРЅРЅР°СЏ BedWars-СЃС‚СЂР°РЅРёС†Р° СЃР±СЂР°СЃС‹РІР°РµС‚ РІРѕР·РјРѕР¶РЅС‹Р№ СЃС‚Р°СЂС‹Р№ РёРЅРґРµРєСЃ РїРµСЂРµРґ РїСЂРѕРІРµСЂРєРѕР№.
                        game.config().gameMode = 3;
                        game.menus().open(player, GameMenus.Page.MAPS);
                        for (int mode : new int[] { 1, 2, 3, 4, 1 }) {
                                game.config().gameMode = mode;
                                game.menus().open(player, GameMenus.Page.MAPS);
                                String[] pages = mode == 3 || mode == 4
                                                ? new String[] { "2000b" } : new String[] { "2000", "2100", "2200" };
                                for (int repeat = 0; repeat < 8; repeat++) {
                                        for (int index = 0; index < pages.length; index++) {
                                                var mapGui = currentGui(player);
                                                translation(mapGui.getGuiElement(0).getItemStack().getHoverName(),
                                                                "swrg.gui.map." + pages[index] + ".0");
                                                for (int slot = 0; slot < 27; slot++) {
                                                        var element = mapGui.getGuiElement(slot);
                                                        if (element == null || slot == 18 || slot == 26) continue;
                                                        Component name = element.getItemStack().getHoverName();
                                                        require(name.getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents text
                                                                        && text.getKey().startsWith("swrg.gui.map." + pages[index] + "."),
                                                                        "Every map card belongs to the current mode/page: " + mode + "/" + pages[index]);
                                                }
                                                if (index + 1 < pages.length)
                                                        inventoryClick(player, 26, 0, ContainerInput.PICKUP);
                                                require(player.containerMenu.containerId == containerId,
                                                                "Navigation preserves the open container ID");
                                                requireLobbyInventory(player);
                                        }
                                        require(currentGui(player).getGuiElement(26) == null,
                                                        "Last mode-specific map page has no next button");
                                        for (int index = 1; index < pages.length; index++)
                                                inventoryClick(player, 18, 0, ContainerInput.PICKUP);
                                }
                        }
                        String selectedMap = game.config().mapId;
                        var stage = game.stage();
                        // РљР»РёРє РїРѕ СЃС‚Р°СЂРѕРјСѓ РјРµРЅСЋ РїРѕСЃР»Рµ СЃРјРµРЅС‹ СЂРµР¶РёРјР° РѕР±РЅРѕРІР»СЏРµС‚ СЃС‚СЂР°РЅРёС†Сѓ, РЅРµ Р·Р°РїСѓСЃРєР°СЏ Р·Р°РіСЂСѓР·РєСѓ.
                        game.config().gameMode = 3;
                        inventoryClick(player, 0, 0, ContainerInput.PICKUP);
                        translation(currentGui(player).getGuiElement(0).getItemStack().getHoverName(), "swrg.gui.map.2000b.0");
                        game.config().gameMode = 1;
                        inventoryClick(player, 0, 0, ContainerInput.PICKUP);
                        translation(currentGui(player).getGuiElement(0).getItemStack().getHoverName(), "swrg.gui.map.2000.0");
                        require(game.config().mapId.equals(selectedMap) && game.stage() == stage,
                                        "Stale cross-mode cards never select or load the other mode's map");
                        inventoryClick(player, 26, 0, ContainerInput.PICKUP);
                        inventoryClick(player, 26, 0, ContainerInput.PICKUP);
                        game.config().gameMode = 3;
                        game.menus().open(player, GameMenus.Page.MAPS);
                        translation(currentGui(player).getGuiElement(0).getItemStack().getHoverName(), "swrg.gui.map.2000b.0");
                        require(currentGui(player).getGuiElement(26) == null,
                                        "Switching from the third SkyWars page clamps the single BedWars page");
                        inventoryClick(player, 18, 0, ContainerInput.PICKUP);
                        requireItem(currentGui(player), 0, Items.COMPARATOR,
                                        "Back on the only BedWars map page returns to the main menu");
                } finally {
                        game.config().gameMode = previousMode;
                        game.menus().open(player);
                }
                var profile = game.players().get(player.getUUID());
                int kit = profile.lbcKit, skill = profile.lbcSkill, trinket = profile.lbcTrinket;
                int[] levelups = profile.levelups.clone();
                boolean ranked = game.config().ranked;
                try {
                        game.config().ranked = true;
                        for (var page : new GameMenus.Page[] { GameMenus.Page.LBC_KITS, GameMenus.Page.LBC_SKILLS,
                                        GameMenus.Page.LBC_LEVELUPS, GameMenus.Page.LBC_TRINKETS }) {
                                profile.lbcKit = 3;
                                profile.lbcSkill = 4;
                                profile.lbcTrinket = 5;
                                java.util.Arrays.fill(profile.levelups, 6);
                                game.menus().open(player, page);
                                requireItem(currentGui(player), 25, Items.BARRIER,
                                                "Perk reset appears on first page: " + page);
                                if (page != GameMenus.Page.LBC_SKILLS) {
                                        String model = switch (page) {
                                                case LBC_KITS -> "lbc:broken_totem";
                                                case LBC_LEVELUPS -> "lbc:luck_clover";
                                                default -> "lbc:trinket_0";
                                        };
                                        require(net.minecraft.resources.Identifier.parse(model)
                                                        .equals(currentGui(player).getGuiElement(0)
                                                                        .getItemStack().get(DataComponents.ITEM_MODEL)),
                                                        "Loot codec preserves source item model: " + model);
                                }
                                inventoryClick(player, 26, 0, ContainerInput.PICKUP);
                                requireItem(currentGui(player), 25, Items.BARRIER,
                                                "Perk reset appears on second page: " + page);
                                require(currentGui(player).getGuiElement(26) == null,
                                                "Last perk page has no next button");
                                if (page != GameMenus.Page.LBC_TRINKETS)
                                        require(currentGui(player).getGuiElement(0) != null,
                                                        "Second perk page contains its source cards: " + page);
                                inventoryClick(player, 25, 0, ContainerInput.PICKUP);
                                switch (page) {
                                        case LBC_KITS -> require(
                                                        profile.lbcKit == 0 && profile.lbcSkill == 4
                                                                        && profile.lbcTrinket == 5,
                                                        "Kit reset preserves other perk selections");
                                        case LBC_SKILLS -> require(
                                                        profile.lbcSkill == 0 && profile.lbcKit == 3
                                                                        && profile.lbcTrinket == 5,
                                                        "Skill reset preserves other perk selections");
                                        case LBC_TRINKETS -> require(
                                                        profile.lbcTrinket == 0 && profile.lbcKit == 3
                                                                        && profile.lbcSkill == 4,
                                                        "Trinket reset preserves other perk selections");
                                        case LBC_LEVELUPS -> require(
                                                        java.util.Arrays.stream(profile.levelups)
                                                                        .allMatch(value -> value == 0)
                                                                        && profile.lbcKit == 3 && profile.lbcSkill == 4,
                                                        "Levelup reset preserves other perk selections");
                                        default -> {
                                        }
                                }
                                var saved = PlayerStore.load().get(player.getUUID());
                                require(saved.lbcKit == profile.lbcKit && saved.lbcSkill == profile.lbcSkill
                                                && saved.lbcTrinket == profile.lbcTrinket
                                                && java.util.Arrays.equals(saved.levelups, profile.levelups),
                                                "Perk reset persists to disk: " + page);
                                inventoryClick(player, 18, 0, ContainerInput.PICKUP);
                                inventoryClick(player, 18, 0, ContainerInput.PICKUP);
                                requireLobbyInventory(player);
                        }
                } finally {
                        profile.lbcKit = kit;
                        profile.lbcSkill = skill;
                        profile.lbcTrinket = trinket;
                        System.arraycopy(levelups, 0, profile.levelups, 0, levelups.length);
                        game.config().ranked = ranked;
                        game.players().save();
                        game.menus().open(player);
                }
        }

        static void inventoryClick(ServerPlayer player, int slot, int button, ContainerInput input) {
                var menu = player.containerMenu;
                player.connection.handleContainerClick(
                                new net.minecraft.network.protocol.game.ServerboundContainerClickPacket(
                                                menu.containerId, menu.getStateId(), (short) slot, (byte) button, input,
                                                new it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap<>(),
                                                net.minecraft.network.HashedStack.EMPTY));
        }

        private static void checkLockedPerks(GameController game) {
                require(game.inLobby(), "Locked perk fixtures require a ready lobby");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var profile = game.players().get(player.getUUID());
                boolean ranked = game.config().ranked;
                int kit=profile.kit, skill=profile.skill, lbcKit=profile.lbcKit, lbcSkill=profile.lbcSkill;
                int trinket=profile.lbcTrinket, trinketSlot=profile.lbcTrinketSlot, levelupSlot=profile.lbcLevelupSlot;
                var levelups=profile.levelups.clone(); var trinkets=profile.trinkets.clone();
                var unlocks=new java.util.HashSet<>(profile.lbcUnlocks);
                var completedCriteria=new java.util.LinkedHashMap<net.minecraft.advancements.AdvancementHolder,java.util.List<String>>();
                boolean kitTag=player.entityTags().remove("swrg.kit1"), skillTag=player.entityTags().remove("swrg.skill1");
                try {
                        game.config().ranked=false; profile.lbcUnlocks.clear();
                        for (var page : new GameMenus.Page[]{GameMenus.Page.VANILLA_KITS,GameMenus.Page.VANILLA_SKILLS}) {
                                profile.kit=0; profile.skill=0;
                                game.menus().open(player,page);
                                var stack=currentGui(player).getGuiElement(0).getItemStack();
                                require(stack.is(Items.REPEATING_COMMAND_BLOCK)
                                                && net.minecraft.resources.Identifier.parse("lbc:locked_case").equals(stack.get(DataComponents.ITEM_MODEL)),
                                                "Vanilla closed perks show the exact source case lock");
                                translation(stack.get(DataComponents.CUSTOM_NAME),"gui.locked1");
                                require(stack.get(DataComponents.CUSTOM_NAME).getStyle().isBold()
                                                && java.util.Objects.equals(stack.get(DataComponents.CUSTOM_NAME).getStyle().getColor(),
                                                        net.minecraft.network.chat.TextColor.fromLegacyFormat(net.minecraft.ChatFormatting.RED)),
                                                "Locked case retains source bold red title");
                                click(currentGui(player),0);
                                require(profile.kit==0 && profile.skill==0,"Clicking a closed vanilla perk cannot select it");
                                game.config().ranked=true; game.menus().open(player,page); click(currentGui(player),0);
                                require((page==GameMenus.Page.VANILLA_KITS?profile.kit:profile.skill)==1,
                                                "Ranked permits a real GUI selection without an unlock tag");
                                game.config().ranked=false;
                        }
                        require(!player.entityTags().contains("swrg.kit1") && !player.entityTags().contains("swrg.skill1"),
                                        "Ranked never grants vanilla unlock tags");
                        try (var input=GameChecks.class.getResourceAsStream("/skywars2/lbc_loadouts.json")) {
                                var catalog=com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(input,
                                                java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();
                                for (var kind:LbcLoadouts.Kind.values()) {
                                        String name=kind.name().toLowerCase(java.util.Locale.ROOT);
                                        var entry=java.util.stream.StreamSupport.stream(catalog.getAsJsonArray(name).spliterator(),false)
                                                .map(com.google.gson.JsonElement::getAsJsonObject).filter(e->e.has("gate")).findFirst().orElseThrow();
                                        String gate=entry.get("gate").getAsString();
                                        var advancement=game.server().getAdvancements().get(net.minecraft.resources.Identifier.parse(gate));
                                        require(advancement!=null,"The original perk gate exists: "+gate);
                                        var criteria=new java.util.ArrayList<String>();
                                        player.getAdvancements().getOrStartProgress(advancement).getCompletedCriteria().forEach(criteria::add);
                                        completedCriteria.put(advancement,criteria);
                                        for(var criterion:criteria) player.getAdvancements().revoke(advancement,criterion);
                                        int page=entry.get("page").getAsInt(), slot=entry.get("slot").getAsInt();
                                        var lock=OriginalGuiDesign.button(player,"lbc",page,slot,profile,game.config());
                                        require(net.minecraft.resources.Identifier.parse("lbc:locked").equals(lock.get(DataComponents.ITEM_MODEL)),
                                                        "Closed LBC "+kind+" uses its original plain lock");
                                        translation(lock.get(DataComponents.CUSTOM_NAME),"gui.locked");
                                        require(lock.get(DataComponents.LORE)!=null && !lock.get(DataComponents.LORE).lines().isEmpty(),
                                                        "Locked LBC perk retains its original achievement description");
                                        require(!game.lbc().select(player,kind,page,slot),"Ordinary selection enforces "+gate);
                                        var inventoryBefore=java.util.stream.IntStream.range(0,player.getInventory().getContainerSize())
                                                .mapToObj(i->player.getInventory().getItem(i).copy()).toList();
                                        game.configureLobbySetting(player,"ranked","true");
                                        require(GameConfig.load().ranked,"Ranked persists through the real settings setter");
                                        require(game.items().mana().score(net.minecraft.world.scores.ScoreHolder.forNameOnly("ranked"),"lbc.event").get()==1,
                                                        "Ranked settings immediately update legacy loot conditions");
                                        var open=OriginalGuiDesign.button(player,"lbc",page,slot,profile,game.config());
                                        require(!net.minecraft.resources.Identifier.parse("lbc:locked").equals(open.get(DataComponents.ITEM_MODEL))
                                                        && game.lbc().select(player,kind,page,slot),"Ranked exposes and selects LBC "+kind);
                                        require(profile.lbcUnlocks.isEmpty() && !player.getAdvancements().getOrStartProgress(advancement).isDone(),
                                                        "Ranked does not grant native achievements or administrative unlocks");
                                        require(java.util.stream.IntStream.range(0,inventoryBefore.size()).allMatch(i->
                                                        ItemStack.matches(inventoryBefore.get(i),player.getInventory().getItem(i))),
                                                        "Enabling ranked and selecting a perk do not grant real inventory items");
                                        game.configureLobbySetting(player,"ranked","false");
                                        require(!game.lbc().select(player,kind,page,slot),"Disabling ranked restores the gate for "+kind);
                                        profile.lbcUnlocks.add(gate);
                                        require(OriginalGuiDesign.unlocked(player,"lbc",page,slot,profile,game.config())
                                                        && game.lbc().select(player,kind,page,slot),"Existing admin unlock remains valid without ranked");
                                        profile.lbcUnlocks.remove(gate);
                                }
                        } catch(java.io.IOException failure) {throw new IllegalStateException(failure);}
                        var ruby=OriginalGuiDesign.button(player,"lbc",9100,1,profile,game.config());
                        require(ruby.get(DataComponents.LORE)!=null && ruby.get(DataComponents.LORE).lines().size()==2,
                                        "Ruby lock retains both source lore rows");
                        translation(ruby.get(DataComponents.LORE).lines().get(1),"lbc.adv.upgraded_tuntija.ruby");
                        SkyWars2.LOGGER.info("[check] PASS locked-perks");
                } finally {
                        for(var entry:completedCriteria.entrySet()) for(var criterion:entry.getValue())
                                player.getAdvancements().award(entry.getKey(),criterion);
                        profile.kit=kit; profile.skill=skill; profile.lbcKit=lbcKit; profile.lbcSkill=lbcSkill;
                        profile.lbcTrinket=trinket; profile.lbcTrinketSlot=trinketSlot; profile.lbcLevelupSlot=levelupSlot;
                        System.arraycopy(levelups,0,profile.levelups,0,levelups.length);
                        System.arraycopy(trinkets,0,profile.trinkets,0,trinkets.length);
                        profile.lbcUnlocks.clear(); profile.lbcUnlocks.addAll(unlocks);
                        if(kitTag) player.entityTags().add("swrg.kit1"); if(skillTag) player.entityTags().add("swrg.skill1");
                        game.config().ranked=ranked; game.config().save(); game.lbc().syncRanked(); game.players().save(); game.menus().open(player);
                }
        }

        private static void checkDynamicDesign(GameController game, ServerPlayer player, PlayerStore.Profile profile) {
                int kit = profile.kit, skill = profile.skill;
                int games = profile.games, wins = profile.wins, kills = profile.kills, deaths = profile.deaths;
                boolean ranked = game.config().ranked;
                try {
                        game.config().ranked = true;
                        profile.kit = 0;
                        profile.skill = 0;
                        for (var page : new GameMenus.Page[] { GameMenus.Page.VANILLA_KITS,
                                        GameMenus.Page.VANILLA_SKILLS }) {
                                game.menus().open(player, page);
                                var before = currentGui(player).getGuiElement(0).getItemStack()
                                                .get(DataComponents.LORE);
                                click(currentGui(player), 0);
                                var selected = currentGui(player).getGuiElement(0).getItemStack();
                                var after = selected.get(DataComponents.LORE);
                                require(Boolean.TRUE.equals(selected.get(DataComponents.ENCHANTMENT_GLINT_OVERRIDE)),
                                                "Selected source item glints: " + page);
                                require(after != null && before != null
                                                && after.lines().size() == before.lines().size() + 1,
                                                "Selection prepends one row without removing source lore: " + page);
                                translation(after.lines().getFirst(), "swrg.gui.select");
                                for (int index = 0; index < before.lines().size(); index++) {
                                        require(after.lines().get(index + 1).equals(before.lines().get(index)),
                                                        "Selection retains exact source lore row " + index);
                                }
                        }
                        profile.games = 3;
                        profile.wins = 1;
                        profile.kills = 1;
                        for (int divisor : new int[] { 20, 8 }) {
                                profile.deaths = divisor;
                                game.menus().open(player);
                                var lore = currentGui(player).getGuiElement(8).getItemStack().get(DataComponents.LORE);
                                require(lore != null && lore.lines().size() == 3,
                                                "Profile chooses exactly one conditional KD row");
                                require(lore.lines().get(1).getString().endsWith("33"),
                                                "Source winrate retains integer precision");
                                require(lore.lines().get(2).getString().endsWith(divisor == 20 ? "0.05" : "0.12"),
                                                "Source KD retains two decimals");
                                click(currentGui(player), 8);
                                var stats = currentGui(player);
                                requireItem(stats, 8, Items.PLAYER_HEAD, "Statistics retains original profile head");
                                requireItem(stats, 18, Items.SPECTRAL_ARROW, "Statistics retains back navigation");
                                Component deathsName = stats.getGuiElement(11).getItemStack().getHoverName();
                                require(deathsName.equals(Component.translatable("skywars2.gui.stats.deaths", divisor)
                                                .withStyle(style -> style.withColor(net.minecraft.ChatFormatting.GREEN)
                                                                .withItalic(false))),
                                                "Statistics refreshes actual deaths on every opening");
                                require(stats.getGuiElement(10).getItemStack().getHoverName().equals(
                                                Component.translatable("skywars2.gui.stats.wins_kills", profile.wins,
                                                                profile.kills)
                                                                .withStyle(style -> style.withColor(
                                                                                net.minecraft.ChatFormatting.GREEN)
                                                                                .withItalic(false))),
                                                "Statistics includes actual wins and kills");
                                int[] walletSlots = { 13, 14 };
                                int[] balances = { profile.coins, profile.memcoins };
                                for (int index = 0; index < walletSlots.length; index++) {
                                        var balance = stats.getGuiElement(walletSlots[index]).getItemStack()
                                                        .get(DataComponents.LORE);
                                        require(balance != null && balance.lines().getFirst().getString()
                                                        .equals(Integer.toString(balances[index])),
                                                        "Statistics reads current wallet balance "
                                                                        + walletSlots[index]);
                                }
                                var keys = stats.getGuiElement(16).getItemStack().get(DataComponents.LORE);
                                require(keys != null && keys.lines().getFirst().equals(Component
                                                .translatable("skywars2.gui.stats.keys.list",
                                                                profile.keys[0], profile.keys[1], profile.keys[2],
                                                                profile.keys[3], profile.keys[4])
                                                .withStyle(style -> style.withColor(net.minecraft.ChatFormatting.AQUA)
                                                                .withItalic(false))),
                                                "Statistics includes all five key balances");
                        }
                } finally {
                        profile.kit = kit;
                        profile.skill = skill;
                        profile.games = games;
                        profile.wins = wins;
                        profile.kills = kills;
                        profile.deaths = deaths;
                        game.config().ranked = ranked;
                        game.players().save();
                }
        }

        private static void exportMenuDesign(GameController game) {
                require(game.canUseMenus(), "Menu design export requires lobby/loading");
                var player = game.server().getPlayerList().getPlayers().getFirst();
                var output = new com.google.gson.JsonObject();
                var pages = new com.google.gson.JsonArray();
                var ops = player.registryAccess().createSerializationContext(JsonOps.INSTANCE);
                for (var page : GameMenus.Page.values()) {
                        game.menus().open(player, page);
                        var gui = (SimpleGui) currentGui(player);
                        var entry = new com.google.gson.JsonObject();
                        entry.addProperty("page", page.name());
                        entry.addProperty("size", gui.getVirtualSize());
                        entry.add("title", ComponentSerialization.CODEC.encodeStart(JsonOps.INSTANCE, gui.getTitle())
                                        .getOrThrow());
                        var slots = new com.google.gson.JsonArray();
                        for (int slot = 0; slot < gui.getVirtualSize(); slot++) {
                                var element = gui.getGuiElement(slot);
                                if (element == null || element.getItemStack().isEmpty())
                                        continue;
                                var button = new com.google.gson.JsonObject();
                                button.addProperty("slot", slot);
                                button.add("item", net.minecraft.world.item.ItemStack.CODEC
                                                .encodeStart(ops, element.getItemStack()).getOrThrow());
                                slots.add(button);
                        }
                        entry.add("slots", slots);
                        pages.add(entry);
                }
                output.add("pages", pages);
                try {
                        java.nio.file.Files.writeString(java.nio.file.Path.of("menu-design-snapshot.json"),
                                        new com.google.gson.GsonBuilder().setPrettyPrinting().disableHtmlEscaping()
                                                        .create().toJson(output),
                                        StandardCharsets.UTF_8);
                } catch (java.io.IOException error) {
                        throw new IllegalStateException("Cannot export menu design", error);
                }
                game.menus().open(player);
        }

        private static void requireLobbyInventory(ServerPlayer player) {
                for (int slot = 0; slot < player.getInventory().getContainerSize(); slot++) {
                        var stack = player.getInventory().getItem(slot);
                        require(slot == GameController.MENU_COMPASS_SLOT
                                        ? stack.is(Items.COMPASS) && stack.getCount() == 1
                                        : stack.isEmpty(),
                                        "Fixed lobby inventory slot " + slot);
                }
                require(player.containerMenu.getCarried().isEmpty(), "Lobby cursor remains empty");
        }

        private static void checkLobbyInventory(GameController game) {
                require(game.inventoryLocked(), "Lobby/loading inventory lock is active");
                ServerPlayer player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player != null, "Create bots first");
                player.closeContainer();
                player.getInventory().setSelectedSlot(GameController.MENU_COMPASS_SLOT);
                requireLobbyInventory(player);
                int compassSlot = 36 + GameController.MENU_COMPASS_SLOT;
                for (ContainerInput input : ContainerInput.values()) {
                        inventoryClick(player, compassSlot, 0, input);
                        requireLobbyInventory(player);
                }
                for (var action : new net.minecraft.network.protocol.game.ServerboundPlayerActionPacket.Action[] {
                                net.minecraft.network.protocol.game.ServerboundPlayerActionPacket.Action.DROP_ITEM,
                                net.minecraft.network.protocol.game.ServerboundPlayerActionPacket.Action.DROP_ALL_ITEMS,
                                net.minecraft.network.protocol.game.ServerboundPlayerActionPacket.Action.SWAP_ITEM_WITH_OFFHAND }) {
                        player.connection.handlePlayerAction(
                                        new net.minecraft.network.protocol.game.ServerboundPlayerActionPacket(
                                                        action, net.minecraft.core.BlockPos.ZERO,
                                                        net.minecraft.core.Direction.DOWN));
                        requireLobbyInventory(player);
                }
                var item = new net.minecraft.world.entity.item.ItemEntity(player.level(), player.getX(), player.getY(),
                                player.getZ(),
                                new net.minecraft.world.item.ItemStack(Items.DIAMOND));
                item.setNoPickUpDelay();
                item.playerTouch(player);
                require(item.getItem().getCount() == 1 && !item.isRemoved(),
                                "Dropped item is not picked up in lobby/loading");
                requireLobbyInventory(player);
                item.discard();

                GameType mode = player.gameMode.getGameModeForPlayer();
                try {
                        player.setGameMode(GameType.CREATIVE);
                        player.connection.handleSetCreativeModeSlot(
                                        new net.minecraft.network.protocol.game.ServerboundSetCreativeModeSlotPacket(
                                                        compassSlot,
                                                        new net.minecraft.world.item.ItemStack(Items.DIAMOND)));
                        requireLobbyInventory(player);
                } finally {
                        player.setGameMode(mode);
                }

                // A real vanilla container must not become a loophole for moving items.
                var storage = new net.minecraft.world.SimpleContainer(27);
                storage.setItem(0, new net.minecraft.world.item.ItemStack(Items.DIAMOND));
                player.containerMenu = net.minecraft.world.inventory.ChestMenu.threeRows(99, player.getInventory(),
                                storage);
                try {
                        inventoryClick(player, 0, 0, ContainerInput.QUICK_MOVE);
                        require(storage.getItem(0).is(Items.DIAMOND), "Vanilla chest transfer is blocked");
                        requireLobbyInventory(player);
                } finally {
                        player.containerMenu = player.inventoryMenu;
                }

                var profile = game.players().get(player.getUUID());
                int coins = profile.coins;
                int[] keys = profile.keys.clone();
                try {
                        profile.coins = 1000;
                        game.menus().open(player, GameMenus.Page.KEY_SHOP);
                        inventoryClick(player, currentGui(player).getSize() + 27 + GameController.MENU_COMPASS_SLOT, 0,
                                        ContainerInput.QUICK_MOVE);
                        requireLobbyInventory(player);
                        inventoryClick(player, 0, 0, ContainerInput.PICKUP);
                        require(profile.coins == 900 && profile.keys[0] == keys[0] + 1,
                                        "Native SGui purchase packet still works");
                        requireLobbyInventory(player);
                } finally {
                        profile.coins = coins;
                        System.arraycopy(keys, 0, profile.keys, 0, keys.length);
                        game.players().save();
                        player.closeContainer();
                }
        }

        private static void checkUnlockedInventory(GameController game) {
                require(game.playing() && !game.inventoryLocked(), "Inventory lock released for the match");
                ServerPlayer player = game.alivePlayers().getFirst();
                player.closeContainer();
                var saved = player.getInventory().getItem(0).copy();
                try {
                        player.getInventory().setItem(0, new net.minecraft.world.item.ItemStack(Items.DIAMOND));
                        inventoryClick(player, 36, 0, ContainerInput.PICKUP);
                        require(player.getInventory().getItem(0).isEmpty()
                                        && player.containerMenu.getCarried().is(Items.DIAMOND),
                                        "Native inventory move works during a match");
                        player.containerMenu.setCarried(net.minecraft.world.item.ItemStack.EMPTY);
                        var item = new net.minecraft.world.entity.item.ItemEntity(player.level(), player.getX(),
                                        player.getY(), player.getZ(),
                                        new net.minecraft.world.item.ItemStack(Items.DIAMOND));
                        item.setNoPickUpDelay();
                        item.playerTouch(player);
                        require(item.isRemoved() && player.getInventory().getItem(0).is(Items.DIAMOND),
                                        "Item pickup works during a match");
                } finally {
                        player.containerMenu.setCarried(net.minecraft.world.item.ItemStack.EMPTY);
                        player.getInventory().setItem(0, saved);
                        player.inventoryMenu.sendAllDataToRemote();
                }
        }

        private static SlotBasedGui currentGui(ServerPlayer player) {
                var gui = SguiUtils.getCurrentGui(player);
                require(gui instanceof SlotBasedGui, "Current container is a real SGui slot wrapper");
                return (SlotBasedGui) gui;
        }

        private static TranslatableContents translation(Component component, String key) {
                require(component.getContents() instanceof TranslatableContents,
                                "Client receives a translation component: " + key);
                var contents = (TranslatableContents) component.getContents();
                require(contents.getKey().equals(key),
                                "Translation key preserved: " + key + "; got " + contents.getKey());
                return contents;
        }

        private static void requireLegacyStyle(
                        Component component, net.minecraft.ChatFormatting color, String message) {
                var style = component.getStyle();
                require(
                                java.util.Objects.equals(
                                                style.getColor(),
                                                net.minecraft.network.chat.TextColor.fromLegacyFormat(color)),
                                message + " color");
                require(Boolean.FALSE.equals(style.isItalic()), message + " italic=false");
        }

        private static void checkClientTranslation(Component component) {
                require(containsTranslation(component) || component.getString().matches("[\\s\\d\\p{Punct}]*"),
                                "Custom text retains client translations: " + component);
                var encoded = ComponentSerialization.CODEC.encodeStart(JsonOps.INSTANCE, component).getOrThrow();
                Component decoded = ComponentSerialization.CODEC.parse(JsonOps.INSTANCE, encoded).getOrThrow();
                var encodedAgain = ComponentSerialization.CODEC.encodeStart(JsonOps.INSTANCE, decoded).getOrThrow();
                // The decoder normalizes Java numeric argument types; compare their wire
                // representation.
                require(encodedAgain.equals(encoded),
                                "Component codec preserves translation keys, arguments and styles: " + encoded);
        }

        private static boolean containsTranslation(Component component) {
                if (component.getContents() instanceof TranslatableContents)
                        return true;
                return component.getSiblings().stream().anyMatch(GameChecks::containsTranslation);
        }

        private static void requireItem(SlotBasedGui gui, int slot, net.minecraft.world.item.Item item,
                        String message) {
                var element = gui.getGuiElement(slot);
                require(element != null && element.getItemStack().is(item), message);
        }

        private static void click(SlotBasedGui gui, int slot) {
                gui.click(slot, ClickType.MOUSE_LEFT, ContainerInput.PICKUP);
        }

        /**
         * Recipient-specific client projection checks; the authoritative artifact is
         * never rewritten.
         */
        public static void checkLooper(GameController game) {
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var observer = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                require(player != null && observer != null, "Looper checks require both reusable test bots online");

                var profile = game.players().get(player.getUUID());
                var observerProfile = game.players().get(observer.getUUID());
                int priorSkill = profile.lbcSkill;
                int priorObserverSkill = observerProfile.lbcSkill;
                boolean priorEnabled = game.config().lbcSkills;
                boolean observerWasObserver = game.isObserver(observer);
                ItemStack[] priorInventory = new ItemStack[player.getInventory().getContainerSize()];
                for (int slot = 0; slot < priorInventory.length; slot++)
                        priorInventory[slot] = player.getInventory().getItem(slot).copy();
                ItemStack priorObserverMain = observer.getMainHandItem().copy();
                game.lbc().grantTable(player, "lbc:ported/mystical_artifact");
                var generated = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                player.getInventory().clearContent();
                try {
                        if (!observerWasObserver)
                                game.spectators().enter(observer);
                        String[] expected = {
                                        "artifact_1", "artifact_2", "artifact_3", "artifact_4", "artifact_5",
                                        "artifact_6", "artifact_7", "artifact_8",
                                        "artifact_9", "artifact_10", "artifact_11", "artifact_12", "artifact_13",
                                        "artifact_14", "artifact_15", "artifact_16",
                                        "artifact_17", "artifact_18", "artifact_19", "artifact_20", "artifact_21",
                                        "artifact_22", "artifact_23" };
                        int[][] states = {
                                        { 1, 1 }, { 1, 2 }, { 1, 3 }, { 1, 4 }, { 1, 5 }, { 1, 6 }, { 1, 7 }, { 1, 8 },
                                        { 2, 1 }, { 2, 2 }, { 2, 3 }, { 2, 4 }, { 2, 5 }, { 2, 6 },
                                        { 3, 1 }, { 3, 2 }, { 3, 3 },
                                        { 4, 1 }, { 4, 2 }, { 4, 3 }, { 4, 4 }, { 4, 5 }, { 4, 6 } };
                        var sourceLore = generated.get(DataComponents.LORE);
                        require(sourceLore != null && sourceLore.lines().size() == 2
                                        && translation(sourceLore.lines().get(1), "mystical_artifact.lore") != null,
                                        "Authoritative artifact keeps its unknown-description lore");
                        profile.lbcSkill = 3;
                        observerProfile.lbcSkill = 2;
                        game.config().lbcSkills = true;
                        game.lbc().tickSecond(); // Refresh the viewer-capability snapshot used by packet conversion.

                        for (int index = 0; index < states.length; index++) {
                                var source = generated.copy();
                                var data = source.get(DataComponents.CUSTOM_DATA).copyTag();
                                data.putInt("unresolved_artifact", 1);
                                data.putInt("mystical", states[index][0]);
                                data.putInt("type", states[index][1]);
                                data.putInt("looper_check_sentinel", 73);
                                source.set(DataComponents.CUSTOM_DATA,
                                                net.minecraft.world.item.component.CustomData.of(data));
                                var before = source.copy();
                                var originalLore = source.get(DataComponents.LORE).lines();

                                var privileged = polymerArtifactView(player, source);
                                var unknown = polymerArtifactView(observer, source);
                                require(privileged.is(Items.REPEATING_COMMAND_BLOCK)
                                                && unknown.is(Items.REPEATING_COMMAND_BLOCK),
                                                "Both recipients receive the native Polymer proxy for state "
                                                                + (index + 1));
                                require(ItemStack.matches(before, source),
                                                "Per-viewer conversion leaves authoritative artifact components unchanged for state "
                                                                + (index + 1));
                                require(privileged.get(DataComponents.LORE) != null
                                                && unknown.get(DataComponents.LORE) != null
                                                && privileged.get(DataComponents.LORE).lines().size() == 2
                                                && unknown.get(DataComponents.LORE).lines().size() == 2,
                                                "Both Polymer projections retain the two source lore rows for state "
                                                                + (index + 1));
                                var privilegedLore = privileged.get(DataComponents.LORE).lines();
                                var unknownLore = unknown.get(DataComponents.LORE).lines();
                                var expectedFirst = Component.empty()
                                                .append(source.get(DataComponents.LORE).styledLines().get(0))
                                                .setStyle(eu.pb4.polymer.core.api.item.PolymerItemUtils.CLEAN_STYLE);
                                require(privilegedLore.get(0).equals(expectedFirst)
                                                && unknownLore.get(0).equals(expectedFirst),
                                                "Both projections preserve the first source lore row for state "
                                                                + (index + 1));
                                var privilegedDescription = unwrapPolymerArtifactLore(privilegedLore.get(1));
                                var unknownDescription = unwrapPolymerArtifactLore(unknownLore.get(1));
                                require(translation(privilegedDescription, expected[index]) != null,
                                                "Looper viewer sees exact source description " + expected[index]);
                                requireLegacyStyle(privilegedDescription, ChatFormatting.YELLOW,
                                                "Looper viewer lore " + expected[index]);
                                require(translation(unknownDescription, "mystical_artifact.lore") != null,
                                                "Non-Looper viewer sees unknown lore for state " + (index + 1));
                                requireLegacyStyle(unknownDescription, ChatFormatting.RED,
                                                "Unknown artifact lore " + (index + 1));
                                require(ItemStack.matches(before, polymerArtifactRealStack(privileged, player))
                                                && ItemStack.matches(before,
                                                                polymerArtifactRealStack(unknown, observer)),
                                                "Both client projections restore the exact server artifact for state "
                                                                + (index + 1));
                        }

                        // Ground drops use the same native item conversion, with independent recipient
                        // contexts.
                        var groundSource = generated.copy();
                        var level = player.level();
                        var groundEntity = new net.minecraft.world.entity.item.ItemEntity(level, player.getX(),
                                        player.getY(), player.getZ(), groundSource);
                        groundEntity.setDeltaMovement(Vec3.ZERO);
                        var observerGroundEntity = new net.minecraft.world.entity.item.ItemEntity(observer.level(),
                                        observer.getX(), observer.getY(), observer.getZ(), groundSource.copy());
                        observerGroundEntity.setDeltaMovement(Vec3.ZERO);
                        try {
                                require(level.addFreshEntity(groundEntity)
                                                && observer.level().addFreshEntity(observerGroundEntity),
                                                "Native artifact ItemEntity ground probes are spawned for packet refresh checks");
                                // Р¤РёРєС‚РёРІРЅС‹Рµ РїРѕРґРєР»СЋС‡РµРЅРёСЏ РЅРµ РїРѕРґС‚РІРµСЂР¶РґР°СЋС‚ С‡Р°РЅРєРё; Р·РґРµСЃСЊ РїСЂРѕРІРµСЂСЏРµРј РїСЂРµРґСЃС‚Р°РІР»РµРЅРёСЏ,
                                // РЅРµ РІС‹РґР°РІР°СЏ РѕС‚СЃСѓС‚СЃС‚РІРёРµ РЅР°СЃС‚РѕСЏС‰РµРіРѕ РєР»РёРµРЅС‚СЃРєРѕРіРѕ tracking Р·Р° РїСЂРѕРІРµСЂРµРЅРЅСѓСЋ РґРѕСЃС‚Р°РІРєСѓ
                                // РїР°РєРµС‚РѕРІ.
                                var groundBefore = groundEntity.getItem().copy();
                                var groundPrivileged = polymerArtifactView(player, groundEntity.getItem());
                                var groundUnknown = polymerArtifactView(observer, groundEntity.getItem());
                                require(translation(unwrapPolymerArtifactLore(
                                                groundPrivileged.get(DataComponents.LORE).lines().get(1)),
                                                "artifact_1") != null
                                                && translation(unwrapPolymerArtifactLore(
                                                                groundUnknown.get(DataComponents.LORE).lines().get(1)),
                                                                "mystical_artifact.lore") != null,
                                                "Native ground ItemEntity stack projects independently for both recipients");
                                require(ItemStack.matches(groundBefore, groundEntity.getItem())
                                                && ItemStack.matches(groundBefore, observerGroundEntity.getItem()),
                                                "Ground ItemEntities keep their authoritative stacks");
                                LbcSkills.refreshViewer(player);
                                LbcSkills.refreshViewer(observer);
                                require(ItemStack.matches(groundBefore, groundEntity.getItem())
                                                && ItemStack.matches(groundBefore, observerGroundEntity.getItem()),
                                                "Viewer refresh leaves native ground stacks unchanged");
                        } finally {
                                groundEntity.discard();
                                observerGroundEntity.discard();
                        }

                        // A perk/config change affects the next projection of the same source stack in
                        // both directions.
                        var refreshSource = generated.copy();
                        var refreshBefore = refreshSource.copy();
                        require(translation(
                                        unwrapPolymerArtifactLore(polymerArtifactView(observer, refreshSource)
                                                        .get(DataComponents.LORE).lines().get(1)),
                                        "mystical_artifact.lore") != null,
                                        "Observer without Looper initially gets unknown lore");
                        observerProfile.lbcSkill = 3;
                        game.lbc().tickSecond();
                        require(translation(
                                        unwrapPolymerArtifactLore(polymerArtifactView(observer, refreshSource)
                                                        .get(DataComponents.LORE).lines().get(1)),
                                        "artifact_1") != null,
                                        "Updated observer perk is used by the next client-stack projection");
                        game.config().lbcSkills = false;
                        game.lbc().tickSecond();
                        require(translation(
                                        unwrapPolymerArtifactLore(polymerArtifactView(observer, refreshSource)
                                                        .get(DataComponents.LORE).lines().get(1)),
                                        "mystical_artifact.lore") != null,
                                        "Disabling LBC skills removes the description on the next projection");
                        game.config().lbcSkills = true;
                        game.lbc().tickSecond();
                        require(translation(
                                        unwrapPolymerArtifactLore(polymerArtifactView(observer, refreshSource)
                                                        .get(DataComponents.LORE).lines().get(1)),
                                        "artifact_1") != null && ItemStack.matches(refreshBefore, refreshSource),
                                        "Re-enabling Looper restores the viewer description without changing the source stack");

                        // Stacks resolved by the former mutating hook must also be hidden from viewers
                        // without Looper.
                        var legacyResolved = generated.copy();
                        var legacyLore = new java.util.ArrayList<>(legacyResolved.get(DataComponents.LORE).lines());
                        legacyLore.set(1, Component.translatable("artifact_1")
                                        .withStyle(style -> style.withColor(ChatFormatting.YELLOW).withItalic(false)));
                        legacyResolved.set(DataComponents.LORE,
                                        new net.minecraft.world.item.component.ItemLore(legacyLore));
                        var legacyData = legacyResolved.get(DataComponents.CUSTOM_DATA).copyTag();
                        legacyData.remove("unresolved_artifact");
                        legacyResolved.set(DataComponents.CUSTOM_DATA,
                                        net.minecraft.world.item.component.CustomData.of(legacyData));
                        var legacyBefore = legacyResolved.copy();
                        observerProfile.lbcSkill = 2;
                        game.lbc().tickSecond();
                        var legacyUnknown = polymerArtifactView(observer, legacyResolved);
                        require(translation(
                                        unwrapPolymerArtifactLore(
                                                        legacyUnknown.get(DataComponents.LORE).lines().get(1)),
                                        "mystical_artifact.lore") != null,
                                        "Viewer without Looper sees unknown lore even on a legacy-resolved artifact");
                        require(ItemStack.matches(legacyBefore, legacyResolved),
                                        "Legacy resolved artifact remains unchanged on the server");

                        var invalid = generated.copy();
                        var invalidData = invalid.get(DataComponents.CUSTOM_DATA).copyTag();
                        invalidData.putInt("mystical", 9);
                        invalidData.putInt("type", 1);
                        invalid.set(DataComponents.CUSTOM_DATA,
                                        net.minecraft.world.item.component.CustomData.of(invalidData));
                        var invalidBefore = invalid.copy();
                        profile.lbcSkill = 3;
                        game.lbc().tickSecond();
                        var invalidView = polymerArtifactView(player, invalid);
                        require(translation(
                                        unwrapPolymerArtifactLore(invalidView.get(DataComponents.LORE).lines().get(1)),
                                        "mystical_artifact.lore") != null
                                        && ItemStack.matches(invalidBefore, invalid),
                                        "Invalid mystical state keeps its source lore and is never mutated");

                        var unmarked = generated.copy();
                        var unmarkedData = unmarked.get(DataComponents.CUSTOM_DATA).copyTag();
                        unmarkedData.remove("unresolved_artifact");
                        unmarkedData.remove("mystical");
                        unmarkedData.remove("type");
                        unmarked.set(DataComponents.CUSTOM_DATA,
                                        net.minecraft.world.item.component.CustomData.of(unmarkedData));
                        var unmarkedBefore = unmarked.copy();
                        var unmarkedView = polymerArtifactView(player, unmarked);
                        require(translation(
                                        unwrapPolymerArtifactLore(unmarkedView.get(DataComponents.LORE).lines().get(1)),
                                        "mystical_artifact.lore") != null
                                        && ItemStack.matches(unmarkedBefore, unmarked),
                                        "Unmarked artifact without source state remains unchanged and displays unknown lore");

                        var unrelated = new ItemStack(Items.DIAMOND);
                        var unrelatedData = new net.minecraft.nbt.CompoundTag();
                        unrelatedData.putInt("unresolved_artifact", 1);
                        unrelatedData.putInt("mystical", 1);
                        unrelatedData.putInt("type", 1);
                        unrelated.set(DataComponents.CUSTOM_DATA,
                                        net.minecraft.world.item.component.CustomData.of(unrelatedData));
                        var unrelatedBefore = unrelated.copy();
                        require(polymerArtifactView(player, unrelated).is(Items.DIAMOND)
                                        && ItemStack.matches(unrelatedBefore, unrelated),
                                        "Artifact-like custom data on an ordinary item does not trigger the projection");
                } finally {
                        game.config().lbcSkills = priorEnabled;
                        profile.lbcSkill = priorSkill;
                        observerProfile.lbcSkill = priorObserverSkill;
                        game.lbc().tickSecond();
                        if (!observerWasObserver && game.isObserver(observer))
                                game.spectators().remove(observer);
                        observer.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND, priorObserverMain);
                        player.getInventory().clearContent();
                        for (int slot = 0; slot < priorInventory.length; slot++)
                                player.getInventory().setItem(slot, priorInventory[slot]);
                        game.players().save();
                }
        }

        private static ItemStack polymerArtifactView(ServerPlayer viewer, ItemStack source) {
                var connection = new Connection(PacketFlow.SERVERBOUND) {
                        @Override
                        public net.minecraft.network.PacketListener getPacketListener() {
                                return viewer.connection;
                        }
                };
                var provider = (net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider) connection;
                require(eu.pb4.polymer.common.api.PolymerCommonUtils.getPlayer(provider.getPacketContext()) == viewer,
                                "Artifact Polymer conversion resolves its actual recipient");
                ItemStack[] result = { ItemStack.EMPTY };
                net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider,
                                () -> result[0] = eu.pb4.polymer.core.api.item.PolymerItemUtils.getPolymerItemStack(
                                                source,
                                                net.minecraft.world.item.TooltipFlag.NORMAL,
                                                provider.getPacketContext(), viewer.registryAccess()));
                return result[0];
        }

        private static ItemStack polymerArtifactRealStack(ItemStack clientStack, ServerPlayer viewer) {
                var connection = new Connection(PacketFlow.SERVERBOUND) {
                        @Override
                        public net.minecraft.network.PacketListener getPacketListener() {
                                return viewer.connection;
                        }
                };
                var provider = (net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider) connection;
                ItemStack[] result = { ItemStack.EMPTY };
                net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider,
                                () -> result[0] = eu.pb4.polymer.core.api.item.PolymerItemUtils.getRealItemStack(
                                                clientStack,
                                                provider.getPacketContext(), viewer.registryAccess()));
                return result[0];
        }

        private static Component unwrapPolymerArtifactLore(Component wrappedLore) {
                require(wrappedLore.getSiblings().size() == 1,
                                "Polymer client lore has one CLEAN_STYLE wrapper around the source component");
                return wrappedLore.getSiblings().getFirst();
        }

        public static void checkArtifactPassivesMenu(GameController game) {
                require(game.inLobby(), "Artifact passive loot checks require lobby");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player != null, "Create reusable test bots before passive item setup");
                for (var online : game.server().getPlayerList().getPlayers()) {
                        var profile = game.players().get(online.getUUID());
                        profile.lbcKit = 0;
                        profile.lbcSkill = 0;
                        profile.lbcTrinket = 0;
                        profile.lbcTrinketSlot = 0;
                        java.util.Arrays.fill(profile.levelups, 0);
                        java.util.Arrays.fill(profile.trinkets, 0);
                }
                game.players().save();
                for (var fixture : java.util.List.of(
                                new Object[] { "lbc:ported/mystical_artifact_clear", 6 },
                                new Object[] { "lbc:ported/mystical_artifact_metabolism", 8 })) {
                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, (String) fixture[0]);
                        var stack = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                        var data = stack.get(DataComponents.CUSTOM_DATA).copyTag();
                        require(stack.getCount() == 1 && data.getInt("mystical").orElse(0) == 1
                                        && data.getInt("type").orElse(0) == (int) fixture[1],
                                        "Source loot grants exact mystical artifact type " + fixture[1]);
                        require(stack.has(DataComponents.LORE) && stack.has(DataComponents.TOOLTIP_STYLE),
                                        "Mystical artifact type " + fixture[1] + " retains source tooltip components");
                        requirePolymerStack(player, stack, Items.REPEATING_COMMAND_BLOCK,
                                        "Mystical artifact type " + fixture[1]);
                }
                player.getInventory().clearContent();
                game.menus().open(player);
                SkyWars2.LOGGER.info("[check] PASS artifact-passives-menu");
        }

        public static void checkArtifactPassives(GameController game) {
                require(game.playing(), "Artifact passives require an active match");
                var magic = game.items().magic();
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var observer = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                var level = game.maps().level();
                var priorMode = player.gameMode.getGameModeForPlayer();
                var priorLevel = player.level();
                var priorPosition = player.position();
                var priorNoGravity = player.isNoGravity();
                var observerPriorMode = observer.gameMode.getGameModeForPlayer();
                float observerPriorHealth = observer.getHealth();
                double priorMaxHealthBase = player
                                .getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH)
                                .getBaseValue();
                boolean observerWasObserver = game.isObserver(observer);
                net.minecraft.core.BlockPos passiveBeacon = null;
                try {
                        player.closeContainer();
                        player.getInventory().clearContent();
                        player.setGameMode(GameType.SURVIVAL);
                        player.removeAllEffects();
                        player.setAbsorptionAmount(0);
                        player.setHealth(player.getMaxHealth());

                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_clear");
                        var clear = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                        player.getInventory().setItem(0, clear.copy());
                        triggerNativeInventoryChange(player, clear);
                        magic.tick();
                        require(magic.artifactTypes(player) == (1 << 6), "Typed artifact index recognizes type 6");
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.SPEED, 400, 2));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 400, 0,
                                        true, false, false));
                        magic.tickPassives();
                        require(player.getActiveEffects().isEmpty(),
                                        "Type 6 clears every active effect on its five-tick phase");

                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_metabolism");
                        var metabolism = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                        for (int slot = 0; slot < 36; slot++) {
                                player.getInventory().clearContent();
                                player.getInventory().setItem(slot, metabolism.copy());
                                triggerNativeInventoryChange(player, metabolism);
                                magic.tick();
                                require(magic.artifactTypes(player) == (1 << 8),
                                                "Type 8 refresh sees inventory slot " + slot);
                                player.getInventory().setItem(slot, ItemStack.EMPTY);
                                triggerNativeInventoryChange(player, ItemStack.EMPTY);
                                magic.tick();
                                require(magic.artifactTypes(player) == 0, "Removing type 8 clears slot " + slot);
                        }
                        player.getInventory().setItem(40, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        require(magic.artifactTypes(player) == (1 << 8), "Type 8 refresh sees offhand");
                        player.getInventory().setItem(40, ItemStack.EMPTY);
                        player.getInventory().setItem(36, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        require(magic.artifactTypes(player) == 0,
                                        "Armor slots do not activate typed artifact passives");
                        player.getInventory().setItem(36, ItemStack.EMPTY);

                        player.closeContainer();
                        player.getInventory().setItem(0, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        nativeMagicClick(player, 36);
                        magic.tick();
                        require(magic.artifactTypes(player) == (1 << 8), "Type 8 on the native cursor remains active");
                        nativeMagicClick(player, 1);
                        magic.tick();
                        require(magic.artifactTypes(player) == (1 << 8),
                                        "Type 8 in native 2x2 crafting input remains active");
                        nativeMagicClick(player, 1);
                        nativeMagicClick(player, -999);
                        magic.tick();
                        require(magic.artifactTypes(player) == 0, "Native cursor drop removes typed passive state");
                        for (var drop : level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,
                                        player.getBoundingBox().inflate(5),
                                        item -> item.getItem().is(LbcMagic.MYSTICAL_ARTIFACT)))
                                drop.discard();

                        player.setNoGravity(true);
                        player.teleportTo(level, 0, 200, 0, java.util.Set.of(), 0, 0, true);
                        var tablePos = new net.minecraft.core.BlockPos(1, 199, 0);
                        level.setBlock(tablePos,
                                        net.minecraft.world.level.block.Blocks.CRAFTING_TABLE.defaultBlockState(), 3);
                        player.openMenu(new net.minecraft.world.SimpleMenuProvider(
                                        (id, inventory, owner) -> new net.minecraft.world.inventory.CraftingMenu(id,
                                                        inventory,
                                                        net.minecraft.world.inventory.ContainerLevelAccess.create(level,
                                                                        tablePos)),
                                        Component.literal("passive test")));
                        for (int slot = 1; slot <= 9; slot++) {
                                player.getInventory().setItem(0, metabolism.copy());
                                nativeMagicClick(player, 37);
                                nativeMagicClick(player, slot);
                                magic.tick();
                                require(magic.artifactTypes(player) == (1 << 8),
                                                "Type 8 in native 3x3 crafting input " + slot + " remains active");
                                nativeMagicClick(player, slot);
                                nativeMagicClick(player, -999);
                                magic.tick();
                                require(magic.artifactTypes(player) == 0,
                                                "Dropping from native 3x3 input " + slot + " clears type 8");
                        }
                        player.closeContainer();
                        level.setBlock(tablePos, net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(), 3);
                        for (var drop : level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,
                                        player.getBoundingBox().inflate(5),
                                        item -> item.getItem().is(LbcMagic.MYSTICAL_ARTIFACT)))
                                drop.discard();

                        passiveBeacon = new net.minecraft.core.BlockPos(0, 200, 0);
                        level.setBlock(passiveBeacon, LbcMagic.MAGIC_BEACON_BLOCK.defaultBlockState(), 3);
                        magic.blockChanged(passiveBeacon, level.getBlockState(passiveBeacon));
                        require(magic.beaconSuppressed(new Vec3(5.5, 200.5, 0.5)),
                                        "Native Polymer beacon suppresses passive at an in-range position");
                        player.setHealth(19.0F);
                        player.getInventory().setItem(35, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && !player.hasEffect(MobEffects.REGENERATION),
                                        "Beacon-only suppression gates metabolism within its sphere");
                        level.setBlock(passiveBeacon, net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),
                                        3);
                        magic.blockChanged(passiveBeacon, level.getBlockState(passiveBeacon));
                        passiveBeacon = null;
                        player.setHealth(player.getMaxHealth());

                        player.getInventory().setItem(35, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        require(magic.artifactTypes(player) == (1 << 8),
                                        "Typed artifact index recognizes type 8 in hotbar slot 35");

                        player.setHealth(player.getMaxHealth());
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && !player.hasEffect(MobEffects.REGENERATION),
                                        "Metabolism does nothing at full health");
                        player.setHealth(19.5F);
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && !player.hasEffect(MobEffects.REGENERATION),
                                        "Metabolism keeps source ceil health threshold at 19.5 of 20");
                        player.setHealth(19.9F);
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && !player.hasEffect(MobEffects.REGENERATION),
                                        "Metabolism keeps source ceil health threshold at 19.9 of 20");
                        player.setHealth(19.0F);
                        magic.tickPassives();
                        require(player.getEffect(MobEffects.HUNGER) != null
                                        && player.getEffect(MobEffects.HUNGER).getAmplifier() == 2
                                        && player.getEffect(MobEffects.HUNGER).getDuration() == 20
                                        && player.getEffect(MobEffects.REGENERATION) != null
                                        && player.getEffect(MobEffects.REGENERATION).getAmplifier() == 1
                                        && player.getEffect(MobEffects.REGENERATION).getDuration() == 45,
                                        "Metabolism refreshes Hunger III for twenty ticks and preserves a native Regeneration II heal interval");

                        player.removeAllEffects();
                        player.setHealth(10.0F);
                        magic.tickPassives();
                        for (int tick = 0; tick < 100; tick++) {
                                if (tick % 5 == 0)
                                        magic.tickPassives();
                                var regeneration = player.getEffect(MobEffects.REGENERATION);
                                require(regeneration != null,
                                                "Five-tick metabolism refresh keeps native regeneration alive");
                                if (!regeneration.tickServer(level, player, () -> {
                                }))
                                        player.removeEffect(MobEffects.REGENERATION);
                                var hunger = player.getEffect(MobEffects.HUNGER);
                                if (hunger != null && !hunger.tickServer(level, player, () -> {
                                }))
                                        player.removeEffect(MobEffects.HUNGER);
                        }
                        require(Math.abs(player.getHealth() - 14.0F) < 0.01F,
                                        "Native Regeneration II applies four heals over 100 ticks instead of pulsing on each five-tick refresh");
                        int regenAfterRemoval = player.getEffect(MobEffects.REGENERATION).getDuration();
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        magic.tickPassives();
                        require(regenAfterRemoval > 0 && regenAfterRemoval <= 45
                                        && player.hasEffect(MobEffects.REGENERATION),
                                        "Removing the artifact leaves only the bounded native regeneration duration");
                        for (int tick = 0; tick < 45 && player.hasEffect(MobEffects.REGENERATION); tick++) {
                                var regeneration = player.getEffect(MobEffects.REGENERATION);
                                if (!regeneration.tickServer(level, player, () -> {
                                }))
                                        player.removeEffect(MobEffects.REGENERATION);
                        }
                        require(!player.hasEffect(MobEffects.REGENERATION),
                                        "Regeneration expires within 45 native ticks without another artifact refresh");
                        player.getInventory().setItem(35, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();

                        player.removeAllEffects();
                        player.setHealth(19.0F);
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.HUNGER, 400, 2,
                                        true, false, false));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.REGENERATION, 400,
                                        1,
                                        true, false, false));
                        magic.tickPassives();
                        require(player.getEffect(MobEffects.HUNGER).getAmplifier() == 2
                                        && player.getEffect(MobEffects.HUNGER).getDuration() == 400
                                        && !player.getEffect(MobEffects.HUNGER).isAmbient()
                                        && player.getEffect(MobEffects.HUNGER).isVisible()
                                        && player.getEffect(MobEffects.REGENERATION).getAmplifier() == 1
                                        && player.getEffect(MobEffects.REGENERATION).getDuration() == 400
                                        && !player.getEffect(MobEffects.REGENERATION).isAmbient()
                                        && player.getEffect(MobEffects.REGENERATION).isVisible(),
                                        "Native equal-tier refresh preserves stronger duration and applies source ambient/visibility flags");

                        player.removeAllEffects();
                        player.setHealth(19.0F);
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.HUNGER, 400, 3,
                                        true, false, false));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.REGENERATION, 400,
                                        4,
                                        true, false, false));
                        magic.tickPassives();
                        require(player.getEffect(MobEffects.HUNGER).getAmplifier() == 3
                                        && player.getEffect(MobEffects.HUNGER).getDuration() == 400
                                        && player.getEffect(MobEffects.REGENERATION).getAmplifier() == 4
                                        && player.getEffect(MobEffects.REGENERATION).getDuration() == 400,
                                        "Native metabolism merge preserves effects with stronger amplifiers");

                        player.removeAllEffects();
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.ABSORPTION, 200,
                                        0));
                        player.setAbsorptionAmount(2);
                        require(player.getAbsorptionAmount() == 2,
                                        "Native absorption fixture has two real absorption health points");
                        player.setHealth(18.0F);
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && !player.hasEffect(MobEffects.REGENERATION),
                                        "Absorption health of 18 plus 2 stays at the source threshold");

                        player.setAbsorptionAmount(0);
                        player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH)
                                        .setBaseValue(20.5);
                        player.setHealth(19.9F);
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && !player.hasEffect(MobEffects.REGENERATION),
                                        "Source positive-integer max-health truncation preserves noninteger max health");
                        player.setHealth(19.0F);
                        magic.tickPassives();
                        require(player.hasEffect(MobEffects.HUNGER) && player.hasEffect(MobEffects.REGENERATION),
                                        "Noninteger max health still activates below the truncated source threshold");
                        player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH)
                                        .setBaseValue(priorMaxHealthBase);

                        player.removeAllEffects();
                        player.setAbsorptionAmount(0);
                        player.setHealth(19.0F);
                        player.getInventory().setItem(1, clear.copy());
                        player.getInventory().setItem(2, clear.copy());
                        triggerNativeInventoryChange(player, clear);
                        magic.tick();
                        require(magic.artifactTypes(player) == ((1 << 6) | (1 << 8)),
                                        "Inventory snapshot combines type 6 and type 8 passives");
                        magic.tickPassives();
                        require(player.getActiveEffects().isEmpty(),
                                        "Type 6 runs after metabolism when both passives are held");

                        // Keep the real type-1 source artifact alongside the type-8 stack.
                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact");
                        var direct = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                        player.getInventory().setItem(0, direct.copy());
                        player.getInventory().setItem(1, metabolism.copy());
                        triggerNativeInventoryChange(player, direct);
                        magic.tick();
                        require(magic.artifactActive(player) && (magic.artifactTypes(player) & (1 << 8)) != 0,
                                        "Type 1 and type 8 are tracked together without player-artifact suppression");
                        player.setHealth(19.0F);
                        magic.tickPassives();
                        require(player.hasEffect(MobEffects.HUNGER) && player.hasEffect(MobEffects.REGENERATION),
                                        "Type 1 player artifact does not block metabolism effects");

                        player.removeAllEffects();
                        player.getInventory().clearContent();
                        player.setHealth(player.getMaxHealth());
                        player.setGameMode(GameType.CREATIVE);
                        player.getInventory().setItem(0, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        player.setHealth(19.0F);
                        magic.tickPassives();
                        require(game.canUseGameplayItems(player) && player.hasEffect(MobEffects.HUNGER),
                                        "Eligible Creative participant receives passive effects");

                        if (!observerWasObserver)
                                game.spectators().enter(observer);
                        observer.getInventory().clearContent();
                        observer.setGameMode(GameType.CREATIVE);
                        observer.getInventory().setItem(0, metabolism.copy());
                        triggerNativeInventoryChange(observer, metabolism);
                        magic.tick();
                        observer.setHealth(Math.max(1, observer.getMaxHealth() - 1));
                        magic.tickPassives();
                        require(!game.canUseGameplayItems(observer) && magic.artifactTypes(observer) == 0
                                        && !observer.hasEffect(MobEffects.HUNGER)
                                        && !observer.hasEffect(MobEffects.REGENERATION),
                                        "Creative observer remains excluded from passive artifact effects");
                } finally {
                        if (passiveBeacon != null) {
                                level.setBlock(passiveBeacon,
                                                net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(), 3);
                                magic.blockChanged(passiveBeacon, level.getBlockState(passiveBeacon));
                        }
                        player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH)
                                        .setBaseValue(priorMaxHealthBase);
                        player.removeAllEffects();
                        player.setAbsorptionAmount(0);
                        player.setHealth(player.getMaxHealth());
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        player.setGameMode(priorMode);
                        observer.removeAllEffects();
                        observer.getInventory().clearContent();
                        triggerNativeInventoryChange(observer, ItemStack.EMPTY);
                        magic.tick();
                        if (!observerWasObserver && game.isObserver(observer))
                                game.spectators().remove(observer);
                        observer.setGameMode(observerPriorMode);
                        observer.setHealth(Math.min(observerPriorHealth, observer.getMaxHealth()));
                        player.teleportTo(priorLevel, priorPosition.x, priorPosition.y, priorPosition.z,
                                        java.util.Set.of(), 0, 0, true);
                        player.setNoGravity(priorNoGravity);
                        player.setHealth(Math.min(player.getHealth(), player.getMaxHealth()));
                }
                // РћСЃС‚Р°РІР»СЏРµРј СЂРµР°Р»СЊРЅРѕРµ СЃРѕСЃС‚РѕСЏРЅРёРµ Рё СЌС„С„РµРєС‚С‹ РґР»СЏ СЃР»РµРґСѓСЋС‰РµРіРѕ /sw stop, С‡С‚РѕР±С‹ cleanup
                // РЅРµ Р±С‹Р» РїСѓСЃС‚РѕР№ РїСЂРѕРІРµСЂРєРѕР№.
                game.lbc().grantTable(player, "lbc:ported/mystical_artifact_metabolism");
                triggerNativeInventoryChange(player, inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT));
                magic.tick();
                player.setHealth(Math.max(1, player.getMaxHealth() - 1));
                magic.tickPassives();
                require(magic.artifactTypes(player) == (1 << 8) && player.hasEffect(MobEffects.REGENERATION),
                                "A tracked passive holder and native effect remain for the real match-stop command");
                SkyWars2.LOGGER.info("[check] PASS artifact-passives");
        }

        public static void checkArtifactPassivesCleanup(GameController game) {
                require(game.inLobby(), "Artifact passive cleanup requires lobby");
                var magic = game.items().magic();
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var priorLevel = player.level();
                var priorPosition = player.position();
                var priorNoGravity = player.isNoGravity();
                var priorMode = player.gameMode.getGameModeForPlayer();
                for (var current : game.server().getPlayerList().getPlayers()) {
                        require(magic.artifactTypes(current) == 0,
                                        "Match stop forgets passive artifact types for " + current.getScoreboardName());
                        require(itemCount(current, LbcMagic.MYSTICAL_ARTIFACT) == 0
                                        && !current.hasEffect(MobEffects.HUNGER)
                                        && !current.hasEffect(MobEffects.REGENERATION),
                                        "Real lobby reset clears passive items and effects");
                }
                player.entityTags().add("developer");
                player.setGameMode(GameType.CREATIVE);
                player.setNoGravity(true);
                player.teleportTo(game.maps().level(), 0, 250, -3, java.util.Set.of(), 0, 0, true);
                try {
                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_metabolism");
                        var metabolism = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                        player.getInventory().setItem(0, metabolism.copy());
                        triggerNativeInventoryChange(player, metabolism);
                        magic.tick();
                        player.setHealth(Math.max(1, player.getMaxHealth() - 1));
                        magic.tickPassives();
                        require(game.canUseGameplayItems(player) && player.hasEffect(MobEffects.HUNGER)
                                        && player.hasEffect(MobEffects.REGENERATION),
                                        "Creative developer can use metabolism in the lobby");
                } finally {
                        player.removeAllEffects();
                        player.setHealth(player.getMaxHealth());
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        player.entityTags().remove("developer");
                        player.setGameMode(priorMode);
                        player.teleportTo(priorLevel, priorPosition.x, priorPosition.y, priorPosition.z,
                                        java.util.Set.of(), 0, 0, true);
                        player.setNoGravity(priorNoGravity);
                }
                SkyWars2.LOGGER.info("[check] PASS artifact-passives-cleanup");
        }

        /**
         * Focused native checks for the debuff artifact and the shared cleansing path.
         */
        public static void checkArtifactDebuffMenu(GameController game) {
                require(game.inLobby(), "Artifact debuff loot checks require lobby");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player != null, "Create reusable test bots before debuff item setup");
                player.getInventory().clearContent();
                game.lbc().grantTable(player, "lbc:ported/mystical_artifact_debuff");
                var stack = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                var data = stack.get(DataComponents.CUSTOM_DATA).copyTag();
                require(stack.getCount() == 1 && data.getInt("mystical").orElse(0) == 1
                                && data.getInt("type").orElse(0) == 5,
                                "Source loot grants the exact mystical artifact type 5");
                require(stack.has(DataComponents.LORE) && stack.has(DataComponents.TOOLTIP_STYLE),
                                "Type 5 retains source tooltip components");
                requirePolymerStack(player, stack, Items.REPEATING_COMMAND_BLOCK, "Mystical artifact type 5");
                player.getInventory().clearContent();
        }

        public static void checkArtifactDebuffs(GameController game) {
                require(game.playing(), "Artifact debuff checks require a live match");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var magic = game.items().magic();
                var items = game.items();
                var frost = items.frost();
                var level = game.maps().level();
                var priorMode = player.gameMode.getGameModeForPlayer();
                var priorLevel = player.level();
                var priorPosition = player.position();
                var priorNoGravity = player.isNoGravity();
                var ownedMobs = new java.util.ArrayList<net.minecraft.world.entity.animal.cow.Cow>();
                try {
                        player.closeContainer();
                        player.getInventory().clearContent();
                        player.setGameMode(GameType.SURVIVAL);
                        player.setNoGravity(true);
                        player.teleportTo(level, 4, 200, 4, java.util.Set.of(), 0, 0, true);
                        player.removeAllEffects();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_debuff");
                        var debuff = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().setItem(0, debuff);
                        triggerNativeInventoryChange(player, debuff);
                        magic.tick();
                        require(magic.artifactTypes(player) == (1 << 5), "Typed artifact index recognizes type 5");

                        var negatives = java.util.List.of(MobEffects.BLINDNESS, MobEffects.SLOWNESS,
                                        MobEffects.WEAKNESS,
                                        MobEffects.MINING_FATIGUE, MobEffects.GLOWING, MobEffects.HUNGER,
                                        MobEffects.INSTANT_DAMAGE,
                                        MobEffects.NAUSEA, MobEffects.POISON, MobEffects.UNLUCK, MobEffects.WITHER);
                        for (var effect : negatives)
                                player.addEffect(new net.minecraft.world.effect.MobEffectInstance(effect, 400, 0));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.LEVITATION, 400,
                                        0));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.SPEED, 400, 1));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.REGENERATION, 400,
                                        1));
                        magic.tickPassives();
                        for (var effect : negatives)
                                require(!player.hasEffect(effect), "Type 5 removes " + effect);
                        require(!player.hasEffect(MobEffects.LEVITATION) && player.hasEffect(MobEffects.SPEED)
                                        && player.hasEffect(MobEffects.REGENERATION),
                                        "Type 5 removes ordinary levitation while retaining positive effects");

                        var levitationCases = java.util.List.of(
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.FEET, "reactive", -1,
                                                        false },
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.FEET, "technomk2", -1,
                                                        false },
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.LEGS, "techno", -1,
                                                        false },
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.LEGS, "technomk2", -1,
                                                        false },
                                        new Object[] { null, "reactive_shish", 0, false },
                                        new Object[] { null, "reactive_shish", 35, false },
                                        new Object[] { null, "reactive_shish", 40, false },
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.HEAD, "reactive", -1,
                                                        true },
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.LEGS, "reactive", -1,
                                                        true },
                                        new Object[] { net.minecraft.world.entity.EquipmentSlot.FEET, "techno", -1,
                                                        true },
                                        new Object[] { null, "technomk2", 0, true });
                        for (var fixture : levitationCases) {
                                player.getInventory().clearContent();
                                player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD, ItemStack.EMPTY);
                                player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.LEGS, ItemStack.EMPTY);
                                player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET, ItemStack.EMPTY);
                                player.getInventory().setItem(40, ItemStack.EMPTY);
                                player.getInventory().setItem(34, debuff.copy());
                                triggerNativeInventoryChange(player, debuff);
                                magic.tick();
                                var data = new net.minecraft.nbt.CompoundTag();
                                data.putInt((String) fixture[1], 1);
                                var marker = new ItemStack(Items.STICK);
                                marker.set(DataComponents.CUSTOM_DATA,
                                                net.minecraft.world.item.component.CustomData.of(data));
                                if (fixture[0] != null)
                                        player.setItemSlot((net.minecraft.world.entity.EquipmentSlot) fixture[0],
                                                        marker);
                                else
                                        player.getInventory().setItem((Integer) fixture[2], marker);
                                player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.LEVITATION,
                                                400, 0));
                                magic.tickPassives();
                                require(player.hasEffect(MobEffects.LEVITATION) != (Boolean) fixture[3],
                                                "Type 5 levitation protection slot/tag " + fixture[1] + " / "
                                                                + fixture[2]);
                        }
                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_metabolism");
                        var metabolism = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_clear");
                        var clear = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().clearContent();
                        player.getInventory().setItem(0, debuff.copy());
                        player.getInventory().setItem(1, metabolism.copy());
                        triggerNativeInventoryChange(player, debuff);
                        magic.tick();
                        require(magic.artifactTypes(player) == ((1 << 5) | (1 << 8)),
                                        "Inventory combines type 5 and type 8");
                        player.setHealth(10);
                        magic.tickPassives();
                        require(!player.hasEffect(MobEffects.HUNGER) && player.hasEffect(MobEffects.REGENERATION),
                                        "Type 5 runs after metabolism, clearing Hunger while retaining positive regeneration");
                        player.getInventory().setItem(2, clear.copy());
                        triggerNativeInventoryChange(player, clear);
                        magic.tick();
                        require(magic.artifactTypes(player) == ((1 << 5) | (1 << 6) | (1 << 8)),
                                        "Inventory combines types 5, 6 and 8 without losing the exact mask");
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 400, 0));
                        player.setHealth(10);
                        magic.tickPassives();
                        require(player.getActiveEffects().isEmpty(), "Type 6 runs last after type 5 and metabolism");
                        require(magic.artifactTypes(player) == ((1 << 5) | (1 << 6) | (1 << 8)),
                                        "Effect cleanup leaves the tracked artifact mask coherent");
                        player.setHealth(player.getMaxHealth());

                        // Type 6 delegates to the same cleanup helper even when the player has no
                        // native effects;
                        // frost and turn-curse state must still be released by that shared path.
                        player.getInventory().clearContent();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_clear");
                        clear = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        var anchor = player.blockPosition();
                        var originalLower = level.getBlockState(anchor);
                        var originalUpper = level.getBlockState(anchor.above());
                        frost.add(player, null);
                        require(frost.cold(player) > 0, "Cold status exists before type-6 acquisition");
                        player.getInventory().setItem(0, clear);
                        triggerNativeInventoryChange(player, clear);
                        player.doTick();
                        player.removeAllEffects();
                        require(frost.cold(player) == 0 && frost.trackedCount() == 0
                                        && player.getActiveEffects().isEmpty(),
                                        "Inventory activation immediately clears pre-existing cold-only state");
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        for (int i = 0; i < 10; i++)
                                frost.add(player, null);
                        require(frost.frozenSeconds(player) > 0 && frost.iceBlockCount() > 0,
                                        "Cold fixture owns frozen attachment and temporary ice");
                        var totem = new ItemStack(Items.TOTEM_OF_UNDYING);
                        var totemData = new net.minecraft.nbt.CompoundTag();
                        totemData.putInt("broken_totem", 1);
                        totem.set(DataComponents.CUSTOM_DATA,
                                        net.minecraft.world.item.component.CustomData.of(totemData));
                        items.usedTotem(player, totem);
                        require(items.curseTicks(player) > 0, "Turn-curse fixture is active before shared cleansing");
                        player.entityTags().add("lightningist");
                        player.entityTags().add("greed_cursed");
                        player.getInventory().setItem(0, clear.copy());
                        triggerNativeInventoryChange(player, clear);
                        player.doTick();
                        player.removeAllEffects();
                        require(frost.frozenSeconds(player) == 0 && frost.trackedCount() == 0
                                        && frost.iceBlockCount() == 0,
                                        "Type 6 immediately thaws pre-existing frozen state without native effects");
                        require(level.getBlockState(anchor).equals(originalLower)
                                        && level.getBlockState(anchor.above()).equals(originalUpper),
                                        "Artifact cleansing restores both exact original block states");
                        require(items.curseTicks(player) == 0, "Type 6 shared clear removes turn-curse state");
                        require(!player.entityTags().contains("lightningist")
                                        && !player.entityTags().contains("greed_cursed"),
                                        "Type 6 shared clear removes transient lightning and greed tags");
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        for (int i = 0; i < 10; i++)
                                frost.add(player, null);
                        items.usedTotem(player, totem);
                        require(frost.frozenSeconds(player) > 0 && items.curseTicks(player) > 0,
                                        "Purifier fixture starts with frozen attachment and turn curse");
                        player.addEffect(
                                        new net.minecraft.world.effect.MobEffectInstance(MobEffects.RAID_OMEN, 40, 43));
                        require(frost.frozenSeconds(player) == 0 && frost.trackedCount() == 0
                                        && frost.iceBlockCount() == 0 && items.curseTicks(player) == 0
                                        && player.getActiveEffects().isEmpty(),
                                        "Native purifier effect callback reuses shared frost, curse and potion cleanup");
                        magic.tickPassives();
                        require(player.getActiveEffects().isEmpty(),
                                        "Type 6 invokes shared cleanup on its periodic pass");

                        // РћР±С‰РёР№ Р»С‘Рґ РїСЂРёРЅР°РґР»РµР¶РёС‚ РґРІСѓРј С†РµР»СЏРј: СЃР°РјРѕРѕС‡РёСЃС‚РєР° РЅРµ РґРѕР»Р¶РЅР° РѕСЃРІРѕР±РѕР¶РґР°С‚СЊ С‡СѓР¶СѓСЋ
                        // Р·Р°РјРѕСЂРѕР·РєСѓ.
                        var other = frostProbeCow(level, ownedMobs, anchor.getX(), anchor.getY(), anchor.getZ());
                        for (int i = 0; i < 10; i++) {
                                frost.add(player, null);
                                frost.add(other, null);
                        }
                        player.getInventory().setItem(0, clear.copy());
                        triggerNativeInventoryChange(player, clear);
                        magic.beforeEffects(player);
                        frost.tick();
                        require(frost.frozenSeconds(player) == 0 && frost.frozenSeconds(other) > 0
                                        && frost.iceBlockCount() == 2
                                        && level.getBlockState(anchor).is(net.minecraft.world.level.block.Blocks.ICE),
                                        "Cleansing one owner retains another frozen target and its overlapping ice leases");
                        player.setPos(anchor.getX() + 3, anchor.getY(), anchor.getZ());
                        frost.tick();
                        require(player.getX() == anchor.getX() + 3,
                                        "Cleansed player is no longer tethered by frozen ticks");
                        frost.clear(other);
                        require(frost.iceBlockCount() == 0 && level.getBlockState(anchor).equals(originalLower)
                                        && level.getBlockState(anchor.above()).equals(originalUpper),
                                        "Last overlapping owner cleanup restores both original blocks");
                } finally {
                        items.clearEffects(player);
                        player.removeAllEffects();
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        for (var mob : ownedMobs) {
                                frost.clear(mob);
                                mob.discard();
                        }
                        player.setGameMode(priorMode);
                        player.teleportTo(priorLevel, priorPosition.x, priorPosition.y, priorPosition.z,
                                        java.util.Set.of(), 0, 0, true);
                        player.setNoGravity(priorNoGravity);
                }
                SkyWars2.LOGGER.info("[check] PASS artifact-debuffs");
        }

        /**
         * Immediate cleanse guard assertions, independent of the five-tick passive pulse.
         */
        public static void checkArtifactCleanseImmediate(GameController game) {
                require(game.playing(), "Immediate cleanse checks require a live match");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var observer = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                var magic = game.items().magic();
                var items = game.items();
                var priorMode = player.gameMode.getGameModeForPlayer();
                var priorLevel = player.level();
                var priorPosition = player.position();
                var priorHealth = player.getHealth();
                var priorObserverMode = observer.gameMode.getGameModeForPlayer();
                var priorObserverHealth = observer.getHealth();
                var priorNoGravity = player.isNoGravity();
                boolean observerWasObserver = game.isObserver(observer);
                var beacon = new net.minecraft.core.BlockPos(4, 199, 4);
                var priorBeacon = game.maps().level().getBlockState(beacon);
                boolean beaconInstalled = false;
                try {
                        player.closeContainer();
                        player.getInventory().clearContent();
                        player.removeAllEffects();
                        player.setGameMode(GameType.SURVIVAL);
                        player.setNoGravity(true);
                        player.teleportTo(game.maps().level(), 4, 200, 4, java.util.Set.of(), 0, 0, true);

                        // Type 5 vetoes only its fixed debuff family and retains the native levitation exceptions.
                        player.setInvulnerableTime(0);
                        player.damageCooldownTime = 0;
                        player.setHealth(player.getMaxHealth());
                        float unprotectedHealth = player.getHealth();
                        MobEffects.INSTANT_DAMAGE.value().applyInstantaneousEffect(
                                        game.maps().level(), null, null, player, 0, 1.0);
                        require(player.getHealth() < unprotectedHealth,
                                        "Unprotected native instant harm genuinely damages the control fixture");
                        player.damageCooldownTime = 0;
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_debuff");
                        var debuff = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().setItem(0, debuff);
                        triggerNativeInventoryChange(player, debuff);
                        require(magic.rejectEffect(player, MobEffects.POISON),
                                        "Type 5 immediately rejects poison before passive tick");
                        require(magic.rejectEffect(player, MobEffects.INSTANT_DAMAGE)
                                        && !magic.rejectEffect(player, MobEffects.INSTANT_HEALTH),
                                        "Type 5 preserves its instant-harm debuff policy and allows instant healing");
                        require(!magic.rejectEffect(player, MobEffects.REGENERATION),
                                        "Type 5 retains positive regeneration");
                        player.setHealth(10.0F);
                        MobEffects.INSTANT_DAMAGE.value().applyInstantaneousEffect(
                                        game.maps().level(), null, null, player, 0, 1.0);
                        require(player.getHealth() == 10.0F,
                                        "Type 5 blocks native instantaneous harm before it changes health");
                        MobEffects.INSTANT_HEALTH.value().applyInstantaneousEffect(
                                        game.maps().level(), null, null, player, 0, 1.0);
                        require(player.getHealth() > 10.0F,
                                        "Type 5 allows native instantaneous healing");
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 25, 0));
                        require(!player.hasEffect(MobEffects.POISON),
                                        "Native addEffect cannot apply a rejected type-5 debuff");
                        player.forceAddEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 100, 0), null);
                        require(!player.hasEffect(MobEffects.POISON),
                                        "Native forceAddEffect cannot bypass the type-5 debuff guard");
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();

                        // РЈР¶Рµ РґРµР№СЃС‚РІСѓСЋС‰РёР№ poison РґРѕР»Р¶РµРЅ СЃРЅРёРјР°С‚СЊСЃСЏ РґРѕ СѓСЂРѕРЅР° Рё РїСЂРё РІС‹Р±РѕСЂРѕС‡РЅРѕРј С‚РёРїРµ 5.
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 25, 0));
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.SPEED, 100, 0));
                        require(player.hasEffect(MobEffects.POISON), "Pre-acquisition type-5 poison fixture is present");
                        player.setHealth(10.0F);
                        player.getInventory().setItem(0, debuff.copy());
                        triggerNativeInventoryChange(player, debuff);
                        player.doTick();
                        require(player.getHealth() == 10.0F && !player.hasEffect(MobEffects.POISON)
                                        && player.hasEffect(MobEffects.SPEED),
                                        "Type 5 clears old poison before damage while keeping a positive effect");
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        magic.tick();
                        player.removeAllEffects();

                        // Type 6 clears a pre-existing native effect at the first native effect phase.
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 25, 0));
                        require(player.hasEffect(MobEffects.POISON), "Pre-acquisition poison fixture is present");
                        player.setHealth(10.0F);
                        float healthBeforePoisonPhase = player.getHealth();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_clear");
                        var clear = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().setItem(0, clear);
                        triggerNativeInventoryChange(player, clear);
                        player.doTick();
                        require(!player.hasEffect(MobEffects.POISON),
                                        "Type 6 clears pre-existing poison before the next effect damage phase");
                        require(player.getHealth() == healthBeforePoisonPhase,
                                        "Pre-existing poison causes no damage after cleanup at the native effect-phase head");
                        player.setHealth(10.0F);
                        MobEffects.INSTANT_DAMAGE.value().applyInstantaneousEffect(
                                        game.maps().level(), null, null, player, 0, 1.0);
                        MobEffects.INSTANT_HEALTH.value().applyInstantaneousEffect(
                                        game.maps().level(), null, null, player, 0, 1.0);
                        require(player.getHealth() == 10.0F,
                                        "Type 6 blocks both native instantaneous harm and healing applications");
                        require(magic.rejectEffect(player, MobEffects.POISON)
                                        && magic.rejectEffect(player, MobEffects.INSTANT_DAMAGE)
                                        && magic.rejectEffect(player, MobEffects.INSTANT_HEALTH)
                                        && magic.rejectEffect(player, MobEffects.REGENERATION),
                                        "Type 6 immediately rejects poison and both instant harm and healing");
                        player.forceAddEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 100, 0), null);
                        require(!player.hasEffect(MobEffects.POISON),
                                        "Native forceAddEffect cannot bypass the type-6 guard");
                        require(magic.rejectCustomEffect(player),
                                        "Type 6 immediately rejects custom statuses");
                        items.frost().add(player, null);
                        require(items.frost().cold(player) == 0,
                                        "Active type 6 prevents custom frost accumulation before pulse");
                        var mana = items.mana();
                        int beforeMana = mana.get(player);
                        mana.boost(player, 40);
                        mana.reverse(player, 10);
                        mana.applyNoMagic(player, 10);
                        require(mana.boost(player) == 0 && mana.reverse(player) == 0
                                        && mana.noMagic(player) == 0 && mana.get(player) == beforeMana,
                                        "Type 6 rejects custom mana statuses before timer changes or resource loss");
                        var brokenTotem = new ItemStack(Items.TOTEM_OF_UNDYING);
                        var brokenData = new net.minecraft.nbt.CompoundTag();
                        brokenData.putInt("broken_totem", 1);
                        brokenTotem.set(DataComponents.CUSTOM_DATA,
                                        net.minecraft.world.item.component.CustomData.of(brokenData));
                        items.usedTotem(player, brokenTotem);
                        require(items.curseTicks(player) == 0,
                                        "Active type 6 prevents custom turn curse before item tick");

                        // After removal the same status is accepted immediately, without waiting for refresh.
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        player.doTick();
                        require(!magic.rejectEffect(player, MobEffects.POISON),
                                        "Removed type 6 stops rejecting poison immediately");
                        player.addEffect(new net.minecraft.world.effect.MobEffectInstance(MobEffects.POISON, 100, 0));
                        require(player.hasEffect(MobEffects.POISON),
                                        "Poison applies in the same server tick after type 6 removal");

                        // The observer role and beacon suppression never grant a passive immunity.
                        player.removeAllEffects();
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_clear");
                        clear = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        player.getInventory().setItem(0, clear);
                        triggerNativeInventoryChange(player, clear);
                        game.maps().level().setBlock(beacon, LbcMagic.MAGIC_BEACON_BLOCK.defaultBlockState(), 3);
                        beaconInstalled = true;
                        magic.blockChanged(beacon, game.maps().level().getBlockState(beacon));
                        require(magic.beaconSuppressed(player.position()), "Immediate fixture is inside beacon range");
                        require(!magic.rejectEffect(player, MobEffects.POISON),
                                        "Beacon-suppressed type 6 does not create immunity");
                        mana.boost(player, 40);
                        mana.reverse(player, 10);
                        mana.applyNoMagic(player, 10);
                        require(mana.boost(player) > 0 && mana.reverse(player) > 0 && mana.noMagic(player) > 0,
                                        "Suppressed type 6 allows temporary mana statuses");
                        mana.set(player, 1000);
                        game.maps().level().setBlock(beacon, priorBeacon, 3);
                        magic.blockChanged(beacon, priorBeacon);
                        beaconInstalled = false;
                        mana.tickPlayer(player);
                        require(mana.boost(player) == 0 && mana.reverse(player) == 0 && mana.noMagic(player) == 0
                                        && mana.get(player) >= 1000,
                                        "Leaving beacon suppression clears old statuses before their next mana step");

                        if (!observerWasObserver) game.spectators().enter(observer);
                        observer.setGameMode(GameType.SPECTATOR);
                        observer.getInventory().clearContent();
                        game.lbc().grantTable(observer, "lbc:ported/mystical_artifact_clear");
                        var observerClear = inventoryItem(observer, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        observer.getInventory().setItem(0, observerClear);
                        triggerNativeInventoryChange(observer, observerClear);
                        require(!magic.rejectEffect(observer, MobEffects.POISON),
                                        "Observer role does not acquire type-6 immunity");
                } finally {
                        if (beaconInstalled) {
                                game.maps().level().setBlock(beacon, priorBeacon, 3);
                                magic.blockChanged(beacon, priorBeacon);
                        }
                        items.clearEffects(player);
                        player.removeAllEffects();
                        player.getInventory().clearContent();
                        triggerNativeInventoryChange(player, ItemStack.EMPTY);
                        observer.getInventory().clearContent();
                        triggerNativeInventoryChange(observer, ItemStack.EMPTY);
                        if (!observerWasObserver && game.isObserver(observer)) game.spectators().remove(observer);
                        observer.setGameMode(priorObserverMode);
                        observer.setHealth(Math.min(priorObserverHealth, observer.getMaxHealth()));
                        player.setGameMode(priorMode);
                        player.setNoGravity(priorNoGravity);
                        player.teleportTo(priorLevel, priorPosition.x, priorPosition.y, priorPosition.z,
                                        java.util.Set.of(), 0, 0, true);
                        player.setHealth(Math.min(priorHealth, player.getMaxHealth()));
                }
                SkyWars2.LOGGER.info("[check] PASS artifact-cleanse-immediate");
        }

        /**
         * Source fixture for the type-4 arrow artifact; the active check leaves one
         * holder for stop cleanup.
         */
        public static void checkArtifactArrowsMenu(GameController game) {
                require(game.inLobby(), "Arrow artifact loot checks require lobby");
                var player = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                require(player != null, "Create reusable test bots before arrow artifact setup");
                player.getInventory().clearContent();
                try {
                        game.lbc().grantTable(player, "lbc:ported/mystical_artifact_arrows");
                        var stack = inventoryItem(player, LbcMagic.MYSTICAL_ARTIFACT);
                        var data = stack.get(DataComponents.CUSTOM_DATA).copyTag();
                        require(stack.getCount() == 1 && data.getInt("mystical").orElse(0) == 1
                                        && data.getInt("type").orElse(0) == 4,
                                        "Source loot grants exactly one mystical artifact type 4");
                        require(stack.has(DataComponents.LORE) && stack.has(DataComponents.TOOLTIP_STYLE),
                                        "Type 4 retains source lore and tooltip style defaults");
                        requirePolymerStack(player, stack, Items.REPEATING_COMMAND_BLOCK, "Mystical artifact type 4");
                } finally {
                        player.getInventory().clearContent();
                }
                game.menus().open(player);
        }

        public static void checkArtifactArrows(GameController game) {
                require(game.playing(), "Arrow artifact checks require an active match");
                var magic = game.items().magic();
                var level = game.maps().level();
                var holder = game.server().getPlayerList().getPlayer(offlineUuid("TestAlpha"));
                var second = game.server().getPlayerList().getPlayer(offlineUuid("TestBeta"));
                require(holder != null && second != null && game.allowDamage(holder) && game.allowDamage(second),
                                "Two active participants are available for holder overlap checks");
                var holderMode = holder.gameMode.getGameModeForPlayer();
                var secondMode = second.gameMode.getGameModeForPlayer();
                var holderLevel = holder.level();
                var holderPosition = holder.position();
                var secondLevel = second.level();
                var secondPosition = second.position();
                boolean holderNoGravity = holder.isNoGravity(), secondNoGravity = second.isNoGravity();
                var holderInventory = new ItemStack[holder.getInventory().getContainerSize()];
                var secondInventory = new ItemStack[second.getInventory().getContainerSize()];
                for (int slot = 0; slot < holderInventory.length; slot++)
                        holderInventory[slot] = holder.getInventory().getItem(slot).copy();
                for (int slot = 0; slot < secondInventory.length; slot++)
                        secondInventory[slot] = second.getInventory().getItem(slot).copy();
                var probes = new java.util.ArrayList<net.minecraft.world.entity.Entity>();
                ItemStack artifactForCleanup = ItemStack.EMPTY;
                var tablePos = new net.minecraft.core.BlockPos(1, 199, 0);
                var oldTable = level.getBlockState(tablePos);
                boolean tableChanged = false;
                boolean secondWasObserver = game.isObserver(second);
                boolean holderDeveloper = holder.entityTags().contains("developer");
                boolean secondDeveloper = second.entityTags().contains("developer");
                var scoreboard = game.server().getScoreboard();
                var holderTeam = scoreboard.getPlayersTeam(holder.getScoreboardName());
                var secondTeam = scoreboard.getPlayersTeam(second.getScoreboardName());
                var probeTeam = scoreboard.getPlayerTeam("lbc-arrow-probe");
                if (probeTeam != null)
                        scoreboard.removePlayerTeam(probeTeam);
                probeTeam = scoreboard.addPlayerTeam("lbc-arrow-probe");
                try {
                        holder.closeContainer();
                        second.closeContainer();
                        holder.setNoGravity(true);
                        second.setNoGravity(true);
                        holder.teleportTo(level, 0, 200, 0, java.util.Set.of(), 0, 0, true);
                        second.teleportTo(level, 0, 200, 0, java.util.Set.of(), 0, 0, true);
                        holder.getInventory().clearContent();
                        second.getInventory().clearContent();
                        game.lbc().grantTable(holder, "lbc:ported/mystical_artifact_arrows");
                        var artifact = inventoryItem(holder, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        artifactForCleanup = artifact.copy();
                        holder.getInventory().setItem(0, artifact.copy());
                        triggerNativeInventoryChange(holder, artifact);
                        magic.tick();
                        require(magic.artifactTypes(holder) == (1 << 4), "Typed inventory index recognizes type 4");

                        // The same native menu packet hooks refresh cursor and recipe-grid holders.
                        nativeMagicClick(holder, 36);
                        magic.tick();
                        require(holder.containerMenu.getCarried().is(LbcMagic.MYSTICAL_ARTIFACT)
                                        && magic.artifactTypes(holder) == (1 << 4),
                                        "Native cursor pickup retains type-4 protection");
                        nativeMagicClick(holder, 1);
                        magic.tick();
                        require(holder.containerMenu.getCarried().isEmpty() && magic.artifactTypes(holder) == (1 << 4),
                                        "Native 2x2 crafting input retains type-4 protection");
                        nativeMagicClick(holder, 1);
                        nativeMagicClick(holder, -999);
                        magic.tick();
                        require(magic.artifactTypes(holder) == 0,
                                        "Native cursor drop immediately clears type-4 holder state");
                        for (var drop : level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,
                                        holder.getBoundingBox().inflate(8),
                                        item -> item.getItem().is(LbcMagic.MYSTICAL_ARTIFACT)))
                                drop.discard();
                        level.setBlock(tablePos,
                                        net.minecraft.world.level.block.Blocks.CRAFTING_TABLE.defaultBlockState(), 3);
                        tableChanged = true;
                        holder.getInventory().setItem(0, artifact.copy());
                        triggerNativeInventoryChange(holder, artifact);
                        magic.tick();
                        holder.openMenu(new net.minecraft.world.SimpleMenuProvider(
                                        (id, inventory, owner) -> new net.minecraft.world.inventory.CraftingMenu(id,
                                                        inventory,
                                                        net.minecraft.world.inventory.ContainerLevelAccess.create(level,
                                                                        tablePos)),
                                        Component.literal("arrow artifact test")));
                        nativeMagicClick(holder, 37);
                        nativeMagicClick(holder, 1);
                        magic.tick();
                        require(holder.containerMenu.getCarried().isEmpty() && magic.artifactTypes(holder) == (1 << 4),
                                        "Native 3x3 crafting input retains type-4 protection");
                        nativeMagicClick(holder, 1);
                        nativeMagicClick(holder, -999);
                        magic.tick();
                        require(magic.artifactTypes(holder) == 0,
                                        "Dropping a 3x3 recipe input clears type-4 holder state");
                        holder.closeContainer();
                        level.setBlock(tablePos, oldTable, 3);
                        tableChanged = false;
                        for (var drop : level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,
                                        holder.getBoundingBox().inflate(8),
                                        item -> item.getItem().is(LbcMagic.MYSTICAL_ARTIFACT)))
                                drop.discard();

                        second.getInventory().setItem(0, artifact.copy());
                        holder.getInventory().setItem(0, artifact.copy());
                        triggerNativeInventoryChange(holder, artifact);
                        triggerNativeInventoryChange(second, artifact);
                        magic.tick();
                        require(magic.artifactTypes(second) == (1 << 4),
                                        "Overlapping active holder is indexed once by UUID");
                        scoreboard.addPlayerToTeam(holder.getScoreboardName(), probeTeam);
                        scoreboard.addPlayerToTeam(second.getScoreboardName(), probeTeam);

                        var sparseArrow = arrowProbe(level, probes, 2, 200, 0, holder);
                        magic.tickArrows();
                        require(sparseArrow.isRemoved(),
                                        "One arrow and two holders exercise the sparse-arrow spatial query");
                        var nativeArrow = arrowProbe(level, probes, 0, 200, 0, holder);
                        var spectral = new net.minecraft.world.entity.projectile.arrow.SpectralArrow(
                                        net.minecraft.world.entity.EntityTypes.SPECTRAL_ARROW, level);
                        spectral.setOwner(second);
                        spectral.setNoGravity(true);
                        spectral.setDeltaMovement(Vec3.ZERO);
                        spectral.setPos(1, 200, 0);
                        level.addFreshEntity(spectral);
                        probes.add(spectral);
                        // Р”Р°Р»РµРєРѕ РїРѕ РІРµСЂС‚РёРєР°Р»Рё, РЅРѕ РІ С‚РѕРј Р¶Рµ Р·Р°РіСЂСѓР¶РµРЅРЅРѕРј С‡Р°РЅРєРµ: РёРЅР°С‡Рµ entity-load РµС‰С‘ РЅРµ
                        // РЅР°СЃС‚СѓРїРёС‚.
                        var distantArrow = arrowProbe(level, probes, 0, 240, 0, holder);
                        magic.refreshArrowIndex();
                        require(magic.trackedArrowCount() >= 3,
                                        "Entity events and index rebuild include normal, spectral and distant arrows");
                        magic.tickArrows();
                        require(nativeArrow.isRemoved() && spectral.isRemoved(),
                                        "Own and friendly native and spectral arrows are killed inside the shared 16-block sphere");
                        require(!distantArrow.isRemoved(),
                                        "Three arrows and two holders exercise local searches without touching distant arrows");
                        distantArrow.discard();
                        require(magic.trackedArrowCount() == 0,
                                        "Native entity-unload events remove all disposed arrow references");

                        // Type 1 and a live native Polymer beacon have no suppressing effect on type
                        // 4's arrow clear.
                        second.getInventory().clearContent();
                        game.lbc().grantTable(second, "lbc:ported/mystical_artifact");
                        var antimagic = inventoryItem(second, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        second.getInventory().setItem(0, antimagic);
                        triggerNativeInventoryChange(second, antimagic);
                        magic.tick();
                        require(magic.artifactTypes(second) == (1 << 1),
                                        "Nearby holder carries only the default type-1 artifact");
                        var beaconPos = new net.minecraft.core.BlockPos(5, 199, 0);
                        var beaconOld = level.getBlockState(beaconPos);
                        level.setBlock(beaconPos, LbcMagic.MAGIC_BEACON_BLOCK.defaultBlockState(), 3);
                        magic.blockChanged(beaconPos, level.getBlockState(beaconPos));
                        try {
                                var bypassArrow = arrowProbe(level, probes, 5, 200, 0, holder);
                                magic.tickArrows();
                                require(bypassArrow.isRemoved(),
                                                "Nearby type 1 artifact and Polymer beacon do not veto type-4 arrow clearing");
                        } finally {
                                level.setBlock(beaconPos, beaconOld, 3);
                                magic.blockChanged(beaconPos, beaconOld);
                        }

                        var boundary = arrowProbe(level, probes, 16, 200, 0, holder);
                        magic.tickArrows();
                        require(boundary.isRemoved(),
                                        "Arrow exactly sixteen blocks away is inside the inclusive radius");
                        var paused = arrowProbe(level, probes, 2, 200, 0, holder);
                        holder.entityTags().add("time_stopped");
                        magic.tickArrows();
                        require(!paused.isRemoved(), "Source time_stopped pauses the holder's arrow protection");
                        holder.entityTags().remove("time_stopped");
                        magic.tickArrows();
                        require(paused.isRemoved(), "Removing time_stopped restores arrow cleanup on the next tick");
                        var outside = arrowProbe(level, probes, 16.01, 200, 0, holder);
                        magic.tickArrows();
                        require(!outside.isRemoved(), "Arrow 16.01 blocks away survives");
                        outside.setPos(5, 200, 0);
                        magic.tickArrows();
                        require(outside.isRemoved(), "Moving an indexed arrow into range is applied on the next tick");

                        var movedHolderArrow = arrowProbe(level, probes, 20, 200, 0, holder);
                        magic.tickArrows();
                        require(!movedHolderArrow.isRemoved(), "Arrow outside both holder spheres survives");
                        holder.teleportTo(level, 10, 200, 0, java.util.Set.of(), 0, 0, true);
                        magic.tickArrows();
                        require(movedHolderArrow.isRemoved(),
                                        "Moving the type-4 holder into range is applied on the next tick");

                        var stationary = arrowProbe(level, probes, 2, 199, 2, holder);
                        stationary.setOnGround(true);
                        stationary.setDeltaMovement(Vec3.ZERO);
                        magic.tickArrows();
                        require(stationary.isRemoved(), "Grounded stationary native arrows are still removed");

                        var snowball = new net.minecraft.world.entity.projectile.throwableitemprojectile.Snowball(
                                        net.minecraft.world.entity.EntityTypes.SNOWBALL, level);
                        snowball.setOwner(holder);
                        snowball.setPos(1, 200, 1);
                        require(level.addFreshEntity(snowball), "Snowball probe spawns in arena");
                        probes.add(snowball);
                        magic.tickArrows();
                        require(!snowball.isRemoved(),
                                        "Non-arrow projectiles are outside the minecraft:arrows tag and survive");

                        var otherDimension = new net.minecraft.world.entity.projectile.arrow.Arrow(
                                        net.minecraft.world.entity.EntityTypes.ARROW, game.server().overworld());
                        otherDimension.setNoGravity(true);
                        otherDimension.setPos(0, 200, 0);
                        require(game.server().overworld().addFreshEntity(otherDimension),
                                        "Other-dimension arrow probe spawns");
                        probes.add(otherDimension);
                        magic.tickArrows();
                        require(!otherDimension.isRemoved(),
                                        "Arrow in another dimension survives the arena interceptor");

                        // InventoryChangeTrigger is the actual native inventory event hook; its next
                        // game tick must
                        // remove type 4 before arrow eligibility is evaluated.
                        holder.getInventory().setItem(0, ItemStack.EMPTY);
                        triggerNativeInventoryChange(holder, ItemStack.EMPTY);
                        magic.tick();
                        require(magic.artifactTypes(holder) == 0,
                                        "Native inventory event immediately removes the holder's type-4 mask");
                        var unprotected = arrowProbe(level, probes, 1, 200, 0, holder);
                        magic.tickArrows();
                        require(!unprotected.isRemoved(),
                                        "Arrow survives as soon as the native inventory event removes protection");

                        // Creative is a game mode, not an observer role: a living match participant
                        // remains eligible.
                        holder.getInventory().setItem(0, artifact.copy());
                        triggerNativeInventoryChange(holder, artifact);
                        magic.tick();
                        holder.setGameMode(GameType.CREATIVE);
                        var creativeParticipantArrow = arrowProbe(level, probes, 1, 200, 0, holder);
                        magic.tickArrows();
                        require(creativeParticipantArrow.isRemoved(),
                                        "Living Creative participant still uses the arrow artifact");
                        holder.setGameMode(GameType.SURVIVAL);

                        holder.getInventory().setItem(0, ItemStack.EMPTY);
                        triggerNativeInventoryChange(holder, ItemStack.EMPTY);
                        magic.tick();
                        if (!secondWasObserver)
                                game.spectators().enter(second);
                        second.setGameMode(GameType.CREATIVE);
                        second.entityTags().add("developer");
                        var observerArtifact = artifact.copy();
                        second.getInventory().setItem(0, observerArtifact);
                        triggerNativeInventoryChange(second, observerArtifact);
                        magic.tick();
                        require(!game.canUseGameplayItems(second) && magic.artifactTypes(second) == 0,
                                        "Creative observer developer tag cannot activate an arrow holder");
                        var observerArrow = arrowProbe(level, probes, 1, 200, 0, second);
                        magic.tickArrows();
                        require(!observerArrow.isRemoved(), "Arrow near a Creative developer observer survives");
                        if (secondDeveloper)
                                second.entityTags().add("developer");
                        else
                                second.entityTags().remove("developer");
                        if (!secondWasObserver)
                                game.spectators().remove(second);
                        second.setGameMode(GameType.SURVIVAL);

                        // Keep one real eligible holder for the runner's following stop/cleanup
                        // assertion.
                        holder.getInventory().setItem(35, artifact.copy());
                        triggerNativeInventoryChange(holder, artifact);
                        magic.tick();
                        require(magic.artifactTypes(holder) == (1 << 4),
                                        "Final fixture retains a live type-4 holder for stop cleanup");
                } finally {
                        for (var probe : probes)
                                if (!probe.isRemoved())
                                        probe.discard();
                        holder.entityTags().remove("time_stopped");
                        holder.closeContainer();
                        second.closeContainer();
                        if (tableChanged)
                                level.setBlock(tablePos, oldTable, 3);
                        if (game.isObserver(second) && !secondWasObserver)
                                game.spectators().remove(second);
                        if (holderDeveloper)
                                holder.entityTags().add("developer");
                        else
                                holder.entityTags().remove("developer");
                        if (secondDeveloper)
                                second.entityTags().add("developer");
                        else
                                second.entityTags().remove("developer");
                        scoreboard.removePlayerFromTeam(holder.getScoreboardName());
                        scoreboard.removePlayerFromTeam(second.getScoreboardName());
                        if (holderTeam != null)
                                scoreboard.addPlayerToTeam(holder.getScoreboardName(), holderTeam);
                        if (secondTeam != null)
                                scoreboard.addPlayerToTeam(second.getScoreboardName(), secondTeam);
                        scoreboard.removePlayerTeam(probeTeam);
                        holder.setGameMode(holderMode);
                        second.setGameMode(secondMode);
                        holder.teleportTo(holderLevel, holderPosition.x, holderPosition.y, holderPosition.z,
                                        java.util.Set.of(), 0, 0, true);
                        second.teleportTo(secondLevel, secondPosition.x, secondPosition.y, secondPosition.z,
                                        java.util.Set.of(), 0, 0, true);
                        holder.setNoGravity(holderNoGravity);
                        second.setNoGravity(secondNoGravity);
                        holder.getInventory().clearContent();
                        second.getInventory().clearContent();
                        for (int slot = 0; slot < holderInventory.length; slot++)
                                holder.getInventory().setItem(slot, holderInventory[slot]);
                        for (int slot = 0; slot < secondInventory.length; slot++)
                                second.getInventory().setItem(slot, secondInventory[slot]);
                        // Deliberately retain one source item after restoring the bot loadout for stop
                        // cleanup.
                        if (artifactForCleanup.isEmpty()) {
                                game.lbc().grantTable(holder, "lbc:ported/mystical_artifact_arrows");
                                artifactForCleanup = inventoryItem(holder, LbcMagic.MYSTICAL_ARTIFACT).copy();
                        }
                        holder.getInventory().setItem(35, artifactForCleanup);
                        triggerNativeInventoryChange(holder, artifactForCleanup);
                        magic.tick();
                }
                SkyWars2.LOGGER.info("[check] PASS artifact-arrows");
        }

        private static net.minecraft.world.entity.projectile.arrow.Arrow arrowProbe(
                        net.minecraft.server.level.ServerLevel level,
                        java.util.List<net.minecraft.world.entity.Entity> owned,
                        double x, double y, double z, ServerPlayer owner) {
                var arrow = new net.minecraft.world.entity.projectile.arrow.Arrow(
                                net.minecraft.world.entity.EntityTypes.ARROW, level);
                arrow.setOwner(owner);
                arrow.setNoGravity(true);
                arrow.setDeltaMovement(Vec3.ZERO);
                arrow.setPos(x, y, z);
                require(level.addFreshEntity(arrow), "Native arrow probe spawns");
                owned.add(arrow);
                return arrow;
        }

        public static void checkArtifactArrowsCleanup(GameController game) {
                require(game.inLobby(), "Arrow artifact cleanup requires lobby");
                var magic = game.items().magic();
                for (var player : game.server().getPlayerList().getPlayers()) {
                        require(itemCount(player, LbcMagic.MYSTICAL_ARTIFACT) == 0
                                        && magic.artifactTypes(player) == 0,
                                        "Match stop clears type-4 items and their indexed holder state");
                }
                require(magic.trackedArrowCount() == 0, "Arena unload clears the tracked-arrow index");
        }

